"use client";

import * as React from "react";

import { cn } from "@/lib/utils";

import {
  FileViewer,
  FileViewerContent,
  FileViewerHeader,
  FileViewerControls,
  FileViewerTitle,
  FileViewerInset,
  FileViewerProvider,
  FileViewerViewport,
} from "./file-viewer";
import {
  PdfResourceContent,
  type PdfResourceContentProps,
  type PdfViewerContentProps,
} from "./pdf-viewer-content";
import {
  PdfViewerPages,
  PdfViewerProvider,
  type PdfDocumentSource,
} from "./pdf-viewer-context";
import type { PdfViewerHandle } from "./pdf-viewer-types";

export type {
  PageOverlayProps,
  PdfPageAreaTarget,
  PdfPageRenderSource,
  PdfPageRenderStatus,
  PdfPageRenderTiming,
  PdfViewerHandle,
  PdfViewerPerformanceOptions,
} from "./pdf-viewer-types";
export {
  PdfViewerPages,
  PdfViewerProvider,
  usePdfViewerThumbnails,
  type PdfDocumentSource,
} from "./pdf-viewer-context";
export {
  PdfResourceContent,
  type PdfResourceContentProps,
  type PdfViewerContentProps,
} from "./pdf-viewer-content";
export {
  PdfThumbnailRail,
  PdfViewerThumbnails,
  type PdfThumbnailRailProps,
  type PdfViewerThumbnailsProps,
} from "./pdf-viewer-thumbnails";

export interface PdfHighlightProps extends React.ComponentProps<"div"> {
  /** Normalized box, each field a percentage [0, 100] of the page. */
  area: { left: number; top: number; width: number; height: number };
}

export function PdfHighlight({
  area,
  className,
  style,
  ...props
}: PdfHighlightProps) {
  return (
    <div
      data-slot="pdf-highlight"
      className={cn(
        "border-primary/70 bg-primary/12 pointer-events-none absolute z-10 rounded-[2px] border shadow-[0_4px_16px_rgb(0_0_0_/_8%)]",
        className,
      )}
      style={{
        left: `${area.left}%`,
        top: `${area.top}%`,
        width: `${area.width}%`,
        height: `${area.height}%`,
        ...style,
      }}
      {...props}
    />
  );
}

export interface PdfViewerProps extends PdfViewerContentProps {
  /** Canonical PDF source. URL sources preserve PDF.js range-loading behavior. */
  source: PdfDocumentSource;
}

export const PdfViewer = React.forwardRef<PdfViewerHandle, PdfViewerProps>(
  function PdfViewer(props, ref) {
    const {
      source,
      className,
      bare = false,
      controls = true,
      download = true,
      ...pagesProps
    } = props;
    return (
      <FileViewerProvider source={source}>
        <FileViewer
          className={cn(
            "h-full",
            bare && "rounded-none border-0 bg-transparent",
            className,
          )}
        >
          <PdfViewerProvider>
            <FileViewerHeader>
              <FileViewerTitle className="flex-1" />
              {controls ? <FileViewerControls className="ms-auto" /> : null}
            </FileViewerHeader>
            <FileViewerContent>
              <FileViewerInset>
                <FileViewerViewport>
                  <PdfViewerPages
                    {...pagesProps}
                    bare
                    className="h-full"
                    download={download}
                    ref={ref}
                  />
                </FileViewerViewport>
              </FileViewerInset>
            </FileViewerContent>
          </PdfViewerProvider>
        </FileViewer>
      </FileViewerProvider>
    );
  },
);

"use client";

import * as React from "react";

import { clearPdfDocumentResource } from "@/lib/pdf-document-resource";
import { cn } from "@/lib/utils";
import type { ViewerResource } from "@/lib/viewer-resource";
import { ScrollArea } from "@/components/ui/scroll-area";

import {
  usePdfDocumentControlsRegistration,
  usePdfDocumentControlsState,
} from "./pdf-viewer-document-controls";
import { usePdfDocumentLayout } from "./pdf-viewer-document-layout";
import { usePdfDocumentResource } from "./pdf-viewer-document-resource";
import { usePdfDocumentRuntime } from "./pdf-viewer-document-runtime";
import { PdfDocumentPagesLayer } from "./pdf-viewer-pages-layer";
import { PdfViewerFallback } from "./pdf-viewer-states";
import type {
  PageOverlayProps,
  PdfPageRenderTiming,
  PdfViewerHandle,
  PdfViewerPerformanceOptions,
} from "./pdf-viewer-types";
import { useIsClient } from "./use-is-client";
import { ViewerControls } from "./viewer-controls";
import { ViewerErrorBoundary } from "./viewer-error";

export type PdfViewerContentProps = {
  className?: string;
  /** Controlled rendered scale; when omitted the viewer fits page width until manually zoomed. */
  scale?: number;
  /** Initial uncontrolled scale. Leave unset for fit-to-width. */
  defaultScale?: number;
  /** Called when controls request a scale change. `null` means fit width. */
  onScaleChange?: (scale: number | null) => void;
  controls?: boolean;
  /** Show download actions in this viewer's controls/error state. */
  download?: boolean;
  /** Render absolutely-positioned overlays (e.g. bbox citations) on each page. */
  renderPageOverlay?: (props: PageOverlayProps) => React.ReactNode;
  /** Fired with the 1-based page nearest the top of the viewport as you scroll. */
  onVisiblePageChange?: (page: number) => void;
  /** Fired with scroll progress in [0, 1] (for a fine-grained scroll cursor). */
  onScrollProgressChange?: (progress: number) => void;
  /** Reports page render work for profiling and benchmark surfaces. */
  onPageRenderTiming?: (timing: PdfPageRenderTiming) => void;
  /** Retained for callers that still pass benchmark switches; the simple renderer ignores them. */
  performanceOptions?: PdfViewerPerformanceOptions;
  /** Drop the outer border/rounded/background so the viewer fills its container. */
  bare?: boolean;
};

export type PdfResourceContentProps = PdfViewerContentProps & {
  resource: ViewerResource;
};

export const PdfResourceContent = React.forwardRef<
  PdfViewerHandle,
  PdfResourceContentProps
>(function PdfResourceContent(props, ref) {
  const resource = props.resource;
  const isClient = useIsClient();

  if (!isClient) {
    return (
      <PdfViewerFallback
        className={props.className}
        bare={props.bare}
        controls={props.controls}
      />
    );
  }

  return (
    <ViewerErrorBoundary
      className={props.className}
      download={
        props.controls === false || props.download === false
          ? null
          : resource.originalDownload
      }
      format="pdf"
      onRetry={() => clearPdfDocumentResource(resource.content)}
      resetKey={resource.keys.resource}
      sourceKind={resource.sourceKind}
    >
      <React.Suspense
        fallback={
          <PdfViewerFallback
            className={props.className}
            bare={props.bare}
            controls={props.controls}
          />
        }
      >
        <PdfViewerInner {...props} forwardedRef={ref} resource={resource} />
      </React.Suspense>
    </ViewerErrorBoundary>
  );
});

function PdfViewerInner({
  resource,
  className,
  scale: controlledScale,
  defaultScale,
  onScaleChange,
  controls = true,
  download = true,
  renderPageOverlay,
  onVisiblePageChange,
  onScrollProgressChange,
  onPageRenderTiming,
  performanceOptions,
  bare = false,
  forwardedRef,
}: PdfResourceContentProps & {
  forwardedRef?: React.ForwardedRef<PdfViewerHandle>;
}) {
  const content = resource.content;
  const document = usePdfDocumentResource(content);
  const layout = usePdfDocumentLayout({
    controlledScale,
    defaultScale,
    document,
    onScaleChange,
  });
  const runtime = usePdfDocumentRuntime({
    document,
    documentKey: content.key,
    layout,
    onPageRenderTiming,
    onScrollProgressChange,
    onVisiblePageChange,
    performanceOptions,
    renderPageOverlay,
  });
  const controlsState = usePdfDocumentControlsState({
    currentPage: runtime.currentPage,
    download,
    downloadAction: resource.originalDownload,
    fitWidth: layout.fitWidth,
    pageCount: document.numPages,
    resolvedScale: layout.resolvedScale,
    rotateClockwise: layout.rotateClockwise,
    zoomIn: layout.zoomIn,
    zoomOut: layout.zoomOut,
  });

  usePdfDocumentControlsRegistration(controlsState);
  React.useImperativeHandle(
    forwardedRef ?? null,
    () => runtime.handle,
    [runtime.handle],
  );

  return (
    <div
      className={cn(
        "flex min-h-0 flex-col overflow-hidden",
        bare ? "bg-muted/20 h-full" : "bg-muted/30 rounded-xl border",
        className,
      )}
      data-slot="pdf-viewer"
    >
      {controls ? <ViewerControls {...controlsState} /> : null}

      <div className="flex min-h-0 flex-1">
        <div className="relative flex min-h-0 min-w-0 flex-1 flex-col">
          <div className="relative flex min-h-0 flex-1 flex-col">
            <ScrollArea
              className="min-h-0 flex-1"
              viewportRef={runtime.setViewportElement}
              viewportProps={{
                onScroll: runtime.handleViewportScroll,
                style: { overflowAnchor: "none" },
              }}
            >
              <PdfDocumentPagesLayer {...runtime.pagesLayerProps} />
            </ScrollArea>
          </div>
        </div>
      </div>
    </div>
  );
}

"use client";

import * as React from "react";

import type { ViewerResource } from "@/lib/viewer-resource";
import { joinEffectKey } from "@/lib/effect-key";
import { useKeyedMountEffect } from "@/hooks/use-keyed-mount-effect";

import {
  useViewerControlsRegistration,
  type ViewerControlsState,
} from "./viewer-controls";

export function usePdfDocumentControlsState({
  currentPage,
  download,
  downloadAction,
  fitWidth,
  pageCount,
  resolvedScale,
  rotateClockwise,
  zoomIn,
  zoomOut,
}: {
  currentPage: number;
  download: boolean;
  downloadAction: ViewerResource["originalDownload"];
  fitWidth: () => void;
  pageCount: number;
  resolvedScale: number;
  rotateClockwise: () => void;
  zoomIn: () => void;
  zoomOut: () => void;
}): ViewerControlsState {
  return React.useMemo<ViewerControlsState>(
    () => ({
      position: {
        kind: "page",
        current: currentPage,
        total: pageCount,
      },
      zoom: {
        scale: resolvedScale,
        onZoomOut: zoomOut,
        onZoomIn: zoomIn,
        onFit: fitWidth,
      },
      rotate: { onRotate: rotateClockwise },
      downloads: download ? [downloadAction] : [],
    }),
    [
      currentPage,
      download,
      downloadAction,
      fitWidth,
      pageCount,
      resolvedScale,
      rotateClockwise,
      zoomIn,
      zoomOut,
    ],
  );
}

export function usePdfDocumentControlsRegistration(
  controlsState: ViewerControlsState,
) {
  const onControlsChange = useViewerControlsRegistration();

  useKeyedMountEffect(joinEffectKey([onControlsChange, controlsState]), () => {
    if (!onControlsChange) return;
    onControlsChange(controlsState);
    return () => onControlsChange(null);
  });
}

"use client";

import * as React from "react";

import {
  useOptionalFileViewerRendererEnvironment,
  useOptionalFileViewerRendererFrame,
} from "./file-viewer-renderer-frame";
import type { FileViewerDocumentSurfaceMotionResolver } from "./file-viewer-motion-kernel";
import {
  resolveFileViewerRendererLayoutInlineSize,
  type FileViewerRendererFrame,
} from "./file-viewer-renderer-contract";
import { createFileViewerFitWidthSurfaceMotionResolver } from "./file-viewer-fit-width-motion";
import {
  createPdfPageLayout,
  type PdfPageLayoutModel,
} from "./pdf-viewer-layout";
import { usePdfPageSizes } from "./pdf-viewer-page-sizes";
import {
  getPdfFitWidthScale,
  getPdfPageDevicePixelRatio,
  useMeasuredElementWidth,
  usePdfScale,
} from "./pdf-viewer-scale";
import {
  usePdfDocumentRotation,
  usePdfFirstPageSize,
  type PdfDocument,
} from "./pdf-viewer-document-resource";
import type { PdfPageSize } from "./pdf-viewer-types";
import type { ViewerDocumentTransition } from "./viewer-types";

export type PdfDocumentLayoutState = {
  containerRef: React.RefCallback<HTMLDivElement>;
  displayScale: number;
  firstPageSize: PdfPageSize;
  fitWidth: () => void;
  isFitWidth: boolean;
  pageDevicePixelRatio: number;
  pageLayout: PdfPageLayoutModel;
  renderScale: number;
  resolvedScale: number;
  rotateClockwise: () => void;
  rotation: number;
  resolveSurfaceMotionStyle: FileViewerDocumentSurfaceMotionResolver;
  setPageSize: ReturnType<typeof usePdfPageSizes>["setPageSize"];
  transition: ViewerDocumentTransition;
  rendererFrame: FileViewerRendererFrame;
  zoomIn: () => void;
  zoomOut: () => void;
};

export function usePdfDocumentLayout({
  controlledScale,
  defaultScale,
  document,
  onScaleChange,
}: {
  controlledScale?: number;
  defaultScale?: number;
  document: PdfDocument;
  onScaleChange?: (scale: number | null) => void;
}): PdfDocumentLayoutState {
  const firstPageSize = usePdfFirstPageSize(document);
  const rendererEnvironment = useOptionalFileViewerRendererEnvironment();
  const { ref: containerRef, width: containerWidth } = useMeasuredElementWidth({
    enabled: !rendererEnvironment.usesShellGeometry,
  });
  const rendererFrame = useOptionalFileViewerRendererFrame({
    fallbackInlineSize: containerWidth,
  });
  const { rotation, rotateClockwise } = usePdfDocumentRotation(document);
  const fitPageWidth =
    rotation % 180 === 0 ? firstPageSize.width : firstPageSize.height;
  const logicalInlineSize = resolveFileViewerRendererLayoutInlineSize({
    fallbackInlineSize: containerWidth,
    rendererFrame,
  });
  const { resolvedScale, isFitWidth, zoomIn, zoomOut, fitWidth } = usePdfScale({
    controlledScale,
    defaultScale,
    onScaleChange,
    containerWidth: logicalInlineSize,
    fitWidthInlinePadding: 0,
    pageWidth: fitPageWidth,
    resetKey: document,
  });
  const fitWidthDisplayScale = isFitWidth
    ? getPdfFitWidthScale(logicalInlineSize, fitPageWidth, 0)
    : resolvedScale;
  const displayScale = isFitWidth ? fitWidthDisplayScale : resolvedScale;
  const renderScale = getPdfPreparedFitWidthRenderScale({
    enabled: isFitWidth,
    fallbackScale: resolvedScale,
    pageWidth: fitPageWidth,
    rasterInlineSize: getPdfPreparedFitWidthRasterInlineSize(rendererFrame),
  });
  const transition = React.useMemo(
    () =>
      getPdfDocumentTransition({
        isFitWidth,
        rendererTransition: rendererFrame.documentTransition,
      }),
    [isFitWidth, rendererFrame.documentTransition],
  );
  const { pageSizeByNumber, setPageSize } = usePdfPageSizes(document);
  const pageLayout = React.useMemo(
    () =>
      createPdfPageLayout({
        pageCount: document.numPages,
        defaultPageSize: firstPageSize,
        pageSizeByNumber,
        scale: displayScale,
        rotation,
      }),
    [
      document.numPages,
      displayScale,
      firstPageSize,
      pageSizeByNumber,
      rotation,
    ],
  );
  const pageDevicePixelRatio = getPdfPageDevicePixelRatio({
    devicePixelRatio:
      (typeof window !== "undefined" ? window.devicePixelRatio : 1) || 1,
    mode: "settled",
  });
  // The page layout is already at the motion's target width (commit-then-
  // relax), so the resolver reprojects that settled stage to the in-flight
  // visual width with one uniform transform.
  const resolveSurfaceMotionStyle =
    React.useMemo<FileViewerDocumentSurfaceMotionResolver>(
      () =>
        createFileViewerFitWidthSurfaceMotionResolver({
          align: rendererFrame.align,
          isFitWidth,
          stageInlineSize: pageLayout.maxPageWidth,
        }),
      [isFitWidth, pageLayout.maxPageWidth, rendererFrame.align],
    );

  return {
    containerRef,
    displayScale,
    firstPageSize,
    fitWidth,
    isFitWidth,
    pageDevicePixelRatio,
    pageLayout,
    renderScale,
    resolvedScale,
    rotateClockwise,
    rotation,
    resolveSurfaceMotionStyle,
    setPageSize,
    transition,
    rendererFrame,
    zoomIn,
    zoomOut,
  };
}

function getPdfDocumentTransition({
  isFitWidth,
  rendererTransition,
}: {
  isFitWidth: boolean;
  rendererTransition: ViewerDocumentTransition;
}): ViewerDocumentTransition {
  if (isFitWidth && rendererTransition.source === "viewer-shell") {
    return rendererTransition;
  }

  return {
    layoutPolicy: "live",
    scrollPolicy: "preserve",
    source: "none",
    transitionId: null,
    visualPolicy: "none",
  };
}

function getPdfPreparedFitWidthRenderScale({
  enabled,
  fallbackScale,
  pageWidth,
  rasterInlineSize,
}: {
  enabled: boolean;
  fallbackScale: number;
  pageWidth: number;
  rasterInlineSize: number | null;
}) {
  if (!enabled || rasterInlineSize == null) return fallbackScale;

  // Layout commits the target width at slide start; this prepares the
  // backing canvas for the largest width the motion touches so the already-
  // rendered bitmap only ever CSS-rescales — never blanks — while the
  // target-resolution render is pending.
  return getPdfFitWidthScale(rasterInlineSize, pageWidth, 0);
}

function getPdfPreparedFitWidthRasterInlineSize(
  rendererFrame: FileViewerRendererFrame,
) {
  if (!rendererFrame.canToggleSidebar) return rendererFrame.rasterInlineSize;

  const inlineSize = Math.max(
    rendererFrame.rasterInlineSize ?? 0,
    rendererFrame.shellInlineSize ?? 0,
  );

  return inlineSize > 0 ? inlineSize : null;
}

"use client";

import * as React from "react";

import {
  readPdfDocumentResource,
  readPdfPageResource,
  releasePdfDocumentResource,
  retainPdfDocumentResource,
} from "@/lib/pdf-document-resource";
import type { ViewerResource } from "@/lib/viewer-resource";
import { joinEffectKey } from "@/lib/effect-key";
import { useKeyedMountEffect } from "@/hooks/use-keyed-mount-effect";

import type { PdfPageSize } from "./pdf-viewer-types";

export type PdfDocument = ReturnType<typeof readPdfDocumentResource>;
export type PdfDocumentContent = ViewerResource["content"];

export function usePdfDocumentResource(content: PdfDocumentContent) {
  const document = readPdfDocumentResource(content);

  useKeyedMountEffect(joinEffectKey([content, document]), () => {
    retainPdfDocumentResource(content, document);
    return () => releasePdfDocumentResource(content, document);
  });

  return document;
}

export function usePdfFirstPageSize(document: PdfDocument): PdfPageSize {
  const firstPage = readPdfPageResource(document, 1);

  return React.useMemo<PdfPageSize>(() => {
    const viewport = firstPage.getViewport({ scale: 1 });
    return { width: viewport.width, height: viewport.height };
  }, [firstPage]);
}

export function usePdfDocumentRotation(document: PdfDocument) {
  const [rotationState, setRotationState] = React.useState<{
    document: PdfDocument;
    value: number;
  }>(() => ({ document, value: 0 }));
  const rotation = Object.is(rotationState.document, document)
    ? rotationState.value
    : 0;
  const rotateClockwise = React.useCallback(() => {
    setRotationState((state) => ({
      document,
      value:
        ((Object.is(state.document, document) ? state.value : 0) + 90) % 360,
    }));
  }, [document]);

  return { rotation, rotateClockwise };
}

"use client";

import * as React from "react";

import { joinEffectKey } from "@/lib/effect-key";
import { useKeyedLayoutEffect } from "@/hooks/use-keyed-layout-effect";
import { useKeyedMountEffect } from "@/hooks/use-keyed-mount-effect";
import { useMountEffect } from "@/hooks/use-mount-effect";

import {
  findPdfPageByOffset,
  getPdfPageLayout,
  getPdfPhysicalScrollHeight,
} from "./pdf-viewer-layout";
import type { PdfDocumentLayoutState } from "./pdf-viewer-document-layout";
import type { PdfDocument } from "./pdf-viewer-document-resource";
import type { PdfDocumentPagesLayerProps } from "./pdf-viewer-pages-layer";
import {
  FILE_VIEWER_FIT_WIDTH_ANCHOR_BLOCK_PROPERTY,
  captureFileViewerFitWidthAnchorScreenOffset,
  resolveFileViewerFitWidthMotionAnchorBlock,
} from "./file-viewer-fit-width-motion";
import {
  FILE_VIEWER_BEFORE_LAYOUT_MOTION_EVENT,
  readFileViewerBeforeLayoutMotionFrame,
} from "./file-viewer-elements";
import type { FileViewerMotionFrame } from "./file-viewer-motion-plan";
import { usePdfRenderedPageCache } from "./pdf-viewer-render-cache";
import {
  PDF_SCROLLING_PAGE_RENDER_CONCURRENCY,
  usePdfPageRenderScheduler,
} from "./pdf-viewer-render-scheduler";
import { PDF_READING_MARKER_RATIO, usePdfScroll } from "./pdf-viewer-scroll";
import type {
  PageOverlayProps,
  PdfPageRenderTiming,
  PdfViewerHandle,
  PdfViewerPerformanceOptions,
} from "./pdf-viewer-types";
import { usePdfViewerTelemetry } from "./pdf-viewer-telemetry";
import { usePdfPageVirtualization } from "./pdf-viewer-virtualization";

const PDF_SHELL_MOTION_RENDER_RESUME_DELAY_MS = 1400;

export type PdfDocumentRuntimeState = {
  currentPage: number;
  handle: PdfViewerHandle;
  handleViewportScroll: () => void;
  pagesLayerProps: PdfDocumentPagesLayerProps;
  setViewportElement: (element: HTMLDivElement | null) => void;
};

export function usePdfDocumentRuntime({
  document,
  documentKey,
  layout,
  onPageRenderTiming,
  onScrollProgressChange,
  onVisiblePageChange,
  performanceOptions,
  renderPageOverlay,
}: {
  document: PdfDocument;
  documentKey: string;
  layout: PdfDocumentLayoutState;
  onPageRenderTiming?: (timing: PdfPageRenderTiming) => void;
  onScrollProgressChange?: (progress: number) => void;
  onVisiblePageChange?: (page: number) => void;
  performanceOptions?: PdfViewerPerformanceOptions;
  renderPageOverlay?: (props: PageOverlayProps) => React.ReactNode;
}): PdfDocumentRuntimeState {
  const {
    currentPage,
    viewportElement,
    setViewportElement,
    measureScroll,
    handleScroll,
    scrollToPage,
    scrollToPageArea,
    getViewportElement,
    getScrollMetrics,
  } = usePdfScroll({
    isLayoutTransitioning: layout.rendererFrame.isTransitioning,
    pageCount: document.numPages,
    layout: layout.pageLayout,
    transition: layout.transition,
    resetKey: document,
    onVisiblePageChange,
    onScrollProgressChange,
  });
  const documentSurfaceElementRef = React.useRef<HTMLElement | null>(null);
  // The transform's anchor line, in the visual stage's own (physical scroll)
  // coordinates. The idle write is the live reading-marker offset; the
  // slide-start write derives the EXACT fixed point of the commit that just
  // ran (see writeMotionAnchorBlockOffset), so the transform's first frame
  // reproduces the pre-toggle screen even where the rebase clamped.
  const preMotionAnchorRef = React.useRef<{
    pageNumber: number;
    screenRelTop: number;
  } | null>(null);
  const lastAnchorBlockRef = React.useRef<number | null>(null);
  const writeAnchorBlockOffsetPx = React.useCallback((anchorBlock: number) => {
    const documentSurfaceElement = documentSurfaceElementRef.current;
    if (!documentSurfaceElement) return;
    const safeAnchorBlock = Number.isFinite(anchorBlock) ? anchorBlock : 0;
    lastAnchorBlockRef.current = safeAnchorBlock;
    documentSurfaceElement.style.setProperty(
      FILE_VIEWER_FIT_WIDTH_ANCHOR_BLOCK_PROPERTY,
      `${safeAnchorBlock}px`,
    );
  }, []);
  const writeDocumentAnchorBlockOffset = React.useCallback(() => {
    const metrics = getScrollMetrics();
    writeAnchorBlockOffsetPx(
      Math.max(0, metrics.physicalScrollTop) +
        Math.max(0, metrics.viewportHeight) * PDF_READING_MARKER_RATIO,
    );
  }, [getScrollMetrics, writeAnchorBlockOffsetPx]);
  // The transform must pin the exact screen line the slide-start commit
  // preserved, or the first sliding frame drifts off the pre-toggle screen.
  // Rather than assuming anything about the rebase or the layout models,
  // measure the fixed point: capture the marker page's (transform-aware)
  // on-screen top against the OLD layout model before the commit, then solve
  // for the stage anchor that puts the same page top back on that screen line
  // under the NEW layout model at the motion's first-frame scale. Exact in
  // both direct and rebased (paged) scroll spaces, at clamps, across
  // measured/estimated page-size differences, and through mid-flight
  // retargets (the capture applies the in-flight transform it was seen under).
  const writeMotionAnchorBlockOffset = React.useCallback(() => {
    const metrics = getScrollMetrics();
    const preMotionAnchor = preMotionAnchorRef.current;
    const newPageLayout = preMotionAnchor
      ? getPdfPageLayout(layout.pageLayout, preMotionAnchor.pageNumber)
      : null;
    const logicalDelta = metrics.scrollTop - metrics.physicalScrollTop;
    const anchorBlock =
      preMotionAnchor && newPageLayout
        ? resolveFileViewerFitWidthMotionAnchorBlock({
            fromInlineSize: layout.rendererFrame.fromInlineSize,
            probeScreenOffset: preMotionAnchor.screenRelTop,
            probeStageOffset: newPageLayout.offsetTop - logicalDelta,
            scrollTop: metrics.physicalScrollTop,
            stageInlineSize: layout.pageLayout.maxPageWidth,
            toInlineSize: layout.rendererFrame.toInlineSize,
          })
        : null;

    if (anchorBlock == null) {
      writeDocumentAnchorBlockOffset();
      return;
    }
    writeAnchorBlockOffsetPx(anchorBlock);
  }, [
    getScrollMetrics,
    layout.pageLayout,
    layout.rendererFrame.fromInlineSize,
    layout.rendererFrame.toInlineSize,
    writeAnchorBlockOffsetPx,
    writeDocumentAnchorBlockOffset,
  ]);
  const measureBeforeLayoutMotion = React.useCallback(
    (liveFrame: FileViewerMotionFrame | null) => {
      const metrics = getScrollMetrics();
      const markerOffset =
        metrics.scrollTop +
        Math.max(0, metrics.viewportHeight) * PDF_READING_MARKER_RATIO;
      const pageNumber = findPdfPageByOffset(layout.pageLayout, markerOffset);
      const pageLayout = getPdfPageLayout(layout.pageLayout, pageNumber);
      const logicalDelta = metrics.scrollTop - metrics.physicalScrollTop;
      preMotionAnchorRef.current = pageLayout
        ? {
            pageNumber,
            screenRelTop: captureFileViewerFitWidthAnchorScreenOffset({
              lastAnchorBlock: lastAnchorBlockRef.current,
              liveFrame,
              probeStageOffset: pageLayout.offsetTop - logicalDelta,
              scrollTop: metrics.physicalScrollTop,
              stageInlineSize: layout.pageLayout.maxPageWidth,
            }),
          }
        : null;
      measureScroll();
    },
    [getScrollMetrics, layout.pageLayout, measureScroll],
  );
  const measureBeforeLayoutMotionRef = React.useRef(measureBeforeLayoutMotion);
  measureBeforeLayoutMotionRef.current = measureBeforeLayoutMotion;
  const handleBeforeLayoutMotion = React.useCallback((event: Event) => {
    measureBeforeLayoutMotionRef.current(
      readFileViewerBeforeLayoutMotionFrame(event),
    );
  }, []);
  const setDocumentSurfaceElement = React.useCallback(
    (element: HTMLElement | null) => {
      const previousElement = documentSurfaceElementRef.current;
      if (previousElement === element) return;
      previousElement?.removeEventListener(
        FILE_VIEWER_BEFORE_LAYOUT_MOTION_EVENT,
        handleBeforeLayoutMotion,
      );
      documentSurfaceElementRef.current = element;
      if (!element) return;
      element.addEventListener(
        FILE_VIEWER_BEFORE_LAYOUT_MOTION_EVENT,
        handleBeforeLayoutMotion,
      );
      writeDocumentAnchorBlockOffset();
    },
    [handleBeforeLayoutMotion, writeDocumentAnchorBlockOffset],
  );
  const [shouldHoldPageWindowForRaster, setShouldHoldPageWindowForRaster] =
    React.useState(false);
  const {
    scrollPageOffset,
    visiblePageNumbers,
    renderPageNumbers,
    warmPageNumbers,
    preloadPageNumbers,
    measureVisiblePages,
  } = usePdfPageVirtualization({
    getScrollMetrics,
    isLayoutTransitioning: layout.rendererFrame.isTransitioning,
    layout: layout.pageLayout,
    resetKey: document,
    shouldHoldPageWindow: shouldHoldPageWindowForRaster,
    transition: layout.transition,
    viewportElement,
  });
  const renderedPageCache = usePdfRenderedPageCache(document);
  const shouldUseRenderedPageCache =
    performanceOptions?.renderedPageCache !== false;
  const isShellMotionActive =
    layout.rendererFrame.phase !== "idle" ||
    layout.transition.source === "viewer-shell";
  const isPageRenderingPaused =
    usePdfShellMotionRenderPause(isShellMotionActive);
  const {
    activePageNumbers: activeRenderPageNumbers,
    isRenderQueueIdle,
    onPageRenderTiming: handleScheduledPageRenderTiming,
  } = usePdfPageRenderScheduler({
    isPaused: isPageRenderingPaused,
    pageNumbers: visiblePageNumbers,
    warmPageNumbers:
      performanceOptions?.directionAwarePreRender === false
        ? []
        : warmPageNumbers,
    lowPriorityPageNumbers:
      performanceOptions?.directionAwarePreRender === false
        ? []
        : preloadPageNumbers,
    scale: layout.renderScale,
    rotation: layout.rotation,
    devicePixelRatio: layout.pageDevicePixelRatio,
    resetKey: document,
    maxRunning: PDF_SCROLLING_PAGE_RENDER_CONCURRENCY,
    maxLowPriorityRunning:
      performanceOptions?.directionAwarePreRender === false ? 0 : 1,
  });
  useKeyedMountEffect(
    joinEffectKey([isShellMotionActive, isRenderQueueIdle]),
    () => {
      const nextShouldHold =
        isShellMotionActive ||
        (shouldHoldPageWindowForRaster && !isRenderQueueIdle);
      setShouldHoldPageWindowForRaster((previous) =>
        previous === nextShouldHold ? previous : nextShouldHold,
      );
    },
  );
  const handlePageRenderTiming = React.useCallback(
    (timing: PdfPageRenderTiming) => {
      handleScheduledPageRenderTiming(timing);
      onPageRenderTiming?.(timing);
    },
    [handleScheduledPageRenderTiming, onPageRenderTiming],
  );
  const readSettleSnapshot = React.useCallback(() => {
    const metrics = getScrollMetrics();
    const viewportElement = getViewportElement();

    return [
      metrics.scrollTop,
      metrics.physicalScrollTop,
      metrics.scrollPageOffset,
      metrics.viewportHeight,
      viewportElement?.scrollHeight ?? 0,
      viewportElement?.clientHeight ?? 0,
      layout.pageLayout.totalHeight,
      layout.pageLayout.maxPageWidth,
    ];
  }, [
    getScrollMetrics,
    getViewportElement,
    layout.pageLayout.maxPageWidth,
    layout.pageLayout.totalHeight,
  ]);
  usePdfViewerTelemetry({
    activeRenderPageNumbers,
    displayScale: layout.displayScale,
    documentKey,
    getDocumentSurfaceElement: () => documentSurfaceElementRef.current,
    getScrollMetrics,
    getViewportElement,
    layout: layout.pageLayout,
    pageDevicePixelRatio: layout.pageDevicePixelRatio,
    renderPageNumbers,
    renderScale: layout.renderScale,
    rendererFrame: layout.rendererFrame,
    visiblePageNumbers,
  });
  const scrollInteractionElementRef = React.useRef<HTMLDivElement | null>(null);
  const setScrollInteractionElement = React.useCallback(
    (element: HTMLDivElement | null) => {
      scrollInteractionElementRef.current = element;
    },
    [],
  );
  const suspendScrollInteractions = usePdfScrollInteractionSuspension(
    scrollInteractionElementRef,
  );

  useMountEffect(() => () => {
    documentSurfaceElementRef.current?.removeEventListener(
      FILE_VIEWER_BEFORE_LAYOUT_MOTION_EVENT,
      handleBeforeLayoutMotion,
    );
    documentSurfaceElementRef.current = null;
  });

  // displayScale now changes at slide START (commit-then-relax), so this
  // idle re-measure must not clobber the motion's fixed-point anchor; the
  // transitioning effect below owns the anchor for the whole motion.
  useKeyedMountEffect(
    joinEffectKey([
      document.numPages,
      layout.displayScale,
      layout.rendererFrame.isTransitioning,
      layout.rotation,
      measureScroll,
      writeDocumentAnchorBlockOffset,
      viewportElement,
    ]),
    () => {
      measureScroll();
      if (layout.rendererFrame.isTransitioning) return;
      writeDocumentAnchorBlockOffset();
    },
  );

  // The before-layout-motion event fires before the layout jump and captures
  // the pre-toggle scroll; this effect runs inside the slide-start commit
  // AFTER the scroll rebase (hook order puts the scroll layout effect first),
  // so it can pin the transform to the rebase's exact fixed point before the
  // first frame paints.
  useKeyedLayoutEffect(
    joinEffectKey([
      layout.rendererFrame.documentTransition.transitionId,
      layout.rendererFrame.isTransitioning,
      writeMotionAnchorBlockOffset,
    ]),
    () => {
      if (!layout.rendererFrame.isTransitioning) return;
      writeMotionAnchorBlockOffset();
    },
  );

  const handleViewportScroll = React.useCallback(() => {
    suspendScrollInteractions();
    const result = handleScroll();
    if (result?.source === "internal") return;
    // While the shell motion is in flight the anchor is the motion's fixed
    // point; a user scroll mid-slide must not retarget it to the marker.
    if (!layout.rendererFrame.isTransitioning) {
      writeDocumentAnchorBlockOffset();
    }
    measureVisiblePages();
  }, [
    handleScroll,
    layout.rendererFrame.isTransitioning,
    measureVisiblePages,
    suspendScrollInteractions,
    writeDocumentAnchorBlockOffset,
  ]);

  const handle = React.useMemo<PdfViewerHandle>(
    () => ({
      scrollToPage,
      scrollToPageArea,
      getViewportElement,
    }),
    [getViewportElement, scrollToPage, scrollToPageArea],
  );

  return {
    currentPage,
    handle,
    handleViewportScroll,
    pagesLayerProps: {
      activeRenderPageNumbers,
      containerRef: layout.containerRef,
      devicePixelRatio: layout.pageDevicePixelRatio,
      document,
      documentAlign: layout.rendererFrame.align,
      documentKey,
      isLayoutTransitioning: layout.rendererFrame.isTransitioning,
      layout: layout.pageLayout,
      onPageRenderTiming: handlePageRenderTiming,
      physicalScrollHeight: getPdfPhysicalScrollHeight({
        totalHeight: layout.pageLayout.totalHeight,
        viewportHeight: viewportElement?.clientHeight ?? 0,
      }),
      readSettleSnapshot,
      renderCache: shouldUseRenderedPageCache ? renderedPageCache : undefined,
      renderPageNumbers,
      renderPageOverlay,
      renderScale: layout.renderScale,
      resolveSurfaceMotionStyle: layout.resolveSurfaceMotionStyle,
      rotation: layout.rotation,
      scale: layout.displayScale,
      scrollPageOffset,
      setDocumentSurfaceElement,
      setScrollInteractionElement,
      setPageSize: layout.setPageSize,
      viewportHeight: viewportElement?.clientHeight ?? 0,
      visiblePageNumbers,
    },
    setViewportElement,
  };
}

function usePdfShellMotionRenderPause(isShellMotionActive: boolean) {
  const [isSettling, setIsSettling] = React.useState(false);

  useKeyedMountEffect(joinEffectKey([isShellMotionActive, isSettling]), () => {
    if (isShellMotionActive) {
      setIsSettling(true);
      return;
    }

    if (!isSettling) return;

    const timer = setTimeout(() => {
      setIsSettling(false);
    }, PDF_SHELL_MOTION_RENDER_RESUME_DELAY_MS);

    return () => clearTimeout(timer);
  });

  return isShellMotionActive || isSettling;
}

function usePdfScrollInteractionSuspension(
  scrollInteractionElementRef: React.RefObject<HTMLElement | null>,
) {
  const restoreTimeoutRef = React.useRef<number | null>(null);
  const scrollElementRef = React.useRef<HTMLElement | null>(null);

  const suspendScrollInteractions = React.useCallback(() => {
    const scrollElement = scrollInteractionElementRef.current;
    if (!scrollElement) return;

    if (restoreTimeoutRef.current !== null) {
      window.clearTimeout(restoreTimeoutRef.current);
    }
    scrollElementRef.current = scrollElement;
    scrollElement.style.pointerEvents = "none";
    if (isMobileSafari()) {
      scrollElement.style.overflowX = "hidden";
    }
    restoreTimeoutRef.current = window.setTimeout(() => {
      restoreTimeoutRef.current = null;
      restorePdfScrollInteractions(scrollElementRef.current);
      scrollElementRef.current = null;
    }, 120);
  }, [scrollInteractionElementRef]);

  useMountEffect(() => () => {
    if (restoreTimeoutRef.current !== null) {
      window.clearTimeout(restoreTimeoutRef.current);
      restoreTimeoutRef.current = null;
    }
    restorePdfScrollInteractions(scrollElementRef.current);
    scrollElementRef.current = null;
  });

  return suspendScrollInteractions;
}

function restorePdfScrollInteractions(element: HTMLElement | null) {
  if (!element) return;
  element.style.removeProperty("pointer-events");
  element.style.removeProperty("overflow-x");
}

function isMobileSafari() {
  if (typeof navigator === "undefined") return false;
  const userAgent = navigator.userAgent;
  return (
    /Safari/i.test(userAgent) &&
    /Mobile/i.test(userAgent) &&
    !/CriOS|FxiOS|EdgiOS/i.test(userAgent)
  );
}

"use client";

import * as React from "react";

import { useKeyedLayoutEffect } from "@/hooks/use-keyed-layout-effect";
import { joinEffectKey } from "@/lib/effect-key";
import { cn } from "@/lib/utils";

import type { FileViewerDocumentAlign } from "./file-viewer-renderer-contract";
import type {
  FileViewerDocumentSurfaceMotionResolver,
  FileViewerDocumentSurfaceSettleSnapshotReader,
} from "./file-viewer-motion-kernel";
import { useOptionalFileViewerRendererEnvironment } from "./file-viewer-renderer-frame";
import {
  getPdfRenderedPageWindow,
  type PdfPageLayoutModel,
} from "./pdf-viewer-layout";
import { PdfPage } from "./pdf-viewer-page";
import type { PdfRenderedPageCache } from "./pdf-viewer-render-cache";
import { PageSkeleton } from "./pdf-viewer-states";
import type {
  PageOverlayProps,
  PdfPageRenderTiming,
  PdfPageSize,
} from "./pdf-viewer-types";
import type { PdfDocument } from "./pdf-viewer-document-resource";

export type PdfDocumentPagesLayerProps = {
  activeRenderPageNumbers: readonly number[];
  containerRef: React.RefCallback<HTMLDivElement>;
  devicePixelRatio: number;
  document: PdfDocument;
  documentAlign: FileViewerDocumentAlign | null;
  documentKey: string;
  isLayoutTransitioning: boolean;
  layout: PdfPageLayoutModel;
  onPageRenderTiming?: (timing: PdfPageRenderTiming) => void;
  physicalScrollHeight: number;
  renderCache?: PdfRenderedPageCache;
  renderPageNumbers: readonly number[];
  readSettleSnapshot: FileViewerDocumentSurfaceSettleSnapshotReader;
  renderPageOverlay?: (props: PageOverlayProps) => React.ReactNode;
  renderScale: number;
  resolveSurfaceMotionStyle: FileViewerDocumentSurfaceMotionResolver;
  rotation: number;
  scale: number;
  scrollPageOffset: number;
  setDocumentSurfaceElement: React.RefCallback<HTMLElement>;
  setScrollInteractionElement: React.RefCallback<HTMLDivElement>;
  setPageSize: (pageNumber: number, size: PdfPageSize) => void;
  viewportHeight: number;
  visiblePageNumbers: readonly number[];
};

export function PdfDocumentPagesLayer({
  activeRenderPageNumbers,
  containerRef,
  devicePixelRatio,
  document,
  documentAlign,
  documentKey,
  isLayoutTransitioning,
  layout,
  onPageRenderTiming,
  physicalScrollHeight,
  renderCache,
  renderPageNumbers,
  readSettleSnapshot,
  renderPageOverlay,
  renderScale,
  resolveSurfaceMotionStyle,
  rotation,
  scale,
  scrollPageOffset,
  setDocumentSurfaceElement,
  setScrollInteractionElement,
  setPageSize,
  viewportHeight,
  visiblePageNumbers,
}: PdfDocumentPagesLayerProps) {
  const visiblePageNumberSet = React.useMemo(
    () => new Set(visiblePageNumbers),
    [visiblePageNumbers],
  );
  const { registerDocumentSurface } =
    useOptionalFileViewerRendererEnvironment();
  const [visualStageElement, setVisualStageElementState] =
    React.useState<HTMLElement | null>(null);
  const setVisualStageElement = React.useCallback(
    (element: HTMLElement | null) => {
      setVisualStageElementState((previousElement) =>
        previousElement === element ? previousElement : element,
      );
      setDocumentSurfaceElement(element);
    },
    [setDocumentSurfaceElement],
  );
  const documentSurfaceKey = visualStageElement
    ? joinEffectKey([
        registerDocumentSurface,
        readSettleSnapshot,
        resolveSurfaceMotionStyle,
        visualStageElement,
      ])
    : null;
  useKeyedLayoutEffect(documentSurfaceKey, () => {
    if (!visualStageElement) return;
    return registerDocumentSurface({
      element: visualStageElement,
      readSettleSnapshot,
      resolveMotionStyle: resolveSurfaceMotionStyle,
    });
  });
  const activeRenderPageNumberSet = React.useMemo(
    () => new Set(activeRenderPageNumbers),
    [activeRenderPageNumbers],
  );
  const renderedWindow = React.useMemo(
    () =>
      getPdfRenderedPageWindow({
        layout,
        pageNumbers: renderPageNumbers,
        physicalScrollHeight,
        scrollPageOffset,
        viewportHeight,
      }),
    [
      layout,
      physicalScrollHeight,
      renderPageNumbers,
      scrollPageOffset,
      viewportHeight,
    ],
  );
  const isInsideDocumentFrame = documentAlign !== null;
  const scrollRangeStyle = {
    contain: "layout size style",
    height: physicalScrollHeight,
    minWidth: layout.maxPageWidth,
    width: layout.maxPageWidth,
  } satisfies React.CSSProperties;
  const visualClipStyle = {
    contain: "paint style",
    overflow: "clip",
  } satisfies React.CSSProperties;
  const visualStageStyle = {
    height: physicalScrollHeight,
    minWidth: layout.maxPageWidth,
    width: layout.maxPageWidth,
  } satisfies React.CSSProperties;

  const documentContent = (
    <div
      data-slot="pdf-viewer-scroll-range"
      className={cn("relative", getPdfDocumentFrameAlignClass(documentAlign))}
      style={scrollRangeStyle}
    >
      <div
        data-slot="pdf-viewer-visual-clip"
        data-layout-transitioning={isLayoutTransitioning ? "" : undefined}
        className="absolute inset-0"
        style={visualClipStyle}
      >
        <div
          ref={setVisualStageElement}
          data-slot="pdf-viewer-visual-stage"
          className="relative"
          style={visualStageStyle}
        >
          {renderedWindow ? (
            <div
              ref={setScrollInteractionElement}
              data-slot="pdf-page-window"
              className="absolute inset-0"
              style={{
                contain: "layout style",
                isolation: "isolate",
              }}
            >
              {/* Pages sit at their settled layout positions for the whole
                  motion (commit-then-relax); the kernel's single surface
                  transform on the visual stage is the only in-flight style. */}
              {renderedWindow.pages.map((page) => (
                <div
                  key={page.pageNumber}
                  className="absolute left-1/2 flex -translate-x-1/2 items-start justify-center"
                  data-layout-transitioning={
                    isLayoutTransitioning ? "" : undefined
                  }
                  data-slot="pdf-page-slot"
                  data-page-number={page.pageNumber}
                  data-visible={
                    visiblePageNumberSet.has(page.pageNumber) ? "" : undefined
                  }
                  style={{
                    top: renderedWindow.beforeHeight + page.windowTop,
                    width: page.width,
                    height: page.height,
                  }}
                >
                  {activeRenderPageNumberSet.has(page.pageNumber) ? (
                    <React.Suspense fallback={<PageSkeleton />}>
                      <PdfPage
                        document={document}
                        documentKey={documentKey}
                        pageNumber={page.pageNumber}
                        scale={scale}
                        renderScale={renderScale}
                        isLayoutTransitioning={isLayoutTransitioning}
                        rotation={rotation}
                        devicePixelRatio={devicePixelRatio}
                        renderCache={renderCache}
                        renderOverlay={renderPageOverlay}
                        onRenderTiming={onPageRenderTiming}
                        onSize={setPageSize}
                      />
                    </React.Suspense>
                  ) : (
                    <PageSkeleton />
                  )}
                </div>
              ))}
            </div>
          ) : null}
        </div>
      </div>
    </div>
  );

  return (
    <div
      ref={containerRef}
      data-slot="pdf-viewer-fit-width-measure"
      className={cn(
        "relative min-w-0",
        isInsideDocumentFrame && "h-full w-full",
      )}
    >
      {documentContent}
    </div>
  );
}

function getPdfDocumentFrameAlignClass(align: FileViewerDocumentAlign | null) {
  switch (align) {
    case "center":
    case null:
      return "mx-auto";
    case "end":
      return "ml-auto";
    case "start":
      return "mr-auto";
  }
}

import * as React from "react";

import type { PdfPageRenderTiming } from "./pdf-viewer-types";
import { useKeyedMountEffect } from "@/hooks/use-keyed-mount-effect";
import { useKeyedLayoutEffect } from "@/hooks/use-keyed-layout-effect";
import { joinEffectKey } from "@/lib/effect-key";

export const PDF_PAGE_RENDER_CONCURRENCY = 2;
export const PDF_SCROLLING_PAGE_RENDER_CONCURRENCY = 4;

type PdfPageRenderKeyInput = {
  pageNumber: number;
  scale: number;
  rotation: number;
  devicePixelRatio: number;
};

type PdfPageRenderRequest = PdfPageRenderKeyInput;

export function getPdfPageRenderKey({
  pageNumber,
  scale,
  rotation,
  devicePixelRatio,
}: PdfPageRenderKeyInput) {
  return `${pageNumber}:${scale}:${rotation}:${devicePixelRatio}`;
}

export function usePdfPageRenderScheduler({
  isPaused = false,
  pageNumbers,
  warmPageNumbers = [],
  lowPriorityPageNumbers = [],
  scale,
  rotation,
  devicePixelRatio,
  resetKey,
  maxRunning = PDF_PAGE_RENDER_CONCURRENCY,
  maxLowPriorityRunning = 1,
}: {
  pageNumbers: readonly number[];
  warmPageNumbers?: readonly number[];
  lowPriorityPageNumbers?: readonly number[];
  isPaused?: boolean;
  scale: number;
  rotation: number;
  devicePixelRatio: number;
  resetKey: unknown;
  maxRunning?: number;
  maxLowPriorityRunning?: number;
}) {
  const requestedRenders = React.useMemo<PdfPageRenderRequest[]>(
    () =>
      mergePdfPageNumbers(pageNumbers).map((pageNumber) => ({
        pageNumber,
        scale,
        rotation,
        devicePixelRatio,
      })),
    [devicePixelRatio, pageNumbers, rotation, scale],
  );
  const warmRequestedRenders = React.useMemo<PdfPageRenderRequest[]>(() => {
    const primaryPageNumberSet = new Set(pageNumbers);
    return mergePdfPageNumbers(warmPageNumbers)
      .filter((pageNumber) => !primaryPageNumberSet.has(pageNumber))
      .map((pageNumber) => ({
        pageNumber,
        scale,
        rotation,
        devicePixelRatio,
      }));
  }, [devicePixelRatio, pageNumbers, rotation, scale, warmPageNumbers]);
  const lowPriorityRequestedRenders = React.useMemo<
    PdfPageRenderRequest[]
  >(() => {
    const primaryPageNumberSet = new Set(pageNumbers);
    const warmPageNumberSet = new Set(warmPageNumbers);
    return mergePdfPageNumbers(lowPriorityPageNumbers)
      .filter(
        (pageNumber) =>
          !primaryPageNumberSet.has(pageNumber) &&
          !warmPageNumberSet.has(pageNumber),
      )
      .map((pageNumber) => ({
        pageNumber,
        scale,
        rotation,
        devicePixelRatio,
      }));
  }, [
    devicePixelRatio,
    lowPriorityPageNumbers,
    pageNumbers,
    rotation,
    scale,
    warmPageNumbers,
  ]);
  const allRequestedRenders = React.useMemo(
    () => [
      ...requestedRenders,
      ...warmRequestedRenders,
      ...lowPriorityRequestedRenders,
    ],
    [lowPriorityRequestedRenders, requestedRenders, warmRequestedRenders],
  );
  const requestedRendersRef = React.useRef(allRequestedRenders);
  const resetKeyRef = React.useRef(resetKey);
  useKeyedLayoutEffect(joinEffectKey([allRequestedRenders, resetKey]), () => {
    requestedRendersRef.current = allRequestedRenders;
    resetKeyRef.current = resetKey;
  });

  const [state, setState] = React.useState<{
    resetKey: unknown;
    renderedByKey: ReadonlyMap<string, PdfPageRenderRequest>;
  }>(() => ({ resetKey, renderedByKey: new Map() }));
  const emptyRenderedByKey = React.useMemo<
    ReadonlyMap<string, PdfPageRenderRequest>
  >(() => new Map(), []);
  const renderedByKey = Object.is(state.resetKey, resetKey)
    ? state.renderedByKey
    : emptyRenderedByKey;

  useKeyedMountEffect(joinEffectKey([allRequestedRenders, resetKey]), () => {
    setState((previousState) => {
      if (!Object.is(previousState.resetKey, resetKey)) {
        return { resetKey, renderedByKey: new Map() };
      }

      const renderedByKey = new Map<string, PdfPageRenderRequest>();
      for (const [key, rendered] of previousState.renderedByKey) {
        if (
          allRequestedRenders.some((request) =>
            doesRenderedPageKeepRequestMounted(rendered, request),
          )
        ) {
          renderedByKey.set(key, rendered);
        }
      }

      return areMapsEqual(previousState.renderedByKey, renderedByKey)
        ? previousState
        : { resetKey, renderedByKey };
    });
  });

  const renderWindow = React.useMemo(() => {
    const renderedPageNumbers: number[] = [];
    const stalePageNumbers: number[] = [];
    const pendingPageNumbers: number[] = [];
    const warmRenderedPageNumbers: number[] = [];
    const warmStalePageNumbers: number[] = [];
    const warmPendingPageNumbers: number[] = [];
    const lowPriorityRenderedPageNumbers: number[] = [];
    const lowPriorityStalePageNumbers: number[] = [];
    const lowPriorityPendingPageNumbers: number[] = [];

    for (const request of requestedRenders) {
      if (isRenderRequestSatisfied(request, renderedByKey)) {
        renderedPageNumbers.push(request.pageNumber);
      } else if (isRenderRequestMountedStale(request, renderedByKey)) {
        stalePageNumbers.push(request.pageNumber);
      } else {
        pendingPageNumbers.push(request.pageNumber);
      }
    }
    for (const request of warmRequestedRenders) {
      if (isRenderRequestSatisfied(request, renderedByKey)) {
        warmRenderedPageNumbers.push(request.pageNumber);
      } else if (isRenderRequestMountedStale(request, renderedByKey)) {
        warmStalePageNumbers.push(request.pageNumber);
      } else {
        warmPendingPageNumbers.push(request.pageNumber);
      }
    }
    for (const request of lowPriorityRequestedRenders) {
      if (isRenderRequestSatisfied(request, renderedByKey)) {
        lowPriorityRenderedPageNumbers.push(request.pageNumber);
      } else if (isRenderRequestMountedStale(request, renderedByKey)) {
        lowPriorityStalePageNumbers.push(request.pageNumber);
      } else {
        lowPriorityPendingPageNumbers.push(request.pageNumber);
      }
    }

    const maxPrimaryRunning = Math.max(1, maxRunning);
    const activePrimaryPendingCount = isPaused
      ? 0
      : Math.min(pendingPageNumbers.length, maxPrimaryRunning);
    const activePrimaryPageNumbers = [
      ...renderedPageNumbers,
      ...stalePageNumbers,
      ...pendingPageNumbers.slice(0, activePrimaryPendingCount),
    ];
    const remainingWarmSlots = Math.max(
      0,
      maxRunning - activePrimaryPendingCount,
    );
    const activeWarmPendingCount = isPaused
      ? 0
      : Math.min(warmPendingPageNumbers.length, remainingWarmSlots);
    const activeWarmPageNumbers = [
      ...warmRenderedPageNumbers,
      ...warmStalePageNumbers,
      ...warmPendingPageNumbers.slice(0, activeWarmPendingCount),
    ];
    const activeLowPriorityPageNumbers =
      isPaused || activePrimaryPendingCount + activeWarmPendingCount > 0
        ? [...lowPriorityRenderedPageNumbers, ...lowPriorityStalePageNumbers]
        : [
            ...lowPriorityRenderedPageNumbers,
            ...lowPriorityStalePageNumbers,
            ...lowPriorityPendingPageNumbers.slice(
              0,
              Math.max(0, maxLowPriorityRunning),
            ),
          ];

    return {
      activePageNumbers: mergePdfPageNumbers([
        ...activePrimaryPageNumbers,
        ...activeWarmPageNumbers,
        ...activeLowPriorityPageNumbers,
      ]),
      pendingPageNumbers: mergePdfPageNumbers([
        ...pendingPageNumbers,
        ...warmPendingPageNumbers,
        ...lowPriorityPendingPageNumbers,
      ]),
    };
  }, [
    isPaused,
    lowPriorityRequestedRenders,
    maxLowPriorityRunning,
    maxRunning,
    renderedByKey,
    requestedRenders,
    warmRequestedRenders,
  ]);

  const onPageRenderTiming = React.useCallback(
    (timing: PdfPageRenderTiming) => {
      const key = getPdfPageRenderKey(timing);

      setState((previousState) => {
        const resetKey = resetKeyRef.current;
        const previousRenderedByKey = Object.is(
          previousState.resetKey,
          resetKey,
        )
          ? previousState.renderedByKey
          : new Map<string, PdfPageRenderRequest>();
        const nextRenderedByKey = new Map(previousRenderedByKey);
        const rendered: PdfPageRenderRequest = {
          pageNumber: timing.pageNumber,
          scale: timing.scale,
          rotation: timing.rotation,
          devicePixelRatio: timing.devicePixelRatio,
        };

        if (
          timing.status === "rendered" &&
          requestedRendersRef.current.some((request) =>
            doesRenderedPageKeepRequestMounted(rendered, request),
          )
        ) {
          nextRenderedByKey.set(key, rendered);
        } else {
          nextRenderedByKey.delete(key);
        }

        return areMapsEqual(previousRenderedByKey, nextRenderedByKey)
          ? previousState
          : { resetKey, renderedByKey: nextRenderedByKey };
      });
    },
    [],
  );

  return {
    activePageNumbers: renderWindow.activePageNumbers,
    isRenderQueueIdle: renderWindow.pendingPageNumbers.length === 0,
    onPageRenderTiming,
    pendingPageNumbers: renderWindow.pendingPageNumbers,
  };
}

function mergePdfPageNumbers(pageNumbers: readonly number[]) {
  return [...new Set(pageNumbers)].sort((left, right) => left - right);
}

function isRenderRequestSatisfied(
  request: PdfPageRenderRequest,
  renderedByKey: ReadonlyMap<string, PdfPageRenderRequest>,
) {
  for (const rendered of renderedByKey.values()) {
    if (doesRenderedPageSatisfyRequest(rendered, request)) return true;
  }
  return false;
}

function isRenderRequestMountedStale(
  request: PdfPageRenderRequest,
  renderedByKey: ReadonlyMap<string, PdfPageRenderRequest>,
) {
  for (const rendered of renderedByKey.values()) {
    if (
      !doesRenderedPageSatisfyRequest(rendered, request) &&
      doesRenderedPageKeepRequestMounted(rendered, request)
    ) {
      return true;
    }
  }
  return false;
}

function doesRenderedPageSatisfyRequest(
  rendered: PdfPageRenderRequest,
  request: PdfPageRenderRequest,
) {
  return (
    rendered.pageNumber === request.pageNumber &&
    rendered.scale === request.scale &&
    rendered.rotation === request.rotation &&
    rendered.devicePixelRatio >= request.devicePixelRatio
  );
}

function doesRenderedPageKeepRequestMounted(
  rendered: PdfPageRenderRequest,
  request: PdfPageRenderRequest,
) {
  return (
    rendered.pageNumber === request.pageNumber &&
    rendered.rotation === request.rotation
  );
}

function areMapsEqual(
  left: ReadonlyMap<string, PdfPageRenderRequest>,
  right: ReadonlyMap<string, PdfPageRenderRequest>,
) {
  if (left.size !== right.size) return false;
  for (const [key, value] of left) {
    if (right.get(key) !== value) return false;
  }
  return true;
}

import { useKeyedMountEffect } from "@/hooks/use-keyed-mount-effect";
import { joinEffectKey } from "@/lib/effect-key";

export const PDF_RENDERED_PAGE_CACHE_MAX_ENTRIES = 16;
export const PDF_RENDERED_PAGE_CACHE_MAX_PIXELS = 24_000_000;
// Only close lower-resolution renders of the same page may be stretched as
// resize previews; thumbnail-resolution bitmaps below this ratio would blur.
export const PDF_RENDERED_PAGE_PREVIEW_MIN_SCALE_RATIO = 0.5;

export type PdfRenderedPageSignature = {
  documentKey: string;
  pageNumber: number;
  scale: number;
  rotation: number;
  devicePixelRatio: number;
  viewportWidth: number;
  viewportHeight: number;
};

export type PdfRenderedPageCache = {
  clock: number;
  entries: Map<string, PdfRenderedPageCacheEntry>;
  resetKey: unknown;
};

export type PdfRenderedPageCacheEntry = PdfRenderedPageSignature & {
  canvas: HTMLCanvasElement;
  lastUsed: number;
  pixels: number;
};

type PdfRenderedPageCacheRecord = {
  cache: PdfRenderedPageCache;
  retainCount: number;
  resetKey: unknown;
};

const objectCacheRecords = new WeakMap<object, PdfRenderedPageCacheRecord>();
const primitiveCacheRecords = new Map<unknown, PdfRenderedPageCacheRecord>();

export function createPdfRenderedPageCache(
  resetKey: unknown,
): PdfRenderedPageCache {
  return {
    clock: 0,
    entries: new Map(),
    resetKey,
  };
}

export function usePdfRenderedPageCache(resetKey: unknown) {
  const record = getPdfRenderedPageCacheRecord(resetKey);

  useKeyedMountEffect(joinEffectKey([record]), () => {
    record.retainCount += 1;
    return () => releasePdfRenderedPageCacheRecord(record);
  });

  return record.cache;
}

export function readPdfRenderedPageCache(
  cache: PdfRenderedPageCache | undefined,
  requested: PdfRenderedPageSignature,
) {
  if (!cache) return null;

  let bestEntry: PdfRenderedPageCacheEntry | null = null;
  for (const entry of cache.entries.values()) {
    if (!doesRenderedPageSatisfyRequest(entry, requested)) continue;
    if (
      !bestEntry ||
      entry.pixels < bestEntry.pixels ||
      (entry.pixels === bestEntry.pixels && entry.lastUsed > bestEntry.lastUsed)
    ) {
      bestEntry = entry;
    }
  }

  if (!bestEntry) return null;
  cache.clock += 1;
  bestEntry.lastUsed = cache.clock;
  return bestEntry;
}

export function readPdfRenderedPageCachePreview(
  cache: PdfRenderedPageCache | undefined,
  requested: PdfRenderedPageSignature,
) {
  if (!cache) return null;

  let bestEntry: PdfRenderedPageCacheEntry | null = null;
  for (const entry of cache.entries.values()) {
    if (!doesRenderedPageMatchPreview(entry, requested)) continue;
    if (!bestEntry || entry.pixels > bestEntry.pixels) {
      bestEntry = entry;
    }
  }

  if (!bestEntry) return null;
  cache.clock += 1;
  bestEntry.lastUsed = cache.clock;
  return bestEntry;
}

export function writePdfRenderedPageCache({
  cache,
  rendered,
  sourceCanvas,
}: {
  cache: PdfRenderedPageCache | undefined;
  rendered: PdfRenderedPageSignature;
  sourceCanvas: HTMLCanvasElement;
}) {
  if (!cache || sourceCanvas.width <= 0 || sourceCanvas.height <= 0) return;

  const canvas = document.createElement("canvas");
  canvas.width = sourceCanvas.width;
  canvas.height = sourceCanvas.height;
  const context = canvas.getContext("2d");
  if (!context || typeof context.drawImage !== "function") return;

  context.drawImage(sourceCanvas, 0, 0);
  cache.clock += 1;
  const key = getPdfRenderedPageCacheKey(rendered);
  cache.entries.set(key, {
    ...rendered,
    canvas,
    lastUsed: cache.clock,
    pixels: canvas.width * canvas.height,
  });
  evictPdfRenderedPageCache(cache, key);
}

export function clearPdfRenderedPageCache(cache: PdfRenderedPageCache) {
  cache.clock = 0;
  cache.entries.clear();
}

function evictPdfRenderedPageCache(
  cache: PdfRenderedPageCache,
  retainedKey: string,
) {
  let totalPixels = getTotalCachedPixels(cache);

  while (
    cache.entries.size > PDF_RENDERED_PAGE_CACHE_MAX_ENTRIES ||
    totalPixels > PDF_RENDERED_PAGE_CACHE_MAX_PIXELS
  ) {
    const evicted = findPdfRenderedPageCacheEviction(cache, retainedKey);
    if (!evicted) return;

    totalPixels -= evicted.entry.pixels;
    cache.entries.delete(evicted.key);
  }
}

function findPdfRenderedPageCacheEviction(
  cache: PdfRenderedPageCache,
  retainedKey: string,
) {
  let oldest: { key: string; entry: PdfRenderedPageCacheEntry } | null = null;

  for (const [key, entry] of cache.entries) {
    if (key === retainedKey) continue;
    if (!oldest || entry.lastUsed < oldest.entry.lastUsed) {
      oldest = { key, entry };
    }
  }

  return oldest;
}

function getTotalCachedPixels(cache: PdfRenderedPageCache) {
  let pixels = 0;
  for (const entry of cache.entries.values()) {
    pixels += entry.pixels;
  }
  return pixels;
}

function doesRenderedPageSatisfyRequest(
  rendered: PdfRenderedPageSignature,
  requested: PdfRenderedPageSignature,
) {
  return (
    rendered.documentKey === requested.documentKey &&
    rendered.pageNumber === requested.pageNumber &&
    rendered.rotation === requested.rotation &&
    rendered.scale >= requested.scale &&
    rendered.viewportWidth >= requested.viewportWidth &&
    rendered.viewportHeight >= requested.viewportHeight &&
    hasMatchingPageAspectRatio(rendered, requested) &&
    rendered.devicePixelRatio >= requested.devicePixelRatio
  );
}

function doesRenderedPageMatchPreview(
  rendered: PdfRenderedPageSignature,
  requested: PdfRenderedPageSignature,
) {
  return (
    rendered.documentKey === requested.documentKey &&
    rendered.pageNumber === requested.pageNumber &&
    rendered.rotation === requested.rotation &&
    rendered.viewportWidth >=
      requested.viewportWidth * PDF_RENDERED_PAGE_PREVIEW_MIN_SCALE_RATIO &&
    rendered.viewportHeight >=
      requested.viewportHeight * PDF_RENDERED_PAGE_PREVIEW_MIN_SCALE_RATIO &&
    hasMatchingPageAspectRatio(rendered, requested)
  );
}

function getPdfRenderedPageCacheKey(rendered: PdfRenderedPageSignature) {
  return [
    rendered.documentKey,
    rendered.pageNumber,
    rendered.scale,
    rendered.rotation,
    rendered.devicePixelRatio,
    rendered.viewportWidth,
    rendered.viewportHeight,
  ].join(":");
}

function getPdfRenderedPageCacheRecord(
  resetKey: unknown,
): PdfRenderedPageCacheRecord {
  const records = isObjectCacheKey(resetKey)
    ? objectCacheRecords
    : primitiveCacheRecords;
  const cached = records.get(resetKey as never);
  if (cached) return cached;

  const record: PdfRenderedPageCacheRecord = {
    cache: createPdfRenderedPageCache(resetKey),
    retainCount: 0,
    resetKey,
  };
  records.set(resetKey as never, record);
  return record;
}

function releasePdfRenderedPageCacheRecord(record: PdfRenderedPageCacheRecord) {
  record.retainCount = Math.max(0, record.retainCount - 1);
  if (record.retainCount > 0) return;

  clearPdfRenderedPageCache(record.cache);
  if (isObjectCacheKey(record.resetKey)) {
    objectCacheRecords.delete(record.resetKey);
  } else {
    primitiveCacheRecords.delete(record.resetKey);
  }
}

function isObjectCacheKey(value: unknown): value is object {
  return (
    (typeof value === "object" && value !== null) || typeof value === "function"
  );
}

function hasMatchingPageAspectRatio(
  rendered: PdfRenderedPageSignature,
  requested: PdfRenderedPageSignature,
) {
  const renderedRatio = rendered.viewportWidth / rendered.viewportHeight;
  const requestedRatio = requested.viewportWidth / requested.viewportHeight;
  return Math.abs(renderedRatio - requestedRatio) < 0.0001;
}

"use client";

import * as React from "react";

import { useKeyedMountEffect } from "@/hooks/use-keyed-mount-effect";
import { getPdfPageResource } from "@/lib/pdf-document-resource";
import type { PdfDocumentProxy } from "@/lib/pdf-document-types";

import { joinEffectKey } from "@/lib/effect-key";

export const PDF_PAGE_METRIC_CONCURRENCY = 4;

export type PdfPageMetric = {
  pageNumber: number;
  width: number;
  height: number;
  rotation: number;
};

export type PdfPageMetrics = {
  metricByPageNumber: ReadonlyMap<number, PdfPageMetric>;
  requestPageMetrics: (pageNumbers: Iterable<number>) => void;
  status: "idle" | "loading";
};

type MetricControllerState = {
  documentKey: unknown;
  pageCount: number;
  metricByPageNumber: ReadonlyMap<number, PdfPageMetric>;
  queuedPageNumbers: readonly number[];
  loadingPageNumbers: ReadonlySet<number>;
  error: unknown;
};

type MetricAction =
  | { type: "reset"; documentKey: unknown; pageCount: number }
  | {
      type: "enqueue";
      documentKey: unknown;
      pageCount: number;
      pageNumbers: readonly number[];
    }
  | { type: "start"; documentKey: unknown; pageNumbers: readonly number[] }
  | { type: "resolve"; documentKey: unknown; metric: PdfPageMetric }
  | { type: "reject"; documentKey: unknown; error: unknown };

export function usePdfPageMetrics(
  document: PdfDocumentProxy,
  resetKey: unknown,
): PdfPageMetrics {
  const workerSequenceRef = React.useRef(0);
  const [state, dispatch] = React.useReducer(
    metricControllerReducer,
    undefined,
    () => createMetricControllerState(resetKey, document.numPages),
  );
  const visibleState = Object.is(state.documentKey, resetKey)
    ? state
    : createMetricControllerState(resetKey, document.numPages);
  const status =
    visibleState.queuedPageNumbers.length > 0 ||
    visibleState.loadingPageNumbers.size > 0
      ? "loading"
      : "idle";

  const resetEffectKey = joinEffectKey(["reset", document, resetKey]);
  useKeyedMountEffect(resetEffectKey, () => {
    workerSequenceRef.current += 1;
    dispatch({
      type: "reset",
      documentKey: resetKey,
      pageCount: document.numPages,
    });
  });

  const requestPageMetrics = React.useCallback(
    (pageNumbers: Iterable<number>) => {
      const requestedPageNumbers = Array.from(pageNumbers)
        .map((pageNumber) =>
          normalizePdfPageNumber(pageNumber, document.numPages),
        )
        .filter((pageNumber): pageNumber is number => pageNumber != null);

      if (requestedPageNumbers.length === 0) return;

      dispatch({
        type: "enqueue",
        documentKey: resetKey,
        pageCount: document.numPages,
        pageNumbers: requestedPageNumbers,
      });
    },
    [document.numPages, resetKey],
  );

  const loadEffectKey = joinEffectKey([
    "load",
    document,
    resetKey,
    state.documentKey,
    state.error,
    state.loadingPageNumbers,
    state.queuedPageNumbers,
  ]);
  useKeyedMountEffect(loadEffectKey, () => {
    if (!Object.is(state.documentKey, resetKey)) return;
    if (state.error) return;

    const availableSlotCount =
      PDF_PAGE_METRIC_CONCURRENCY - state.loadingPageNumbers.size;
    if (availableSlotCount <= 0) return;

    const startingPageNumbers = state.queuedPageNumbers.slice(
      0,
      availableSlotCount,
    );
    if (startingPageNumbers.length === 0) return;

    const sequence = workerSequenceRef.current;
    dispatch({
      type: "start",
      documentKey: resetKey,
      pageNumbers: startingPageNumbers,
    });

    for (const pageNumber of startingPageNumbers) {
      void getPdfPageResource(document, pageNumber, {
        retainRejected: true,
      })
        .then((page) => {
          if (workerSequenceRef.current !== sequence) return;

          const rotation = page.rotate ?? 0;
          const viewport = page.getViewport({ scale: 1, rotation });
          dispatch({
            type: "resolve",
            documentKey: resetKey,
            metric: {
              pageNumber,
              width: viewport.width,
              height: viewport.height,
              rotation,
            },
          });
        })
        .catch((error: unknown) => {
          if (workerSequenceRef.current !== sequence) return;
          dispatch({ type: "reject", documentKey: resetKey, error });
        });
    }
  });

  if (visibleState.error) throw visibleState.error;

  return {
    metricByPageNumber: visibleState.metricByPageNumber,
    requestPageMetrics,
    status,
  };
}

function metricControllerReducer(
  state: MetricControllerState,
  action: MetricAction,
): MetricControllerState {
  switch (action.type) {
    case "reset":
      return createMetricControllerState(action.documentKey, action.pageCount);
    case "enqueue":
      return enqueuePageMetrics(state, action);
    case "start":
      return startPageMetrics(state, action);
    case "resolve":
      return resolvePageMetric(state, action);
    case "reject":
      if (!Object.is(state.documentKey, action.documentKey)) return state;
      return {
        ...state,
        queuedPageNumbers: [],
        loadingPageNumbers: new Set(),
        error: action.error,
      };
  }
}

function createMetricControllerState(
  documentKey: unknown,
  pageCount: number,
): MetricControllerState {
  return {
    documentKey,
    pageCount,
    metricByPageNumber: new Map(),
    queuedPageNumbers: [],
    loadingPageNumbers: new Set(),
    error: null,
  };
}

function enqueuePageMetrics(
  state: MetricControllerState,
  action: Extract<MetricAction, { type: "enqueue" }>,
): MetricControllerState {
  const baseState = Object.is(state.documentKey, action.documentKey)
    ? state
    : createMetricControllerState(action.documentKey, action.pageCount);
  const queuedPageNumberSet = new Set(baseState.queuedPageNumbers);
  const queuedPageNumbers = [...baseState.queuedPageNumbers];

  for (const pageNumber of action.pageNumbers) {
    if (baseState.metricByPageNumber.has(pageNumber)) continue;
    if (baseState.loadingPageNumbers.has(pageNumber)) continue;
    if (queuedPageNumberSet.has(pageNumber)) continue;

    queuedPageNumberSet.add(pageNumber);
    queuedPageNumbers.push(pageNumber);
  }

  if (queuedPageNumbers.length === baseState.queuedPageNumbers.length) {
    return baseState;
  }

  return {
    ...baseState,
    queuedPageNumbers,
  };
}

function startPageMetrics(
  state: MetricControllerState,
  action: Extract<MetricAction, { type: "start" }>,
): MetricControllerState {
  if (!Object.is(state.documentKey, action.documentKey)) return state;

  const startingPageNumberSet = new Set(action.pageNumbers);
  const queuedPageNumbers = state.queuedPageNumbers.filter(
    (pageNumber) => !startingPageNumberSet.has(pageNumber),
  );
  const loadingPageNumbers = new Set(state.loadingPageNumbers);

  for (const pageNumber of action.pageNumbers) {
    if (state.metricByPageNumber.has(pageNumber)) continue;
    loadingPageNumbers.add(pageNumber);
  }

  return {
    ...state,
    queuedPageNumbers,
    loadingPageNumbers,
  };
}

function resolvePageMetric(
  state: MetricControllerState,
  action: Extract<MetricAction, { type: "resolve" }>,
): MetricControllerState {
  if (!Object.is(state.documentKey, action.documentKey)) return state;

  const loadingPageNumbers = new Set(state.loadingPageNumbers);
  loadingPageNumbers.delete(action.metric.pageNumber);

  const metricByPageNumber = new Map(state.metricByPageNumber);
  metricByPageNumber.set(action.metric.pageNumber, action.metric);

  return {
    ...state,
    metricByPageNumber,
    loadingPageNumbers,
  };
}

function normalizePdfPageNumber(pageNumber: number, pageCount: number) {
  return Number.isInteger(pageNumber) &&
    pageNumber >= 1 &&
    pageNumber <= pageCount
    ? pageNumber
    : null;
}

"use client";

import * as React from "react";

import {
  createViewerResource,
  type ViewerResource,
} from "@/lib/viewer-resource";
import type { BlobViewerSource, UrlViewerSource } from "@/lib/viewer-source";

import { useOptionalFileViewerResource } from "./file-viewer-resource-state";
import {
  PdfResourceContent,
  type PdfViewerContentProps,
} from "./pdf-viewer-content";
import type { PdfViewerHandle } from "./pdf-viewer-types";

export type PdfDocumentSource = UrlViewerSource | BlobViewerSource;

export type PdfViewerThumbnailsState = {
  currentPage: number | null;
  onSelectPage: ((page: number) => void) | undefined;
  resource: ViewerResource;
};

export interface PdfViewerProviderProps {
  source?: PdfDocumentSource;
  children: React.ReactNode;
}

type PdfViewerContextValue = {
  currentPage: number | null;
  isViewerReady: boolean;
  resource: ViewerResource;
  setCurrentPage: (page: number | null) => void;
  setViewerHandle: (handle: PdfViewerHandle | null) => void;
  viewerHandleRef: React.RefObject<PdfViewerHandle | null>;
};

type PdfDocumentPagesState = {
  resource: ViewerResource;
  setCurrentPage: (page: number | null) => void;
  setViewerHandle: (handle: PdfViewerHandle | null) => void;
};

const PdfViewerContext = React.createContext<PdfViewerContextValue | null>(
  null,
);

const PDF_THUMBNAIL_SMOOTH_SCROLL_MAX_PAGE_DELTA = 8;

function usePdfViewerContext(
  consumer = "PdfViewer parts",
): PdfViewerContextValue {
  const context = React.useContext(PdfViewerContext);
  if (!context) {
    throw new Error(`${consumer} must be used within PdfViewerProvider.`);
  }
  return context;
}

export function usePdfViewerThumbnails(): PdfViewerThumbnailsState {
  const { currentPage, isViewerReady, resource, viewerHandleRef } =
    usePdfViewerContext("usePdfViewerThumbnails");
  const onSelectPage = React.useCallback(
    (page: number) => {
      const pageDelta = currentPage == null ? 0 : Math.abs(page - currentPage);
      viewerHandleRef.current?.scrollToPage(page, {
        behavior:
          pageDelta > PDF_THUMBNAIL_SMOOTH_SCROLL_MAX_PAGE_DELTA
            ? "auto"
            : "smooth",
      });
    },
    [currentPage, viewerHandleRef],
  );

  return {
    currentPage,
    onSelectPage: isViewerReady ? onSelectPage : undefined,
    resource,
  };
}

function usePdfDocumentPagesState(): PdfDocumentPagesState {
  const { resource, setCurrentPage, setViewerHandle } = usePdfViewerContext();
  return { resource, setCurrentPage, setViewerHandle };
}

export const PdfViewerPages = React.forwardRef<
  PdfViewerHandle,
  PdfViewerContentProps
>(function PdfViewerPages(props, ref) {
  const { resource, setCurrentPage, setViewerHandle } =
    usePdfDocumentPagesState();
  const { onVisiblePageChange } = props;
  const handleVisiblePageChange = React.useCallback(
    (page: number) => {
      setCurrentPage(page);
      onVisiblePageChange?.(page);
    },
    [onVisiblePageChange, setCurrentPage],
  );
  const handleRef = React.useCallback(
    (handle: PdfViewerHandle | null) => {
      setViewerHandle(handle);
      if (typeof ref === "function") {
        ref(handle);
        return;
      }
      if (ref) ref.current = handle;
    },
    [ref, setViewerHandle],
  );

  return (
    <PdfResourceContent
      {...props}
      ref={handleRef}
      resource={resource}
      controls={false}
      onVisiblePageChange={handleVisiblePageChange}
    />
  );
});

export function PdfViewerProvider({
  source,
  children,
}: PdfViewerProviderProps) {
  const fileViewerResource = useOptionalFileViewerResource();
  const resource = React.useMemo(() => {
    if (source) return createViewerResource(source);
    if (fileViewerResource) return fileViewerResource;
    throw new Error(
      "PdfViewerProvider requires a source or enclosing FileViewer.",
    );
  }, [fileViewerResource, source]);
  const [currentPage, setCurrentPage] = React.useState<number | null>(null);
  const viewerHandleRef = React.useRef<PdfViewerHandle | null>(null);
  const [isViewerReady, setIsViewerReady] = React.useState(false);
  const setViewerHandle = React.useCallback((handle: PdfViewerHandle | null) => {
    viewerHandleRef.current = handle;
    const nextIsViewerReady = handle !== null;
    setIsViewerReady((currentIsViewerReady) =>
      currentIsViewerReady === nextIsViewerReady
        ? currentIsViewerReady
        : nextIsViewerReady,
    );
  }, []);
  const value = React.useMemo<PdfViewerContextValue>(
    () => ({
      currentPage,
      isViewerReady,
      resource,
      setCurrentPage,
      setViewerHandle,
      viewerHandleRef,
    }),
    [currentPage, isViewerReady, resource, setViewerHandle],
  );

  return (
    <PdfViewerContext.Provider value={value}>
      {children}
    </PdfViewerContext.Provider>
  );
}

