import * as React from "react";

export const MIN_PDF_SCALE = 0.25;
export const MAX_PDF_SCALE = 5;
export const PDF_ZOOM_STEP = 1.2;
export const PDF_PAGE_HORIZONTAL_PADDING = 32;
export const PDF_PAGE_SETTLED_MAX_DEVICE_PIXEL_RATIO = 2;
export const PDF_PAGE_SCROLLING_MAX_DEVICE_PIXEL_RATIO =
  PDF_PAGE_SETTLED_MAX_DEVICE_PIXEL_RATIO;

export type PdfPageDprMode = "scrolling" | "settled";

export function clamp(value: number, min: number, max: number) {
  return Math.min(max, Math.max(min, value));
}

export function clampPdfScale(value: number) {
  // NaN has no ordering, so default it to 1; ±Infinity clamps to the bounds
  // like any large/small finite value (e.g. 1e9 → MAX, -1e9 → MIN).
  if (Number.isNaN(value)) return 1;
  return clamp(value, MIN_PDF_SCALE, MAX_PDF_SCALE);
}

export function getPdfFitWidthScale(
  containerWidth: number | null,
  pageWidth: number,
  inlinePadding = PDF_PAGE_HORIZONTAL_PADDING,
) {
  if (!containerWidth || !Number.isFinite(containerWidth) || pageWidth <= 0) {
    return 1;
  }
  return clampPdfScale((containerWidth - inlinePadding) / pageWidth);
}

export function getPdfPageDevicePixelRatio({
  devicePixelRatio,
  mode: _mode,
}: {
  devicePixelRatio: number;
  mode: PdfPageDprMode;
}) {
  const normalizedDevicePixelRatio =
    Number.isFinite(devicePixelRatio) && devicePixelRatio > 0
      ? devicePixelRatio
      : 1;
  return Math.min(
    normalizedDevicePixelRatio,
    PDF_PAGE_SETTLED_MAX_DEVICE_PIXEL_RATIO,
  );
}

export function useMeasuredElementWidth({
  enabled = true,
}: {
  enabled?: boolean;
} = {}) {
  const [element, setElement] = React.useState<HTMLDivElement | null>(null);
  const [width, setWidth] = React.useState<number | null>(null);

  const ref = React.useCallback((nextElement: HTMLDivElement | null) => {
    setElement(nextElement);
  }, []);

  React.useLayoutEffect(() => {
    if (!enabled || !element) {
      if (!enabled) setWidth(null);
      return;
    }

    let frame = 0;
    const measure = () => {
      if (frame) return;
      frame = requestAnimationFrame(() => {
        frame = 0;
        setWidth(element.clientWidth);
      });
    };

    measure();
    if (typeof ResizeObserver === "undefined") {
      return () => {
        if (frame) cancelAnimationFrame(frame);
      };
    }

    const observer = new ResizeObserver(measure);

    observer.observe(element);
    return () => {
      if (frame) cancelAnimationFrame(frame);
      observer.disconnect();
    };
  }, [element, enabled]);

  return { ref, width };
}

export function usePdfScale({
  controlledScale,
  defaultScale,
  onScaleChange,
  containerWidth,
  pageWidth,
  fitWidthInlinePadding,
  resetKey,
}: {
  controlledScale?: number;
  defaultScale?: number;
  onScaleChange?: (scale: number | null) => void;
  containerWidth: number | null;
  fitWidthInlinePadding?: number;
  pageWidth: number;
  resetKey?: unknown;
}) {
  const initialRequestedScale =
    defaultScale == null ? null : clampPdfScale(defaultScale);
  const [uncontrolledScaleState, setUncontrolledScaleState] = React.useState<{
    resetKey: unknown;
    requestedScale: number | null;
  }>(() => ({
    resetKey,
    requestedScale: initialRequestedScale,
  }));
  const uncontrolledRequestedScale = Object.is(
    uncontrolledScaleState.resetKey,
    resetKey,
  )
    ? uncontrolledScaleState.requestedScale
    : initialRequestedScale;
  const isControlledScale = controlledScale !== undefined;
  const isFitWidth = !isControlledScale && uncontrolledRequestedScale == null;
  const fitWidthScale = getPdfFitWidthScale(
    containerWidth,
    pageWidth,
    fitWidthInlinePadding,
  );
  const resolvedScale = isControlledScale
    ? clampPdfScale(controlledScale)
    : (uncontrolledRequestedScale ?? fitWidthScale);

  const setRequestedScale = React.useCallback(
    (nextScale: number | null) => {
      const normalizedScale =
        nextScale == null ? null : clampPdfScale(nextScale);
      if (isControlledScale) {
        onScaleChange?.(normalizedScale);
        return;
      }
      setUncontrolledScaleState((previousState) =>
        Object.is(previousState.resetKey, resetKey) &&
        previousState.requestedScale === normalizedScale
          ? previousState
          : { resetKey, requestedScale: normalizedScale },
      );
    },
    [isControlledScale, onScaleChange, resetKey],
  );

  const zoomIn = React.useCallback(
    () => setRequestedScale(resolvedScale * PDF_ZOOM_STEP),
    [resolvedScale, setRequestedScale],
  );
  const zoomOut = React.useCallback(
    () => setRequestedScale(resolvedScale / PDF_ZOOM_STEP),
    [resolvedScale, setRequestedScale],
  );
  const fitWidth = React.useCallback(
    () => setRequestedScale(null),
    [setRequestedScale],
  );

  return {
    resolvedScale,
    isFitWidth,
    zoomIn,
    zoomOut,
    fitWidth,
  };
}

import * as React from "react";
import { useMountEffect } from "@/hooks/use-mount-effect";

import {
  findPdfPageByOffset,
  getPdfLogicalScrollTop,
  getPdfPageLayout,
  getPdfPhysicalScrollHeight,
  resolvePdfPhysicalScrollPosition,
  type PdfPageLayoutModel,
} from "./pdf-viewer-layout";
import { clamp } from "./pdf-viewer-scale";
import type { PdfPageAreaTarget } from "./pdf-viewer-types";
import type {
  ViewerDocumentScrollMapper,
  ViewerDocumentScrollMetrics,
  ViewerDocumentScrollTargetResolver,
  ViewerDocumentLayoutModel,
  ViewerDocumentTransition,
} from "./viewer-types";
import { useViewerDocumentScroll } from "./viewer-document-scroll";
import { useKeyedMountEffect } from "@/hooks/use-keyed-mount-effect";
import { useKeyedLayoutEffect } from "@/hooks/use-keyed-layout-effect";
import { joinEffectKey } from "@/lib/effect-key";

const PDF_SCROLL_TARGET_HEADROOM = 48;
const PDF_SCROLL_TARGET_INLINE_HEADROOM = 32;
export const PDF_READING_MARKER_RATIO = 0.2;
const PDF_READING_BOUNDARY_SNAP_PX = 24;
const PDF_SCROLL_IDLE_MS = 120;

type PdfReadingAnchor =
  | {
      kind: "top";
    }
  | {
      kind: "page-boundary";
      pageNumber: number;
      topInViewport: number;
    }
  | {
      kind: "page";
      pageNumber: number;
      yPercent: number;
    };

type PdfResolvedPageAreaTarget = {
  top: number;
  left?: number;
};

type PdfScrollMetrics = {
  physicalScrollHeight: number;
  physicalScrollTop: number;
  scrollPageOffset: number;
  scrollTop: number;
  viewportHeight: number;
};

type PdfDocumentLayoutModel = ViewerDocumentLayoutModel<PdfReadingAnchor>;

const PDF_DOCUMENT_SCROLL_MAPPER: ViewerDocumentScrollMapper = {
  getLogicalScrollTop: ({
    blockSize,
    physicalScrollTop,
    scrollPageOffset,
    viewportBlockSize,
  }) =>
    getPdfLogicalScrollTop({
      physicalScrollTop,
      scrollPageOffset,
      totalHeight: blockSize,
      viewportHeight: viewportBlockSize,
    }),
  getPhysicalScrollSize: ({ blockSize, viewportBlockSize }) =>
    getPdfPhysicalScrollHeight({
      totalHeight: blockSize,
      viewportHeight: viewportBlockSize,
    }),
  resolvePhysicalScrollPosition: ({
    blockSize,
    logicalScrollTop,
    scrollPageOffset,
    viewportBlockSize,
  }) =>
    resolvePdfPhysicalScrollPosition({
      logicalScrollTop,
      scrollPageOffset,
      totalHeight: blockSize,
      viewportHeight: viewportBlockSize,
    }),
};

export function usePdfScrollActivity() {
  const [isScrolling, setIsScrolling] = React.useState(false);
  const [scrollDirection, setScrollDirection] = React.useState(1);
  const idleTimeoutRef = React.useRef<ReturnType<typeof setTimeout> | null>(
    null,
  );
  const scrollTopRef = React.useRef(0);

  const handleScrollActivity = React.useCallback((viewport?: HTMLElement) => {
    const scrollTop = viewport?.scrollTop ?? scrollTopRef.current;
    const previousScrollTop = scrollTopRef.current;
    if (scrollTop > previousScrollTop) {
      setScrollDirection(1);
    } else if (scrollTop < previousScrollTop) {
      setScrollDirection(-1);
    }
    scrollTopRef.current = scrollTop;

    if (idleTimeoutRef.current) {
      clearTimeout(idleTimeoutRef.current);
    }

    setIsScrolling(true);
    idleTimeoutRef.current = setTimeout(() => {
      idleTimeoutRef.current = null;
      setIsScrolling(false);
    }, PDF_SCROLL_IDLE_MS);
  }, []);

  useMountEffect(() => () => {
    if (idleTimeoutRef.current) clearTimeout(idleTimeoutRef.current);
  });

  return { isScrolling, scrollDirection, handleScrollActivity };
}

// The reading marker's block offset in document coordinates. Layout and
// scroll are committed to their settled values at slide start (commit-then-
// relax), so no settle prediction is needed — the marker is always read
// against live geometry.
export function getPdfReadingMarkerBlockOffset({
  scrollTop,
  viewportHeight,
}: {
  scrollTop: number;
  viewportHeight: number;
}) {
  const safeScrollTop = Number.isFinite(scrollTop) ? Math.max(0, scrollTop) : 0;
  const safeViewportHeight = Number.isFinite(viewportHeight)
    ? Math.max(0, viewportHeight)
    : 0;
  return safeScrollTop + safeViewportHeight * PDF_READING_MARKER_RATIO;
}

export function usePdfScroll({
  isLayoutTransitioning = false,
  pageCount,
  layout,
  transition,
  resetKey,
  onVisiblePageChange,
  onScrollProgressChange,
}: {
  isLayoutTransitioning?: boolean;
  pageCount: number;
  layout: PdfPageLayoutModel;
  transition?: ViewerDocumentTransition;
  resetKey?: unknown;
  onVisiblePageChange?: (page: number) => void;
  onScrollProgressChange?: (progress: number) => void;
}) {
  const lastReportedPageRef = React.useRef(0);
  const scrollFrameRef = React.useRef(0);
  const didMountResetEffectRef = React.useRef(false);
  const [currentPageState, setCurrentPageState] = React.useState<{
    resetKey: unknown;
    page: number;
  }>(() => ({ resetKey, page: 1 }));
  const currentPage = Object.is(currentPageState.resetKey, resetKey)
    ? currentPageState.page
    : 1;
  const documentLayout = React.useMemo(
    () =>
      createPdfDocumentLayoutModel({
        isTransitioning: isLayoutTransitioning,
        layout,
        transition,
      }),
    [isLayoutTransitioning, layout, transition],
  );
  const resolveScrollTarget = React.useCallback<
    ViewerDocumentScrollTargetResolver<PdfReadingAnchor, PdfPageAreaTarget>
  >(
    ({ scrollTop, target, viewportElement }) =>
      getPdfPageAreaScrollTarget(
        viewportElement,
        layout,
        pageCount,
        target,
        scrollTop,
      ),
    [layout, pageCount],
  );
  const documentScroll = useViewerDocumentScroll({
    copyScrollTarget: copyPdfPageAreaTarget,
    layout: documentLayout,
    resetKey,
    resolveScrollTarget,
    scrollMapper: PDF_DOCUMENT_SCROLL_MAPPER,
  });
  const getScrollMetrics = React.useCallback(() => {
    const metrics = documentScroll.getScrollMetrics();
    return toPdfScrollMetrics(metrics);
  }, [documentScroll]);
  const viewportElement = documentScroll.viewportElement;

  const resetCurrentPage = React.useCallback(() => {
    lastReportedPageRef.current = 0;
    setCurrentPageState((previousState) =>
      Object.is(previousState.resetKey, resetKey) && previousState.page === 1
        ? previousState
        : { resetKey, page: 1 },
    );
  }, [resetKey]);

  const measureScroll = React.useCallback(() => {
    scrollFrameRef.current = 0;
    const viewportElement = documentScroll.getViewportElement();
    if (!viewportElement) return;

    const metrics = documentScroll.syncScrollPosition();
    if (!metrics) return;
    const isRebased = metrics.physicalScrollSize < documentLayout.blockSize;
    const scrollable = isRebased
      ? documentLayout.blockSize - metrics.viewportBlockSize
      : viewportElement.scrollHeight - metrics.viewportBlockSize;
    const progress =
      scrollable > 0
        ? clamp(
            (isRebased ? metrics.scrollTop : viewportElement.scrollTop) /
              scrollable,
            0,
            1,
          )
        : 0;
    onScrollProgressChange?.(progress);

    const markerOffset = getPdfReadingMarkerBlockOffset({
      scrollTop: metrics.scrollTop,
      viewportHeight: metrics.viewportBlockSize,
    });
    const visiblePage = findPdfPageByOffset(layout, markerOffset);
    if (
      visiblePage >= 1 &&
      visiblePage <= pageCount &&
      visiblePage !== lastReportedPageRef.current
    ) {
      lastReportedPageRef.current = visiblePage;
      setCurrentPageState((previousState) =>
        Object.is(previousState.resetKey, resetKey) &&
        previousState.page === visiblePage
          ? previousState
          : { resetKey, page: visiblePage },
      );
      onVisiblePageChange?.(visiblePage);
    }
  }, [
    documentLayout,
    documentScroll,
    layout,
    onScrollProgressChange,
    onVisiblePageChange,
    pageCount,
    resetKey,
  ]);
  const measureScrollRef = React.useRef(measureScroll);
  useKeyedLayoutEffect(joinEffectKey([measureScroll]), () => {
    measureScrollRef.current = measureScroll;
  });

  const handleScroll = React.useCallback(() => {
    const result = documentScroll.handleScroll();
    if (result.source === "internal") return result;

    if (scrollFrameRef.current) return result;
    scrollFrameRef.current = requestAnimationFrame(() =>
      measureScrollRef.current(),
    );
    return result;
  }, [documentScroll]);

  useKeyedMountEffect(joinEffectKey([resetCurrentPage]), () => {
    if (!didMountResetEffectRef.current) {
      didMountResetEffectRef.current = true;
      return;
    }
    resetCurrentPage();
  });

  const scrollToPageArea = React.useCallback(
    (target: PdfPageAreaTarget, options?: ScrollToOptions) => {
      documentScroll.scrollToTarget(target, options);
    },
    [documentScroll],
  );
  const scrollToPage = React.useCallback(
    (pageNumber: number, options?: ScrollToOptions) => {
      scrollToPageArea({ pageNumber, top: 0 }, options);
    },
    [scrollToPageArea],
  );
  useKeyedMountEffect(joinEffectKey([measureScroll]), () => {
    if (scrollFrameRef.current) {
      cancelAnimationFrame(scrollFrameRef.current);
      scrollFrameRef.current = 0;
    }
  });

  useMountEffect(() => () => {
    if (scrollFrameRef.current) cancelAnimationFrame(scrollFrameRef.current);
  });

  return {
    currentPage,
    viewportElement,
    setViewportElement: documentScroll.setViewportElement,
    measureScroll,
    handleScroll,
    getScrollMetrics,
    scrollToPage,
    scrollToPageArea,
    getViewportElement: documentScroll.getViewportElement,
  };
}

function getPdfPageAreaScrollTarget(
  viewportElement: HTMLDivElement,
  layout: PdfPageLayoutModel,
  pageCount: number,
  target: PdfPageAreaTarget,
  scrollTop: number,
): PdfResolvedPageAreaTarget | null {
  const pageNumber = target.pageNumber;
  if (pageNumber < 1 || pageNumber > pageCount) return null;

  const pageLayout = getPdfPageLayout(layout, pageNumber);
  if (!pageLayout) return null;

  const requestedTop = Number.isNaN(target.top) ? 0 : target.top;
  const targetTopPercent = clamp(requestedTop, 0, 100);
  const targetHeightPercent = normalizeOptionalPercent(target.height);
  const areaTop =
    pageLayout.offsetTop + (targetTopPercent / 100) * pageLayout.height;
  const areaBottom =
    areaTop + ((targetHeightPercent ?? 0) / 100) * pageLayout.height;
  const visibleTop = scrollTop + PDF_SCROLL_TARGET_HEADROOM;
  const visibleBottom =
    scrollTop + viewportElement.clientHeight - PDF_SCROLL_TARGET_HEADROOM;
  let targetTop = areaTop - PDF_SCROLL_TARGET_HEADROOM;

  if (targetHeightPercent != null && areaTop >= visibleTop) {
    targetTop =
      areaBottom > visibleBottom
        ? areaBottom - viewportElement.clientHeight + PDF_SCROLL_TARGET_HEADROOM
        : scrollTop;
  }

  const targetLeft = getPdfPageAreaScrollLeft(viewportElement, layout, {
    pageLayout,
    left: target.left,
    width: target.width,
  });

  return {
    top: Math.max(0, targetTop),
    ...(targetLeft == null ? null : { left: targetLeft }),
  };
}

function copyPdfPageAreaTarget(target: PdfPageAreaTarget): PdfPageAreaTarget {
  return {
    pageNumber: target.pageNumber,
    top: target.top,
    left: target.left,
    width: target.width,
    height: target.height,
  };
}

function getPdfPageAreaScrollLeft(
  viewportElement: HTMLDivElement,
  layout: PdfPageLayoutModel,
  target: {
    pageLayout: NonNullable<ReturnType<typeof getPdfPageLayout>>;
    left?: number;
    width?: number;
  },
) {
  const targetLeftPercent = normalizeOptionalPercent(target.left);
  const targetWidthPercent = normalizeOptionalPercent(target.width);
  if (targetLeftPercent == null || targetWidthPercent == null) return undefined;

  const documentInlineOffset = Math.max(
    0,
    (viewportElement.clientWidth - layout.maxPageWidth) / 2,
  );
  const pageInlineOffset =
    documentInlineOffset + (layout.maxPageWidth - target.pageLayout.width) / 2;
  const areaLeft =
    pageInlineOffset + (targetLeftPercent / 100) * target.pageLayout.width;
  const areaRight =
    areaLeft + (targetWidthPercent / 100) * target.pageLayout.width;
  const visibleLeft =
    viewportElement.scrollLeft + PDF_SCROLL_TARGET_INLINE_HEADROOM;
  const visibleRight =
    viewportElement.scrollLeft +
    viewportElement.clientWidth -
    PDF_SCROLL_TARGET_INLINE_HEADROOM;

  if (areaLeft < visibleLeft) {
    return Math.max(0, areaLeft - PDF_SCROLL_TARGET_INLINE_HEADROOM);
  }
  if (areaRight > visibleRight) {
    return Math.max(
      0,
      areaRight -
        viewportElement.clientWidth +
        PDF_SCROLL_TARGET_INLINE_HEADROOM,
    );
  }
  return viewportElement.scrollLeft;
}

function normalizeOptionalPercent(value: number | undefined) {
  if (value == null || !Number.isFinite(value)) return undefined;
  return clamp(value, 0, 100);
}

function createPdfDocumentLayoutModel({
  isTransitioning,
  layout,
  transition,
}: {
  isTransitioning: boolean;
  layout: PdfPageLayoutModel;
  transition?: ViewerDocumentTransition;
}): PdfDocumentLayoutModel {
  const documentTransition: ViewerDocumentTransition =
    transition ??
    (isTransitioning
      ? {
          layoutPolicy: "live",
          scrollPolicy: "preserve",
          source: "document-layout",
          transitionId: null,
          visualPolicy: "document-flip",
        }
      : {
          layoutPolicy: "live",
          scrollPolicy: "preserve",
          source: "none",
          transitionId: null,
          visualPolicy: "none",
        });

  return {
    blockSize: layout.totalHeight,
    captureReadingAnchor: (input) => capturePdfReadingAnchor(layout, input),
    getReadingAnchorScrollTop: (target) =>
      getPdfReadingAnchorScrollTop(layout, target),
    inlineSize: layout.maxPageWidth,
    isTransitioning,
    transition: documentTransition,
  };
}

function capturePdfReadingAnchor(
  layout: PdfPageLayoutModel,
  {
    scrollTop,
    viewportBlockSize,
  }: {
    scrollTop: number;
    viewportBlockSize: number;
  },
): PdfReadingAnchor | null {
  if (layout.pageCount === 0) return null;
  if (scrollTop <= 0) return { kind: "top" };

  const anchorOffset = scrollTop + getPdfReadingAnchorOffset(viewportBlockSize);
  const pageNumber = findPdfPageByOffset(layout, anchorOffset);
  const pageLayout = getPdfPageLayout(layout, pageNumber);
  if (!pageLayout || pageLayout.height <= 0) return null;

  const markerOffset = getPdfReadingAnchorOffset(viewportBlockSize);
  const pageTopInViewport = pageLayout.offsetTop - scrollTop;
  const boundarySnap = Math.min(markerOffset, PDF_READING_BOUNDARY_SNAP_PX);
  if (Math.abs(pageTopInViewport) <= boundarySnap) {
    return {
      kind: "page-boundary",
      pageNumber,
      topInViewport: snapPdfReadingBoundaryOffset(pageTopInViewport),
    };
  }

  return {
    kind: "page",
    pageNumber,
    yPercent: clamp(
      (anchorOffset - pageLayout.offsetTop) / pageLayout.height,
      0,
      1,
    ),
  };
}

function getPdfReadingAnchorScrollTop(
  layout: PdfPageLayoutModel,
  {
    anchor,
    viewportBlockSize,
  }: {
    anchor: PdfReadingAnchor;
    viewportBlockSize: number;
  },
) {
  if (anchor.kind === "top") {
    return 0;
  }

  const pageLayout = getPdfPageLayout(layout, anchor.pageNumber);
  if (!pageLayout) return null;

  const maxScrollTop = Math.max(0, layout.totalHeight - viewportBlockSize);
  if (anchor.kind === "page-boundary") {
    return clamp(pageLayout.offsetTop - anchor.topInViewport, 0, maxScrollTop);
  }

  const targetTop =
    pageLayout.offsetTop +
    pageLayout.height * anchor.yPercent -
    getPdfReadingAnchorOffset(viewportBlockSize);
  return clamp(targetTop, 0, maxScrollTop);
}

function getPdfReadingAnchorOffset(viewportBlockSize: number) {
  return Math.max(0, viewportBlockSize * PDF_READING_MARKER_RATIO);
}

function snapPdfReadingBoundaryOffset(offset: number) {
  return Number.isFinite(offset) ? Math.round(offset) : 0;
}

function toPdfScrollMetrics(
  metrics: ViewerDocumentScrollMetrics,
): PdfScrollMetrics {
  return {
    physicalScrollHeight: metrics.physicalScrollSize,
    physicalScrollTop: metrics.physicalScrollTop,
    scrollPageOffset: metrics.scrollPageOffset,
    scrollTop: metrics.scrollTop,
    viewportHeight: metrics.viewportBlockSize,
  };
}

import * as React from "react";

import { useKeyedLayoutEffect } from "@/hooks/use-keyed-layout-effect";
import { useKeyedMountEffect } from "@/hooks/use-keyed-mount-effect";
import { useMountEffect } from "@/hooks/use-mount-effect";
import { joinEffectKey } from "@/lib/effect-key";

import type {
  ViewerDocumentLayoutModel,
  ViewerDocumentPhysicalScrollPosition,
  ViewerDocumentResolvedScrollTarget,
  ViewerDocumentScrollMapper,
  ViewerDocumentScrollMetrics,
  ViewerDocumentScrollTargetResolver,
} from "./viewer-types";
import { useViewerDocumentGeometryTransaction } from "./viewer-document-geometry";

const VIEWER_DOCUMENT_SCROLL_IDLE_MS = 120;
const VIEWER_DOCUMENT_SCROLL_POSITION_EPSILON = 1;
const VIEWER_DOCUMENT_SCROLL_RESTORE_MAX_FRAMES = 45;
const VIEWER_DOCUMENT_INTERNAL_SCROLL_SUPPRESS_MS = 120;

type ViewerDocumentScrollIntent<Target> =
  | {
      kind: "idle";
    }
  | {
      kind: "user";
    }
  | {
      behavior: ScrollBehavior;
      kind: "programmatic";
      sequence: number;
      target: Target;
      targetLeft?: number;
      targetTop: number;
    };

type PendingViewerDocumentScrollRestore = {
  attempts: number;
  options: ScrollToOptions;
  targetTop: number;
};

type ViewerDocumentScrollEventResult = {
  source: "internal" | "programmatic" | "user";
};

export function useViewerDocumentScroll<Anchor, Target>({
  copyScrollTarget,
  layout,
  resetKey,
  resolveScrollTarget,
  scrollMapper,
}: {
  copyScrollTarget?: (target: Target) => Target;
  layout: ViewerDocumentLayoutModel<Anchor>;
  resetKey?: unknown;
  resolveScrollTarget?: ViewerDocumentScrollTargetResolver<Anchor, Target>;
  scrollMapper: ViewerDocumentScrollMapper;
}) {
  const viewportElementRef = React.useRef<HTMLDivElement | null>(null);
  const scrollPageOffsetRef = React.useRef(0);
  const pendingScrollRestoreRef =
    React.useRef<PendingViewerDocumentScrollRestore | null>(null);
  const pendingScrollRestoreFrameRef = React.useRef(0);
  const flushPendingScrollRestoreRef = React.useRef<() => void>(() => {});
  const isInternalScrollWriteRef = React.useRef(false);
  const internalScrollWriteTimeoutRef = React.useRef<ReturnType<
    typeof setTimeout
  > | null>(null);
  const viewportResetKeyRef = React.useRef<unknown>(resetKey);
  const didMountResetEffectRef = React.useRef(false);
  const committedLayoutRef = React.useRef(layout);
  const committedResetKeyRef = React.useRef<unknown>(resetKey);
  const geometryTransaction = useViewerDocumentGeometryTransaction({
    layout,
    resetKey,
  });
  const {
    cacheAnchor,
    cacheReadingAnchor,
    cacheVisualLayerRect,
    cancel: cancelGeometryTransaction,
    classifyLayoutChange,
    commit,
    prepare,
    recordStableState,
    reset: resetGeometryTransaction,
  } = geometryTransaction;
  const scrollIntent = useViewerDocumentScrollIntentController<Target>();
  const [viewportElement, setViewportElementState] =
    React.useState<HTMLDivElement | null>(null);

  const cancelPendingScrollRestore = React.useCallback(() => {
    pendingScrollRestoreRef.current = null;
    if (pendingScrollRestoreFrameRef.current === 0) return;
    cancelAnimationFrame(pendingScrollRestoreFrameRef.current);
    pendingScrollRestoreFrameRef.current = 0;
  }, []);

  const clearInternalScrollWrite = React.useCallback(() => {
    isInternalScrollWriteRef.current = false;
    if (internalScrollWriteTimeoutRef.current === null) return;
    clearTimeout(internalScrollWriteTimeoutRef.current);
    internalScrollWriteTimeoutRef.current = null;
  }, []);

  const markInternalScrollWrite = React.useCallback(() => {
    isInternalScrollWriteRef.current = true;
    if (internalScrollWriteTimeoutRef.current !== null) {
      clearTimeout(internalScrollWriteTimeoutRef.current);
    }
    internalScrollWriteTimeoutRef.current = setTimeout(() => {
      internalScrollWriteTimeoutRef.current = null;
      isInternalScrollWriteRef.current = false;
    }, VIEWER_DOCUMENT_INTERNAL_SCROLL_SUPPRESS_MS);
  }, []);

  const resetViewportForKey = React.useCallback(
    (element: HTMLDivElement, key: unknown) => {
      cancelPendingScrollRestore();
      viewportResetKeyRef.current = key;
      scrollPageOffsetRef.current = 0;
      resetGeometryTransaction(element);
      scrollIntent.reset();
      markInternalScrollWrite();
      setViewportPhysicalScrollTop(element, 0);
      element.scrollTo?.({ top: 0, behavior: "auto" });
    },
    [
      cancelPendingScrollRestore,
      markInternalScrollWrite,
      resetGeometryTransaction,
      scrollIntent,
    ],
  );

  const setViewportElement = React.useCallback(
    (element: HTMLDivElement | null) => {
      viewportElementRef.current = element;
      if (element && !Object.is(viewportResetKeyRef.current, resetKey)) {
        resetViewportForKey(element, resetKey);
      }
      setViewportElementState(element);
    },
    [resetKey, resetViewportForKey],
  );

  const readScrollMetrics = React.useCallback(
    () =>
      readViewerDocumentScrollMetrics({
        layout,
        scrollMapper,
        scrollPageOffset: scrollPageOffsetRef.current,
        viewportElement: viewportElementRef.current,
      }),
    [layout, scrollMapper],
  );

  const syncViewportScrollPosition = React.useCallback(
    (viewportElement: HTMLDivElement, blockSize = layout.blockSize) => {
      const metrics = readViewerDocumentScrollMetrics({
        layout: {
          ...layout,
          blockSize,
        },
        scrollMapper,
        scrollPageOffset: scrollPageOffsetRef.current,
        viewportElement,
      });

      if (metrics.physicalScrollSize >= blockSize) {
        const nextMetrics = {
          ...metrics,
          scrollPageOffset: hasViewerDocumentScrollPageOffset(
            scrollPageOffsetRef.current,
          )
            ? metrics.scrollPageOffset
            : 0,
        };
        scrollPageOffsetRef.current = nextMetrics.scrollPageOffset;
        cacheReadingAnchor(nextMetrics);
        cacheVisualLayerRect(viewportElement);
        return nextMetrics;
      }

      const position = scrollMapper.resolvePhysicalScrollPosition({
        blockSize,
        logicalScrollTop: metrics.scrollTop,
        scrollPageOffset: metrics.scrollPageOffset,
        viewportBlockSize: metrics.viewportBlockSize,
      });
      scrollPageOffsetRef.current = position.scrollPageOffset;
      markInternalScrollWrite();
      setViewportPhysicalScrollTop(viewportElement, position.physicalScrollTop);

      const nextMetrics = {
        ...metrics,
        physicalScrollTop: position.physicalScrollTop,
        scrollPageOffset: position.scrollPageOffset,
      };
      cacheReadingAnchor(nextMetrics);
      cacheVisualLayerRect(viewportElement);
      return nextMetrics;
    },
    [
      cacheReadingAnchor,
      cacheVisualLayerRect,
      layout,
      markInternalScrollWrite,
      scrollMapper,
    ],
  );

  const syncScrollPosition = React.useCallback(() => {
    const viewportElement = viewportElementRef.current;
    return viewportElement ? syncViewportScrollPosition(viewportElement) : null;
  }, [syncViewportScrollPosition]);

  const schedulePendingScrollRestore = React.useCallback(
    (restore: PendingViewerDocumentScrollRestore) => {
      pendingScrollRestoreRef.current = restore;
      if (pendingScrollRestoreFrameRef.current !== 0) return;
      pendingScrollRestoreFrameRef.current = requestAnimationFrame(() => {
        pendingScrollRestoreFrameRef.current = 0;
        flushPendingScrollRestoreRef.current();
      });
    },
    [],
  );

  const resolveLogicalScrollPosition = React.useCallback(
    (viewportElement: HTMLDivElement, targetTop: number) => {
      const viewportBlockSize = viewportElement.clientHeight;
      const position = scrollMapper.resolvePhysicalScrollPosition({
        blockSize: layout.blockSize,
        logicalScrollTop: targetTop,
        scrollPageOffset: scrollPageOffsetRef.current,
        viewportBlockSize,
      });
      const expectedPhysicalScrollSize = scrollMapper.getPhysicalScrollSize({
        blockSize: layout.blockSize,
        viewportBlockSize,
      });

      return {
        expectedMaxPhysicalScrollTop: Math.max(
          0,
          expectedPhysicalScrollSize - viewportBlockSize,
        ),
        position,
      };
    },
    [layout.blockSize, scrollMapper],
  );

  const applyLogicalScrollTop = React.useCallback(
    (
      viewportElement: HTMLDivElement,
      targetTop: number,
      options: ScrollToOptions,
      {
        allowDefer,
        preservePhysicalScrollTop = false,
      }: { allowDefer: boolean; preservePhysicalScrollTop?: boolean },
    ) => {
      if (preservePhysicalScrollTop) {
        scrollPageOffsetRef.current = targetTop - viewportElement.scrollTop;
        cacheReadingAnchor({
          scrollTop: targetTop,
          viewportBlockSize: viewportElement.clientHeight,
        });
        cacheVisualLayerRect(viewportElement);
        return true;
      }

      const { expectedMaxPhysicalScrollTop, position } =
        resolveLogicalScrollPosition(viewportElement, targetTop);
      const currentMaxPhysicalScrollTop =
        getViewportMaxPhysicalScrollTop(viewportElement);
      const shouldDefer =
        allowDefer &&
        position.physicalScrollTop >
          currentMaxPhysicalScrollTop +
            VIEWER_DOCUMENT_SCROLL_POSITION_EPSILON &&
        position.physicalScrollTop <=
          expectedMaxPhysicalScrollTop +
            VIEWER_DOCUMENT_SCROLL_POSITION_EPSILON;

      if (shouldDefer) {
        schedulePendingScrollRestore({
          attempts: 0,
          options: {
            ...options,
            behavior: "auto",
          },
          targetTop,
        });
        return false;
      }

      scrollPageOffsetRef.current = position.scrollPageOffset;
      markInternalScrollWrite();
      scrollViewportToPhysicalTop(viewportElement, position.physicalScrollTop, {
        behavior: "auto",
        ...options,
      });
      return true;
    },
    [
      cacheReadingAnchor,
      cacheVisualLayerRect,
      markInternalScrollWrite,
      resolveLogicalScrollPosition,
      schedulePendingScrollRestore,
    ],
  );

  const flushPendingScrollRestore = React.useCallback(() => {
    const pendingRestore = pendingScrollRestoreRef.current;
    const viewportElement = viewportElementRef.current;
    if (!pendingRestore || !viewportElement) return;

    const { expectedMaxPhysicalScrollTop, position } =
      resolveLogicalScrollPosition(viewportElement, pendingRestore.targetTop);
    const currentMaxPhysicalScrollTop =
      getViewportMaxPhysicalScrollTop(viewportElement);
    const shouldWaitForRange =
      position.physicalScrollTop >
        currentMaxPhysicalScrollTop + VIEWER_DOCUMENT_SCROLL_POSITION_EPSILON &&
      position.physicalScrollTop <=
        expectedMaxPhysicalScrollTop +
          VIEWER_DOCUMENT_SCROLL_POSITION_EPSILON &&
      pendingRestore.attempts < VIEWER_DOCUMENT_SCROLL_RESTORE_MAX_FRAMES;

    if (shouldWaitForRange) {
      schedulePendingScrollRestore({
        ...pendingRestore,
        attempts: pendingRestore.attempts + 1,
      });
      return;
    }

    pendingScrollRestoreRef.current = null;
    scrollPageOffsetRef.current = position.scrollPageOffset;
    markInternalScrollWrite();
    scrollViewportToPhysicalTop(
      viewportElement,
      position.physicalScrollTop,
      pendingRestore.options,
    );
  }, [
    markInternalScrollWrite,
    resolveLogicalScrollPosition,
    schedulePendingScrollRestore,
  ]);

  useKeyedLayoutEffect(joinEffectKey([flushPendingScrollRestore]), () => {
    flushPendingScrollRestoreRef.current = flushPendingScrollRestore;
    flushPendingScrollRestore();
  });

  const materializeScrollPageOffset = React.useCallback(() => {
    const viewportElement = viewportElementRef.current;
    if (
      !viewportElement ||
      !hasViewerDocumentScrollPageOffset(scrollPageOffsetRef.current)
    ) {
      return;
    }

    const metrics = readViewerDocumentScrollMetrics({
      layout,
      scrollMapper,
      scrollPageOffset: scrollPageOffsetRef.current,
      viewportElement,
    });
    const position = scrollMapper.resolvePhysicalScrollPosition({
      blockSize: layout.blockSize,
      logicalScrollTop: metrics.scrollTop,
      scrollPageOffset: 0,
      viewportBlockSize: metrics.viewportBlockSize,
    });
    scrollPageOffsetRef.current = position.scrollPageOffset;
    markInternalScrollWrite();
    scrollViewportToPhysicalTop(viewportElement, position.physicalScrollTop, {
      behavior: "auto",
    });
    cacheReadingAnchor({
      scrollTop: metrics.scrollTop,
      viewportBlockSize: metrics.viewportBlockSize,
    });
    cacheVisualLayerRect(viewportElement);
  }, [
    cacheReadingAnchor,
    cacheVisualLayerRect,
    layout,
    markInternalScrollWrite,
    scrollMapper,
  ]);

  const scrollViewportToLogicalTop = React.useCallback(
    (
      viewportElement: HTMLDivElement,
      targetTop: number,
      options?: ScrollToOptions,
      behavior?: {
        preservePhysicalScrollTop?: boolean;
      },
    ) => {
      applyLogicalScrollTop(
        viewportElement,
        targetTop,
        {
          behavior: "auto",
          ...options,
        },
        {
          allowDefer: true,
          preservePhysicalScrollTop: behavior?.preservePhysicalScrollTop,
        },
      );
      cacheReadingAnchor({
        scrollTop: targetTop,
        viewportBlockSize: viewportElement.clientHeight,
      });
    },
    [applyLogicalScrollTop, cacheReadingAnchor],
  );

  const scrollViewportToResolvedTarget = React.useCallback(
    (
      viewportElement: HTMLDivElement,
      target: ViewerDocumentResolvedScrollTarget,
      options: ScrollToOptions,
    ) => {
      const physicalScrollSize = scrollMapper.getPhysicalScrollSize({
        blockSize: layout.blockSize,
        viewportBlockSize: viewportElement.clientHeight,
      });
      const position =
        physicalScrollSize < layout.blockSize
          ? scrollMapper.resolvePhysicalScrollPosition({
              blockSize: layout.blockSize,
              logicalScrollTop: target.top,
              scrollPageOffset: scrollPageOffsetRef.current,
              viewportBlockSize: viewportElement.clientHeight,
            })
          : {
              physicalScrollTop: Math.max(0, target.top),
              scrollPageOffset: 0,
            };
      scrollPageOffsetRef.current = position.scrollPageOffset;
      viewportElement.scrollTo({
        top: position.physicalScrollTop,
        ...(target.left == null ? null : { left: target.left }),
        ...options,
      });
    },
    [layout.blockSize, scrollMapper],
  );

  useKeyedLayoutEffect(
    joinEffectKey([
      copyScrollTarget,
      cacheAnchor,
      cacheReadingAnchor,
      cacheVisualLayerRect,
      classifyLayoutChange,
      commit,
      layout,
      prepare,
      recordStableState,
      resetKey,
      resetGeometryTransaction,
      resolveScrollTarget,
      scrollIntent,
      scrollMapper,
      scrollViewportToLogicalTop,
      scrollViewportToResolvedTarget,
      syncViewportScrollPosition,
    ]),
    () => {
      const previousLayout = committedLayoutRef.current;
      const previousResetKey = committedResetKeyRef.current;
      committedLayoutRef.current = layout;
      committedResetKeyRef.current = resetKey;

      const viewportElement = viewportElementRef.current;
      if (!viewportElement) return;

      const layoutChange = classifyLayoutChange({
        previousLayout,
        previousResetKey,
      });
      if (layoutChange === "reset") {
        resetGeometryTransaction(viewportElement);
        return;
      }

      const currentLogicalScrollTop = scrollMapper.getLogicalScrollTop({
        blockSize: layout.blockSize,
        physicalScrollTop: viewportElement.scrollTop,
        scrollPageOffset: scrollPageOffsetRef.current,
        viewportBlockSize: viewportElement.clientHeight,
      });
      if (layoutChange !== "geometry") {
        recordStableState({
          clearTransition:
            layoutChange === "metadata" && !layout.isTransitioning,
          scrollTop: currentLogicalScrollTop,
          viewportBlockSize: viewportElement.clientHeight,
          viewportElement,
        });
        return;
      }

      const activeIntent = scrollIntent.current();
      const transition = layout.transition;
      if (
        activeIntent.kind === "programmatic" &&
        resolveScrollTarget &&
        transition?.source !== "viewer-shell"
      ) {
        const metrics = syncViewportScrollPosition(viewportElement);
        const target = resolveScrollTarget({
          layout,
          scrollTop: metrics.scrollTop,
          target: activeIntent.target,
          viewportElement,
        });
        if (!target) return;

        const { intent, targetChanged } = scrollIntent.updateProgrammaticTarget(
          activeIntent,
          target,
        );

        if (targetChanged) {
          scrollViewportToResolvedTarget(viewportElement, target, {
            behavior: intent.behavior,
          });
          scrollIntent.scheduleProgrammaticCompletion(intent.sequence);
        }
        cacheVisualLayerRect(viewportElement);
        return;
      }

      const previousLogicalScrollTop = scrollMapper.getLogicalScrollTop({
        blockSize: previousLayout.blockSize,
        physicalScrollTop: viewportElement.scrollTop,
        scrollPageOffset: scrollPageOffsetRef.current,
        viewportBlockSize: viewportElement.clientHeight,
      });
      const viewportBlockSize = viewportElement.clientHeight;
      const transaction = prepare({
        previousLayout,
        scrollTop: previousLogicalScrollTop,
        viewportBlockSize,
      });
      if (!transaction) return;

      if (transaction.shouldRestoreScroll) {
        const targetTop = layout.getReadingAnchorScrollTop({
          anchor: transaction.anchor,
          viewportBlockSize: transaction.viewportBlockSize,
        });
        if (targetTop != null) {
          // Shell motions always rebase (commit-then-relax rebases scroll in
          // the slide-start commit), so the restore is a real scroll write.
          scrollViewportToLogicalTop(viewportElement, targetTop);
        } else {
          cacheAnchor({
            anchor: transaction.anchor,
            viewportBlockSize,
          });
        }
      } else {
        cacheAnchor({
          anchor: transaction.anchor,
          viewportBlockSize: transaction.viewportBlockSize,
        });
      }

      commit({
        transaction,
        viewportElement,
      });
    },
  );

  const handleScroll = React.useCallback((): ViewerDocumentScrollEventResult => {
    const viewportElement = viewportElementRef.current;
    if (viewportElement && isInternalScrollWriteRef.current) {
      const metrics = readScrollMetrics();
      cacheReadingAnchor(metrics);
      cacheVisualLayerRect(viewportElement);
      return { source: "internal" };
    }

    if (viewportElement) {
      syncViewportScrollPosition(viewportElement);
    }

    const activeIntent = scrollIntent.current();
    if (activeIntent.kind === "programmatic") {
      scrollIntent.scheduleProgrammaticCompletion(activeIntent.sequence);
      return { source: "programmatic" };
    } else {
      scrollIntent.markUser();
      return { source: "user" };
    }
  }, [
    cacheReadingAnchor,
    cacheVisualLayerRect,
    readScrollMetrics,
    scrollIntent,
    syncViewportScrollPosition,
  ]);

  const markUserScrollIntent = React.useCallback(() => {
    materializeScrollPageOffset();
    cancelPendingScrollRestore();
    scrollIntent.markUser();
  }, [cancelPendingScrollRestore, materializeScrollPageOffset, scrollIntent]);

  useKeyedMountEffect(joinEffectKey([resetKey, resetViewportForKey]), () => {
    if (!didMountResetEffectRef.current) {
      didMountResetEffectRef.current = true;
      return;
    }
    const viewportElement = viewportElementRef.current;
    if (viewportElement) {
      resetViewportForKey(viewportElement, resetKey);
    }
  });

  useKeyedMountEffect(
    joinEffectKey([markUserScrollIntent, scrollIntent, viewportElement]),
    () => {
      const viewportElement = viewportElementRef.current;
      if (!viewportElement) return;

      const handleScrollEnd = () => {
        const activeIntent = scrollIntent.current();
        if (activeIntent.kind === "programmatic") {
          scrollIntent.completeProgrammatic(activeIntent.sequence);
        } else {
          scrollIntent.reset();
        }
      };

      viewportElement.addEventListener?.("wheel", markUserScrollIntent, {
        passive: true,
      });
      viewportElement.addEventListener?.("touchstart", markUserScrollIntent, {
        passive: true,
      });
      viewportElement.addEventListener?.("pointerdown", markUserScrollIntent);
      viewportElement.addEventListener?.("keydown", markUserScrollIntent);
      viewportElement.addEventListener?.("scrollend", handleScrollEnd);

      return () => {
        viewportElement.removeEventListener?.("wheel", markUserScrollIntent);
        viewportElement.removeEventListener?.(
          "touchstart",
          markUserScrollIntent,
        );
        viewportElement.removeEventListener?.(
          "pointerdown",
          markUserScrollIntent,
        );
        viewportElement.removeEventListener?.("keydown", markUserScrollIntent);
        viewportElement.removeEventListener?.("scrollend", handleScrollEnd);
      };
    },
  );

  const scrollToTarget = React.useCallback(
    (target: Target, options?: ScrollToOptions) => {
      const viewportElement = viewportElementRef.current;
      const metrics = readScrollMetrics();
      const resolvedTarget =
        viewportElement && resolveScrollTarget
          ? resolveScrollTarget({
              layout,
              scrollTop: metrics.scrollTop,
              target,
              viewportElement,
            })
          : null;
      if (!viewportElement || !resolvedTarget) return;

      cancelPendingScrollRestore();
      const behavior = options?.behavior ?? "smooth";
      const intent = scrollIntent.startProgrammatic({
        behavior,
        copyScrollTarget,
        resolvedTarget,
        target,
      });
      scrollViewportToResolvedTarget(viewportElement, resolvedTarget, {
        behavior: "smooth",
        ...options,
      });
      scrollIntent.scheduleProgrammaticCompletion(intent.sequence);
    },
    [
      cancelPendingScrollRestore,
      copyScrollTarget,
      layout,
      readScrollMetrics,
      resolveScrollTarget,
      scrollIntent,
      scrollViewportToResolvedTarget,
    ],
  );
  const getViewportElement = React.useCallback(
    () => viewportElementRef.current,
    [],
  );

  useMountEffect(() => () => {
    clearInternalScrollWrite();
    cancelPendingScrollRestore();
    cancelGeometryTransaction();
    scrollIntent.clearProgrammaticTimeout();
  });

  return React.useMemo(
    () => ({
      getScrollMetrics: readScrollMetrics,
      getViewportElement,
      handleScroll,
      scrollToTarget,
      scrollViewportToLogicalTop,
      setViewportElement,
      syncScrollPosition,
      viewportElement,
    }),
    [
      getViewportElement,
      handleScroll,
      readScrollMetrics,
      scrollToTarget,
      scrollViewportToLogicalTop,
      setViewportElement,
      syncScrollPosition,
      viewportElement,
    ],
  );
}

function useViewerDocumentScrollIntentController<Target>() {
  const scrollIntentRef = React.useRef<ViewerDocumentScrollIntent<Target>>({
    kind: "idle",
  });
  const scrollIntentSequenceRef = React.useRef(0);
  const programmaticScrollIdleTimeoutRef = React.useRef<ReturnType<
    typeof setTimeout
  > | null>(null);

  const clearProgrammaticTimeout = React.useCallback(() => {
    if (programmaticScrollIdleTimeoutRef.current) {
      clearTimeout(programmaticScrollIdleTimeoutRef.current);
      programmaticScrollIdleTimeoutRef.current = null;
    }
  }, []);

  const reset = React.useCallback(() => {
    clearProgrammaticTimeout();
    scrollIntentRef.current = { kind: "idle" };
  }, [clearProgrammaticTimeout]);

  const completeProgrammatic = React.useCallback(
    (sequence: number) => {
      if (
        scrollIntentRef.current.kind === "programmatic" &&
        scrollIntentRef.current.sequence === sequence
      ) {
        scrollIntentRef.current = { kind: "idle" };
      }
      clearProgrammaticTimeout();
    },
    [clearProgrammaticTimeout],
  );

  const scheduleProgrammaticCompletion = React.useCallback(
    (sequence: number) => {
      clearProgrammaticTimeout();
      programmaticScrollIdleTimeoutRef.current = setTimeout(() => {
        completeProgrammatic(sequence);
      }, VIEWER_DOCUMENT_SCROLL_IDLE_MS);
    },
    [clearProgrammaticTimeout, completeProgrammatic],
  );

  const markUser = React.useCallback(() => {
    clearProgrammaticTimeout();
    scrollIntentRef.current = { kind: "user" };
  }, [clearProgrammaticTimeout]);

  const startProgrammatic = React.useCallback(
    ({
      behavior,
      copyScrollTarget,
      resolvedTarget,
      target,
    }: {
      behavior: ScrollBehavior;
      copyScrollTarget?: (target: Target) => Target;
      resolvedTarget: ViewerDocumentResolvedScrollTarget;
      target: Target;
    }) => {
      const sequence = scrollIntentSequenceRef.current + 1;
      scrollIntentSequenceRef.current = sequence;
      clearProgrammaticTimeout();

      const intent: Extract<
        ViewerDocumentScrollIntent<Target>,
        { kind: "programmatic" }
      > = {
        behavior,
        kind: "programmatic",
        sequence,
        target: copyScrollTarget ? copyScrollTarget(target) : target,
        targetLeft: resolvedTarget.left,
        targetTop: resolvedTarget.top,
      };
      scrollIntentRef.current = intent;
      return intent;
    },
    [clearProgrammaticTimeout],
  );

  const updateProgrammaticTarget = React.useCallback(
    (
      intent: Extract<
        ViewerDocumentScrollIntent<Target>,
        { kind: "programmatic" }
      >,
      target: ViewerDocumentResolvedScrollTarget,
    ) => {
      const targetChanged =
        Math.abs(intent.targetTop - target.top) >
          VIEWER_DOCUMENT_SCROLL_POSITION_EPSILON ||
        Math.abs((intent.targetLeft ?? 0) - (target.left ?? 0)) >
          VIEWER_DOCUMENT_SCROLL_POSITION_EPSILON;
      const nextIntent = {
        ...intent,
        targetLeft: target.left,
        targetTop: target.top,
      };
      scrollIntentRef.current = nextIntent;
      return { intent: nextIntent, targetChanged };
    },
    [],
  );

  useKeyedMountEffect(joinEffectKey([clearProgrammaticTimeout]), () => () => {
    clearProgrammaticTimeout();
  });

  return React.useMemo(
    () => ({
      clearProgrammaticTimeout,
      completeProgrammatic,
      current: () => scrollIntentRef.current,
      markUser,
      reset,
      scheduleProgrammaticCompletion,
      startProgrammatic,
      updateProgrammaticTarget,
    }),
    [
      clearProgrammaticTimeout,
      completeProgrammatic,
      markUser,
      reset,
      scheduleProgrammaticCompletion,
      startProgrammatic,
      updateProgrammaticTarget,
    ],
  );
}

function readViewerDocumentScrollMetrics<Anchor>({
  layout,
  scrollMapper,
  scrollPageOffset,
  viewportElement,
}: {
  layout: ViewerDocumentLayoutModel<Anchor>;
  scrollMapper: ViewerDocumentScrollMapper;
  scrollPageOffset: number;
  viewportElement: HTMLDivElement | null;
}): ViewerDocumentScrollMetrics {
  const viewportBlockSize = viewportElement?.clientHeight ?? 0;
  const physicalScrollTop = viewportElement?.scrollTop ?? 0;
  const physicalScrollSize = scrollMapper.getPhysicalScrollSize({
    blockSize: layout.blockSize,
    viewportBlockSize,
  });
  const isRebased = physicalScrollSize < layout.blockSize;
  const hasLogicalOffset = hasViewerDocumentScrollPageOffset(scrollPageOffset);
  const shouldUseLogicalOffset = isRebased || hasLogicalOffset;

  return {
    physicalScrollSize,
    physicalScrollTop,
    scrollPageOffset: shouldUseLogicalOffset ? scrollPageOffset : 0,
    scrollTop: shouldUseLogicalOffset
      ? scrollMapper.getLogicalScrollTop({
          blockSize: layout.blockSize,
          physicalScrollTop,
          scrollPageOffset,
          viewportBlockSize,
        })
      : Math.max(0, physicalScrollTop),
    viewportBlockSize,
  };
}

function hasViewerDocumentScrollPageOffset(scrollPageOffset: number) {
  return Math.abs(scrollPageOffset) > VIEWER_DOCUMENT_SCROLL_POSITION_EPSILON;
}

function scrollViewportToPhysicalTop(
  viewportElement: HTMLDivElement,
  targetTop: number,
  options: ScrollToOptions,
) {
  if (
    Math.abs(viewportElement.scrollTop - targetTop) <=
    VIEWER_DOCUMENT_SCROLL_POSITION_EPSILON
  ) {
    return;
  }

  if (typeof viewportElement.scrollTo === "function") {
    viewportElement.scrollTo({
      top: targetTop,
      ...options,
    });
    return;
  }

  setViewportPhysicalScrollTop(viewportElement, targetTop);
}

function getViewportMaxPhysicalScrollTop(viewportElement: HTMLDivElement) {
  return Math.max(
    0,
    viewportElement.scrollHeight - viewportElement.clientHeight,
  );
}

function setViewportPhysicalScrollTop(
  viewportElement: HTMLDivElement,
  targetTop: number,
) {
  if (
    Math.abs(viewportElement.scrollTop - targetTop) <=
    VIEWER_DOCUMENT_SCROLL_POSITION_EPSILON
  ) {
    return;
  }

  viewportElement.scrollTop = targetTop;
}

import * as React from "react";

import type {
  ViewerDocumentLayoutModel,
  ViewerDocumentTransition,
} from "./viewer-types";

const VIEWER_DOCUMENT_FLIP_LAYER_SELECTOR = "[data-viewer-document-flip-layer]";
const VIEWER_DOCUMENT_FLIP_TRANSITION_MS = 150;
const VIEWER_DOCUMENT_FLIP_TRANSITION_CLEANUP_MS =
  VIEWER_DOCUMENT_FLIP_TRANSITION_MS + 50;
const VIEWER_DOCUMENT_FLIP_EPSILON = 0.5;
const VIEWER_DOCUMENT_LAYOUT_EPSILON = 0.5;

type ViewerDocumentGeometryLayoutChange =
  | "geometry"
  | "metadata"
  | "reset"
  | "same";

type ViewerDocumentTransitionAnchor<Anchor> = {
  anchor: Anchor;
  transitionId: ViewerDocumentTransition["transitionId"];
  viewportBlockSize: number;
};

type ViewerDocumentReadingAnchor<Anchor> = {
  anchor: Anchor;
  resetKey: unknown;
  viewportBlockSize: number;
};

type ViewerDocumentFlipAnimation = {
  element: HTMLElement;
  frame: number;
  timeout: ReturnType<typeof setTimeout>;
};

export type ViewerDocumentGeometryTransaction<Anchor> = {
  anchor: Anchor;
  previousVisualLayerRect: DOMRectReadOnly | null;
  shouldAnimate: boolean;
  shouldRestoreScroll: boolean;
  viewportBlockSize: number;
};

export function useViewerDocumentGeometryTransaction<Anchor>({
  layout,
  resetKey,
}: {
  layout: ViewerDocumentLayoutModel<Anchor>;
  resetKey: unknown;
}) {
  const transitionAnchorRef =
    React.useRef<ViewerDocumentTransitionAnchor<Anchor> | null>(null);
  const readingAnchorRef =
    React.useRef<ViewerDocumentReadingAnchor<Anchor> | null>(null);
  const visualLayerRectRef = React.useRef<DOMRectReadOnly | null>(null);
  const flipAnimationRef = React.useRef<ViewerDocumentFlipAnimation | null>(
    null,
  );

  const cancel = React.useCallback(() => {
    cancelViewerDocumentFlipAnimation(flipAnimationRef.current);
    flipAnimationRef.current = null;
  }, []);

  const cacheVisualLayerRect = React.useCallback(
    (viewportElement: HTMLDivElement) => {
      if (flipAnimationRef.current) return;
      visualLayerRectRef.current =
        readViewerDocumentVisualLayerRect(viewportElement);
    },
    [],
  );

  const cacheReadingAnchor = React.useCallback(
    ({
      scrollTop,
      viewportBlockSize,
    }: {
      scrollTop: number;
      viewportBlockSize: number;
    }) => {
      const anchor = layout.captureReadingAnchor({
        scrollTop,
        viewportBlockSize,
      });
      readingAnchorRef.current = anchor
        ? {
            anchor,
            resetKey,
            viewportBlockSize,
          }
        : null;
      return anchor;
    },
    [layout, resetKey],
  );

  const classifyLayoutChange = React.useCallback(
    ({
      previousLayout,
      previousResetKey,
    }: {
      previousLayout: ViewerDocumentLayoutModel<Anchor>;
      previousResetKey: unknown;
    }): ViewerDocumentGeometryLayoutChange => {
      if (!Object.is(previousResetKey, resetKey)) return "reset";
      if (Object.is(previousLayout, layout)) return "same";
      if (!hasViewerDocumentLayoutGeometryChange(previousLayout, layout)) {
        return "metadata";
      }
      return "geometry";
    },
    [layout, resetKey],
  );

  const reset = React.useCallback(
    (viewportElement: HTMLDivElement) => {
      transitionAnchorRef.current = null;
      readingAnchorRef.current = null;
      cancel();
      cacheVisualLayerRect(viewportElement);
    },
    [cacheVisualLayerRect, cancel],
  );

  const recordStableState = React.useCallback(
    ({
      clearTransition = false,
      scrollTop,
      viewportBlockSize,
      viewportElement,
    }: {
      clearTransition?: boolean;
      scrollTop: number;
      viewportBlockSize: number;
      viewportElement: HTMLDivElement;
    }) => {
      if (clearTransition) transitionAnchorRef.current = null;
      const anchor = cacheReadingAnchor({ scrollTop, viewportBlockSize });
      if (anchor && shouldRetainViewerDocumentTransitionAnchor(layout)) {
        const transition = getViewerDocumentTransition(layout);
        transitionAnchorRef.current = {
          anchor,
          transitionId: transition.transitionId,
          viewportBlockSize,
        };
      }
      cacheVisualLayerRect(viewportElement);
    },
    [cacheReadingAnchor, cacheVisualLayerRect, layout],
  );

  const prepare = React.useCallback(
    ({
      previousLayout,
      scrollTop,
      viewportBlockSize,
    }: {
      previousLayout: ViewerDocumentLayoutModel<Anchor>;
      scrollTop: number;
      viewportBlockSize: number;
    }): ViewerDocumentGeometryTransaction<Anchor> | null => {
      const isLayoutTransition = isViewerDocumentLayoutTransition({
        layout,
        previousLayout,
      });
      const transition = resolveViewerDocumentTransition({
        layout,
        previousLayout,
      });
      const previousTransitionAnchor =
        getReusableViewerDocumentTransitionAnchor({
          anchor: transitionAnchorRef.current,
          transition,
        });
      const cachedReadingAnchor = Object.is(
        readingAnchorRef.current?.resetKey,
        resetKey,
      )
        ? readingAnchorRef.current
        : null;
      const shouldUseCachedShellTransitionAnchor =
        isLayoutTransition &&
        transition.source === "viewer-shell" &&
        transition.layoutPolicy === "target" &&
        Boolean(cachedReadingAnchor);
      const shouldCaptureLiveShellTransitionAnchor =
        isLayoutTransition &&
        transition.source === "viewer-shell" &&
        !previousTransitionAnchor &&
        !shouldUseCachedShellTransitionAnchor;
      const liveReadingAnchor = shouldCaptureLiveShellTransitionAnchor
        ? previousLayout.captureReadingAnchor({
            scrollTop,
            viewportBlockSize,
          })
        : null;
      const anchor =
        isLayoutTransition && previousTransitionAnchor
          ? previousTransitionAnchor.anchor
          : liveReadingAnchor
            ? liveReadingAnchor
            : isLayoutTransition && cachedReadingAnchor
              ? cachedReadingAnchor.anchor
              : previousLayout.captureReadingAnchor({
                  scrollTop,
                  viewportBlockSize,
                });
      if (!anchor) return null;

      const transactionViewportBlockSize =
        previousTransitionAnchor?.viewportBlockSize ??
        (liveReadingAnchor ? viewportBlockSize : null) ??
        cachedReadingAnchor?.viewportBlockSize ??
        viewportBlockSize;

      if (shouldRetainViewerDocumentTransitionAnchor(layout)) {
        transitionAnchorRef.current = {
          anchor,
          transitionId: transition.transitionId,
          viewportBlockSize: transactionViewportBlockSize,
        };
      } else {
        transitionAnchorRef.current = null;
      }

      return {
        anchor,
        previousVisualLayerRect: visualLayerRectRef.current,
        shouldAnimate:
          isLayoutTransition && transition.visualPolicy === "document-flip",
        // Every remaining scroll policy restores (rebase) or preserves through
        // an explicit restore target; nothing defers anymore.
        shouldRestoreScroll: true,
        viewportBlockSize: transactionViewportBlockSize,
      };
    },
    [layout, resetKey],
  );

  const cacheAnchor = React.useCallback(
    ({
      anchor,
      viewportBlockSize,
    }: {
      anchor: Anchor;
      viewportBlockSize: number;
    }) => {
      readingAnchorRef.current = {
        anchor,
        resetKey,
        viewportBlockSize,
      };
    },
    [resetKey],
  );

  const commit = React.useCallback(
    ({
      transaction,
      viewportElement,
    }: {
      transaction: ViewerDocumentGeometryTransaction<Anchor>;
      viewportElement: HTMLDivElement;
    }) => {
      visualLayerRectRef.current = playViewerDocumentFlipAnimation({
        animationRef: flipAnimationRef,
        enabled: transaction.shouldAnimate,
        previousRect: transaction.previousVisualLayerRect,
        viewportElement,
      });
    },
    [],
  );

  return React.useMemo(
    () => ({
      cacheAnchor,
      cacheReadingAnchor,
      cacheVisualLayerRect,
      cancel,
      classifyLayoutChange,
      commit,
      prepare,
      recordStableState,
      reset,
    }),
    [
      cacheAnchor,
      cacheReadingAnchor,
      cacheVisualLayerRect,
      cancel,
      classifyLayoutChange,
      commit,
      prepare,
      recordStableState,
      reset,
    ],
  );
}

const VIEWER_DOCUMENT_STABLE_TRANSITION: ViewerDocumentTransition = {
  layoutPolicy: "live",
  scrollPolicy: "preserve",
  source: "none",
  transitionId: null,
  visualPolicy: "none",
};

function getViewerDocumentTransition<Anchor>(
  layout: ViewerDocumentLayoutModel<Anchor>,
) {
  return layout.transition ?? VIEWER_DOCUMENT_STABLE_TRANSITION;
}

function isViewerDocumentLayoutTransition<Anchor>({
  layout,
  previousLayout,
}: {
  layout: ViewerDocumentLayoutModel<Anchor>;
  previousLayout: ViewerDocumentLayoutModel<Anchor>;
}) {
  return (
    previousLayout.isTransitioning === true ||
    layout.isTransitioning === true ||
    getViewerDocumentTransition(previousLayout).source !== "none" ||
    getViewerDocumentTransition(layout).source !== "none"
  );
}

function resolveViewerDocumentTransition<Anchor>({
  layout,
  previousLayout,
}: {
  layout: ViewerDocumentLayoutModel<Anchor>;
  previousLayout: ViewerDocumentLayoutModel<Anchor>;
}) {
  const transition = getViewerDocumentTransition(layout);
  if (transition.source !== "none") return transition;

  const previousTransition = getViewerDocumentTransition(previousLayout);
  if (previousTransition.source !== "none") return previousTransition;

  if (
    previousLayout.isTransitioning === true ||
    layout.isTransitioning === true
  ) {
    return {
      layoutPolicy: "live",
      scrollPolicy: "preserve",
      source: "document-layout",
      transitionId: null,
      visualPolicy: "document-flip",
    } satisfies ViewerDocumentTransition;
  }

  return VIEWER_DOCUMENT_STABLE_TRANSITION;
}

function shouldRetainViewerDocumentTransitionAnchor<Anchor>(
  layout: ViewerDocumentLayoutModel<Anchor>,
) {
  const transition = getViewerDocumentTransition(layout);
  return layout.isTransitioning === true;
}

function getReusableViewerDocumentTransitionAnchor<Anchor>({
  anchor,
  transition,
}: {
  anchor: ViewerDocumentTransitionAnchor<Anchor> | null;
  transition: ViewerDocumentTransition;
}) {
  if (!anchor) return null;
  if (transition.source === "viewer-shell") {
    return anchor.transitionId !== null &&
      transition.transitionId !== null &&
      Object.is(anchor.transitionId, transition.transitionId)
      ? anchor
      : null;
  }
  if (anchor.transitionId === null || transition.transitionId === null) {
    return anchor;
  }
  return Object.is(anchor.transitionId, transition.transitionId)
    ? anchor
    : null;
}

function playViewerDocumentFlipAnimation({
  animationRef,
  enabled,
  previousRect,
  viewportElement,
}: {
  animationRef: React.MutableRefObject<ViewerDocumentFlipAnimation | null>;
  enabled: boolean;
  previousRect: DOMRectReadOnly | null;
  viewportElement: HTMLDivElement;
}) {
  const visualLayer = findViewerDocumentVisualLayer(viewportElement);
  const currentRect = readElementRect(visualLayer);
  if (!currentRect) return null;

  if (
    !visualLayer ||
    !enabled ||
    !previousRect ||
    typeof requestAnimationFrame !== "function"
  ) {
    return currentRect;
  }

  const transform = getViewerDocumentFlipTransform({
    currentRect,
    previousRect,
  });
  if (!transform) return currentRect;

  cancelViewerDocumentFlipAnimation(animationRef.current);

  visualLayer.style.transition = "none";
  visualLayer.style.transformOrigin = "top left";
  visualLayer.style.transform = transform;
  visualLayer.style.willChange = "transform";

  const frame = requestAnimationFrame(() => {
    visualLayer.style.transition = `transform ${VIEWER_DOCUMENT_FLIP_TRANSITION_MS}ms linear`;
    visualLayer.style.transform = "translate3d(0px, 0px, 0px) scale(1, 1)";
  });
  const timeout = setTimeout(() => {
    if (animationRef.current?.element !== visualLayer) return;
    finishViewerDocumentFlipAnimation(visualLayer);
    animationRef.current = null;
  }, VIEWER_DOCUMENT_FLIP_TRANSITION_CLEANUP_MS);

  animationRef.current = {
    element: visualLayer,
    frame,
    timeout,
  };
  return currentRect;
}

function cancelViewerDocumentFlipAnimation(
  animation: ViewerDocumentFlipAnimation | null,
) {
  if (!animation) return;
  if (typeof cancelAnimationFrame === "function") {
    cancelAnimationFrame(animation.frame);
  }
  clearTimeout(animation.timeout);
  finishViewerDocumentFlipAnimation(animation.element);
}

function finishViewerDocumentFlipAnimation(element: HTMLElement) {
  element.style.transition = "";
  element.style.transform = "";
  element.style.transformOrigin = "";
  element.style.willChange = "";
}

function getViewerDocumentFlipTransform({
  currentRect,
  previousRect,
}: {
  currentRect: DOMRectReadOnly;
  previousRect: DOMRectReadOnly;
}) {
  if (
    previousRect.width <= 0 ||
    previousRect.height <= 0 ||
    currentRect.width <= 0 ||
    currentRect.height <= 0
  ) {
    return null;
  }

  const translateX = previousRect.left - currentRect.left;
  const translateY = previousRect.top - currentRect.top;
  const scaleX = previousRect.width / currentRect.width;
  const scaleY = previousRect.height / currentRect.height;
  const hasVisibleDelta =
    Math.abs(translateX) > VIEWER_DOCUMENT_FLIP_EPSILON ||
    Math.abs(translateY) > VIEWER_DOCUMENT_FLIP_EPSILON ||
    Math.abs(1 - scaleX) > 0.001 ||
    Math.abs(1 - scaleY) > 0.001;

  if (!hasVisibleDelta) return null;

  return `translate3d(${translateX}px, ${translateY}px, 0px) scale(${scaleX}, ${scaleY})`;
}

function hasViewerDocumentLayoutGeometryChange<Anchor>(
  previousLayout: ViewerDocumentLayoutModel<Anchor>,
  nextLayout: ViewerDocumentLayoutModel<Anchor>,
) {
  return (
    !areViewerDocumentLayoutSizesEqual(
      previousLayout.inlineSize,
      nextLayout.inlineSize,
    ) ||
    !areViewerDocumentLayoutSizesEqual(
      previousLayout.blockSize,
      nextLayout.blockSize,
    )
  );
}

function areViewerDocumentLayoutSizesEqual(previous: number, next: number) {
  return Math.abs(previous - next) < VIEWER_DOCUMENT_LAYOUT_EPSILON;
}

function readViewerDocumentVisualLayerRect(
  viewportElement: HTMLDivElement | null,
) {
  return readElementRect(findViewerDocumentVisualLayer(viewportElement));
}

function findViewerDocumentVisualLayer(viewportElement: HTMLDivElement | null) {
  if (!viewportElement || typeof viewportElement.querySelector !== "function") {
    return null;
  }

  return viewportElement.querySelector<HTMLElement>(
    VIEWER_DOCUMENT_FLIP_LAYER_SELECTOR,
  );
}

function readElementRect(element: HTMLElement | null | undefined) {
  if (!element || typeof element.getBoundingClientRect !== "function") {
    return null;
  }

  const rect = element.getBoundingClientRect();
  return rect.width > 0 && rect.height > 0 ? rect : null;
}

import type { PdfPageSize } from "./pdf-viewer-types";

// Base gap/padding at scale 1. The layout scales these with `displayScale`
// (see createPdfPageLayout) so the whole document is a single linear function
// of scale — page heights AND the space between them grow/shrink together.
// That linearity is what makes the fit-width sidebar transform reproduce the
// pre-toggle frame exactly (gaps included), and it makes zoom feel like a
// camera rather than pages drifting apart on a fixed grid.
export const PDF_PAGE_GAP = 16;
export const PDF_PAGE_PADDING = 16;
export const PDF_RENDER_FIT_PERFECTLY_OVERSCAN_PX =
  PDF_PAGE_GAP + PDF_PAGE_PADDING;
export const PDF_RENDER_WINDOW_OVERSCAN_PX = 1000;
export const PDF_VISIBLE_PAGE_OVERSCAN = 2;
export const PDF_PRELOAD_PAGE_OVERSCAN = 4;
export const PDF_SCROLL_REBASE_CONTAINER_PX = 12_000_000;
export const PDF_SCROLL_REBASE_TRIGGER_PX = 1_000_000;
export const PDF_SCROLL_REBASE_TARGET_PX = 2_000_000;
export const PDF_SCROLL_REBASE_TARGET_BOTTOM_PX =
  PDF_SCROLL_REBASE_CONTAINER_PX - PDF_SCROLL_REBASE_TARGET_PX;
export const PDF_SCROLL_REBASE_THRESHOLD_PX =
  PDF_SCROLL_REBASE_CONTAINER_PX - PDF_SCROLL_REBASE_TRIGGER_PX;

export type PdfPageLayout = {
  pageNumber: number;
  width: number;
  height: number;
  offsetTop: number;
};

export type PdfRenderedPageLayout = PdfPageLayout & {
  windowTop: number;
};

export type PdfRenderedPageWindow = {
  afterHeight: number;
  beforeHeight: number;
  height: number;
  pages: readonly PdfRenderedPageLayout[];
  stickyInset: number;
};

export type PdfRenderPixelWindow = {
  bottom: number;
  top: number;
};

export type PdfScrollRebasePosition = {
  physicalScrollTop: number;
  scrollPageOffset: number;
};

export type PdfMeasuredPageLayout = {
  pageNumber: number;
  width: number;
  height: number;
  heightDelta: number;
};

export type PdfPageLayoutModel = {
  pageCount: number;
  totalHeight: number;
  maxPageWidth: number;
  estimatedWidth: number;
  estimatedHeight: number;
  // Resolved (scaled) vertical spacing, so offset math reads the model rather
  // than re-deriving the scale.
  gap: number;
  padding: number;
  measuredPages: readonly PdfMeasuredPageLayout[];
  measuredPageByNumber: ReadonlyMap<number, PdfMeasuredPageLayout>;
  prefixHeightDeltas: readonly number[];
};

export function createPdfPageLayout({
  pageCount,
  defaultPageSize,
  pageSizeByNumber,
  scale,
  rotation,
}: {
  pageCount: number;
  defaultPageSize: PdfPageSize;
  pageSizeByNumber: ReadonlyMap<number, PdfPageSize>;
  scale: number;
  rotation: number;
}): PdfPageLayoutModel {
  // Rounded to whole pixels like the page dimensions, so offsets stay
  // integer. The sub-pixel rounding residual is absorbed by the model-based
  // reading anchor (which pins the transform to the visible page's actual
  // offset), exactly as page-height rounding already is.
  const gap = Math.round(PDF_PAGE_GAP * scale);
  const padding = Math.round(PDF_PAGE_PADDING * scale);
  const estimatedSize = getRenderedPageSize(defaultPageSize, scale, rotation);
  const measuredPages = Array.from(pageSizeByNumber.entries())
    .filter(([pageNumber]) => pageNumber >= 1 && pageNumber <= pageCount)
    .map(([pageNumber, pageSize]) => {
      const renderedSize = getRenderedPageSize(pageSize, scale, rotation);
      return {
        pageNumber,
        width: renderedSize.width,
        height: renderedSize.height,
        heightDelta: renderedSize.height - estimatedSize.height,
      };
    })
    .filter(
      (page) =>
        page.width !== estimatedSize.width ||
        page.height !== estimatedSize.height,
    )
    .sort((a, b) => a.pageNumber - b.pageNumber);

  const measuredPageByNumber = new Map(
    measuredPages.map((page) => [page.pageNumber, page]),
  );
  const prefixHeightDeltas: number[] = [];
  let totalHeightDelta = 0;
  let maxPageWidth = pageCount === 0 ? 0 : estimatedSize.width;

  for (const page of measuredPages) {
    totalHeightDelta += page.heightDelta;
    prefixHeightDeltas.push(totalHeightDelta);
    maxPageWidth = Math.max(maxPageWidth, page.width);
  }

  return {
    pageCount,
    totalHeight:
      pageCount === 0
        ? 0
        : padding * 2 +
          pageCount * estimatedSize.height +
          (pageCount - 1) * gap +
          totalHeightDelta,
    maxPageWidth,
    estimatedWidth: estimatedSize.width,
    estimatedHeight: estimatedSize.height,
    gap,
    padding,
    measuredPages,
    measuredPageByNumber,
    prefixHeightDeltas,
  };
}

export function getPdfPageLayout(
  layout: PdfPageLayoutModel,
  pageNumber: number,
): PdfPageLayout | undefined {
  if (pageNumber < 1 || pageNumber > layout.pageCount) return undefined;

  const measuredPage = layout.measuredPageByNumber.get(pageNumber);
  return {
    pageNumber,
    width: measuredPage?.width ?? layout.estimatedWidth,
    height: measuredPage?.height ?? layout.estimatedHeight,
    offsetTop: getPdfPageOffsetTop(layout, pageNumber),
  };
}

export function findPdfPageByOffset(
  layout: PdfPageLayoutModel,
  offset: number,
) {
  if (layout.pageCount === 0) return 1;

  let low = 1;
  let high = layout.pageCount;
  let match = 1;

  while (low <= high) {
    const mid = Math.floor((low + high) / 2);
    if (getPdfPageOffsetTop(layout, mid) <= offset) {
      match = mid;
      low = mid + 1;
    } else {
      high = mid - 1;
    }
  }

  return match;
}

export function getPdfVisiblePageNumbers({
  layout,
  scrollTop,
  viewportHeight,
  overscanPages = PDF_VISIBLE_PAGE_OVERSCAN,
}: {
  layout: PdfPageLayoutModel;
  scrollTop: number;
  viewportHeight: number;
  overscanPages?: number;
}) {
  if (layout.pageCount === 0) return [];

  return getPdfPageNumbersInRange({
    layout,
    startOffset: Math.max(0, scrollTop - viewportHeight),
    endOffset: scrollTop + viewportHeight * 2,
    overscanPages,
  });
}

export function getPdfRenderPageNumbers({
  fitPerfectly = false,
  fitPerfectlyOverscanPx = PDF_RENDER_FIT_PERFECTLY_OVERSCAN_PX,
  layout,
  overscanPx = PDF_RENDER_WINDOW_OVERSCAN_PX,
  scrollTop,
  viewportHeight,
}: {
  fitPerfectly?: boolean;
  fitPerfectlyOverscanPx?: number;
  layout: PdfPageLayoutModel;
  overscanPx?: number;
  scrollTop: number;
  viewportHeight: number;
}) {
  if (layout.pageCount === 0) return [];

  const window = createWindowFromScrollPosition({
    fitPerfectly,
    fitPerfectlyOverscanPx,
    overscanPx,
    scrollHeight: layout.totalHeight,
    scrollTop,
    viewportHeight,
  });

  return getPdfPageNumbersInRange({
    layout,
    startOffset: window.top,
    endOffset: window.bottom,
    overscanPages: 0,
  });
}

export function getPdfPreloadPageNumbers({
  layout,
  renderPageNumbers,
  overscanPages = PDF_PRELOAD_PAGE_OVERSCAN,
}: {
  layout: PdfPageLayoutModel;
  renderPageNumbers: readonly number[];
  overscanPages?: number;
}) {
  if (layout.pageCount === 0 || renderPageNumbers.length === 0) return [];

  const firstRenderPage = renderPageNumbers[0];
  const lastRenderPage = renderPageNumbers[renderPageNumbers.length - 1];
  const firstPage = Math.max(1, firstRenderPage - overscanPages);
  const lastPage = Math.min(layout.pageCount, lastRenderPage + overscanPages);

  return createPageNumberRange(firstPage, lastPage);
}

export function getPdfRenderedPageWindow({
  layout,
  pageNumbers,
  physicalScrollHeight = layout.totalHeight,
  scrollPageOffset = 0,
  viewportHeight,
}: {
  layout: PdfPageLayoutModel;
  pageNumbers: readonly number[];
  physicalScrollHeight?: number;
  scrollPageOffset?: number;
  viewportHeight: number;
}): PdfRenderedPageWindow | null {
  const pages = pageNumbers
    .map((pageNumber) => getPdfPageLayout(layout, pageNumber))
    .filter((page): page is PdfPageLayout => Boolean(page))
    .sort((a, b) => a.pageNumber - b.pageNumber);

  if (pages.length === 0) return null;

  const logicalBeforeHeight = pages[0].offsetTop;
  const windowBottom = Math.max(
    ...pages.map((page) => page.offsetTop + page.height),
  );
  const height = Math.max(0, windowBottom - logicalBeforeHeight);
  const beforeHeight = getPdfPagedLayoutTop({
    logicalTop: logicalBeforeHeight,
    scrollPageOffset,
    totalHeight: layout.totalHeight,
    viewportHeight,
  });
  const safeViewportHeight =
    Number.isFinite(viewportHeight) && viewportHeight > 0 ? viewportHeight : 0;
  const safePhysicalScrollHeight = Math.max(
    0,
    finiteNumber(physicalScrollHeight),
  );
  const stickyInset =
    safeViewportHeight > 0 ? -Math.max(0, height - safeViewportHeight) : 0;

  return {
    afterHeight: Math.max(0, safePhysicalScrollHeight - beforeHeight - height),
    beforeHeight,
    height,
    pages: pages.map((page) => ({
      ...page,
      windowTop: page.offsetTop - logicalBeforeHeight,
    })),
    stickyInset,
  };
}

export function createWindowFromScrollPosition({
  fitPerfectly = false,
  fitPerfectlyOverscanPx = 0,
  overscanPx,
  scrollHeight,
  scrollTop,
  viewportHeight,
}: {
  fitPerfectly?: boolean;
  fitPerfectlyOverscanPx?: number;
  overscanPx: number;
  scrollHeight: number;
  scrollTop: number;
  viewportHeight: number;
}): PdfRenderPixelWindow {
  const safeOverscanPx = safePadding(overscanPx);
  const safeScrollHeight = Math.max(0, finiteNumber(scrollHeight));
  const safeScrollTop = Math.max(0, finiteNumber(scrollTop));
  const safeViewportHeight = Math.max(0, finiteNumber(viewportHeight));
  const windowHeight = safeViewportHeight + safeOverscanPx * 2;
  const fitPerfectlyOverscan = safePadding(fitPerfectlyOverscanPx);
  const effectiveHeight = fitPerfectly
    ? safeViewportHeight + fitPerfectlyOverscan * 2
    : windowHeight;

  if (windowHeight >= safeScrollHeight || fitPerfectly) {
    const fitScrollTop = Math.min(safeScrollTop, safeScrollHeight);
    const top = Math.max(fitScrollTop - fitPerfectlyOverscan, 0);
    const bottom = Math.min(fitScrollTop + effectiveHeight, safeScrollHeight);
    return {
      bottom: Math.ceil(Math.max(bottom, top)),
      top: Math.floor(Math.max(0, top)),
    };
  }

  const scrollCenter = safeScrollTop + safeViewportHeight / 2;
  let top = scrollCenter - windowHeight / 2;
  let bottom = top + windowHeight;

  if (top < 0) {
    top = 0;
    bottom = windowHeight;
  }
  if (bottom > safeScrollHeight) {
    bottom = safeScrollHeight;
    top = safeScrollHeight - windowHeight;
  }

  return {
    bottom: Math.ceil(Math.max(bottom, top)),
    top: Math.floor(Math.max(0, top)),
  };
}

export function getPdfPhysicalScrollHeight({
  totalHeight,
  viewportHeight,
}: {
  totalHeight: number;
  viewportHeight: number;
}) {
  const safeTotalHeight = safeSize(totalHeight);
  return shouldRebasePdfScroll({ totalHeight: safeTotalHeight, viewportHeight })
    ? Math.min(safeTotalHeight, PDF_SCROLL_REBASE_CONTAINER_PX)
    : safeTotalHeight;
}

export function getPdfLogicalScrollTop({
  physicalScrollTop,
  scrollPageOffset,
  totalHeight,
  viewportHeight,
}: {
  physicalScrollTop: number;
  scrollPageOffset: number;
  totalHeight: number;
  viewportHeight: number;
}) {
  return clamp(
    finiteNumber(physicalScrollTop) + safePadding(scrollPageOffset),
    0,
    getPdfMaxLogicalScrollTop({ totalHeight, viewportHeight }),
  );
}

export function resolvePdfPhysicalScrollPosition({
  logicalScrollTop,
  scrollPageOffset,
  totalHeight,
  viewportHeight,
}: {
  logicalScrollTop: number;
  scrollPageOffset: number;
  totalHeight: number;
  viewportHeight: number;
}): PdfScrollRebasePosition {
  const safeLogicalScrollTop = clamp(
    finiteNumber(logicalScrollTop),
    0,
    getPdfMaxLogicalScrollTop({ totalHeight, viewportHeight }),
  );

  if (!shouldRebasePdfScroll({ totalHeight, viewportHeight })) {
    return {
      physicalScrollTop: clamp(
        safeLogicalScrollTop,
        0,
        getPdfMaxPhysicalScrollTop({ totalHeight, viewportHeight }),
      ),
      scrollPageOffset: 0,
    };
  }

  const currentPageOffset = clampPdfScrollPageOffset({
    scrollPageOffset,
    totalHeight,
    viewportHeight,
  });
  const physicalScrollTop = safeLogicalScrollTop - currentPageOffset;
  const maxPhysicalScrollTop = getPdfMaxPhysicalScrollTop({
    totalHeight,
    viewportHeight,
  });
  const maxPageOffset = getPdfMaxScrollPageOffset({
    totalHeight,
    viewportHeight,
  });
  const shouldMoveDown =
    physicalScrollTop > PDF_SCROLL_REBASE_THRESHOLD_PX &&
    currentPageOffset < maxPageOffset;
  const shouldMoveUp =
    physicalScrollTop < PDF_SCROLL_REBASE_TRIGGER_PX && currentPageOffset > 0;

  if (
    physicalScrollTop < 0 ||
    physicalScrollTop > maxPhysicalScrollTop ||
    shouldMoveDown ||
    shouldMoveUp
  ) {
    return resolvePdfScrollPageWindow({
      logicalScrollTop: safeLogicalScrollTop,
      preferredPhysicalScrollTop: shouldMoveUp
        ? Math.min(PDF_SCROLL_REBASE_TARGET_BOTTOM_PX, maxPhysicalScrollTop)
        : PDF_SCROLL_REBASE_TARGET_PX,
      totalHeight,
      viewportHeight,
    });
  }

  return {
    physicalScrollTop: roundPdfScrollPixel(
      clamp(physicalScrollTop, 0, maxPhysicalScrollTop),
    ),
    scrollPageOffset: currentPageOffset,
  };
}

export function getPdfPagedLayoutTop({
  logicalTop,
  scrollPageOffset,
  totalHeight,
  viewportHeight,
}: {
  logicalTop: number;
  scrollPageOffset: number;
  totalHeight: number;
  viewportHeight: number;
}) {
  const offset = finiteNumber(scrollPageOffset);
  if (
    Math.abs(offset) <= 0.001 &&
    !shouldRebasePdfScroll({ totalHeight, viewportHeight })
  ) {
    return finiteNumber(logicalTop);
  }
  return Math.max(0, finiteNumber(logicalTop) - offset);
}

function getPdfPageNumbersInRange({
  layout,
  startOffset,
  endOffset,
  overscanPages,
}: {
  layout: PdfPageLayoutModel;
  startOffset: number;
  endOffset: number;
  overscanPages: number;
}) {
  const safeStartOffset = Math.max(0, startOffset);
  const safeEndOffset = Math.max(safeStartOffset, endOffset);
  const firstVisiblePage = findPdfPageByOffset(layout, safeStartOffset);
  const lastVisiblePage = findPdfPageByOffset(layout, safeEndOffset);
  const firstPage = Math.max(1, firstVisiblePage - overscanPages);
  const lastPage = Math.min(layout.pageCount, lastVisiblePage + overscanPages);

  return createPageNumberRange(firstPage, lastPage);
}

function shouldRebasePdfScroll({
  totalHeight,
  viewportHeight,
}: {
  totalHeight: number;
  viewportHeight: number;
}) {
  return (
    getPdfMaxLogicalScrollTop({ totalHeight, viewportHeight }) >
    PDF_SCROLL_REBASE_THRESHOLD_PX
  );
}

function getPdfMaxLogicalScrollTop({
  totalHeight,
  viewportHeight,
}: {
  totalHeight: number;
  viewportHeight: number;
}) {
  return Math.max(
    safeSize(totalHeight) - Math.max(0, finiteNumber(viewportHeight)),
    0,
  );
}

function getPdfMaxPhysicalScrollTop({
  totalHeight,
  viewportHeight,
}: {
  totalHeight: number;
  viewportHeight: number;
}) {
  return Math.max(
    getPdfPhysicalScrollHeight({ totalHeight, viewportHeight }) -
      Math.max(0, finiteNumber(viewportHeight)),
    0,
  );
}

function getPdfMaxScrollPageOffset({
  totalHeight,
  viewportHeight,
}: {
  totalHeight: number;
  viewportHeight: number;
}) {
  return Math.max(
    getPdfMaxLogicalScrollTop({ totalHeight, viewportHeight }) -
      getPdfMaxPhysicalScrollTop({ totalHeight, viewportHeight }),
    0,
  );
}

function clampPdfScrollPageOffset({
  scrollPageOffset,
  totalHeight,
  viewportHeight,
}: {
  scrollPageOffset: number;
  totalHeight: number;
  viewportHeight: number;
}) {
  return clamp(
    safePadding(scrollPageOffset),
    0,
    getPdfMaxScrollPageOffset({ totalHeight, viewportHeight }),
  );
}

function resolvePdfScrollPageWindow({
  logicalScrollTop,
  preferredPhysicalScrollTop,
  totalHeight,
  viewportHeight,
}: {
  logicalScrollTop: number;
  preferredPhysicalScrollTop: number;
  totalHeight: number;
  viewportHeight: number;
}): PdfScrollRebasePosition {
  let physicalScrollTop = roundPdfScrollPixel(
    clamp(
      finiteNumber(preferredPhysicalScrollTop),
      0,
      getPdfMaxPhysicalScrollTop({ totalHeight, viewportHeight }),
    ),
  );
  let scrollPageOffset = clampPdfScrollPageOffset({
    scrollPageOffset: logicalScrollTop - physicalScrollTop,
    totalHeight,
    viewportHeight,
  });

  physicalScrollTop = roundPdfScrollPixel(
    clamp(
      logicalScrollTop - scrollPageOffset,
      0,
      getPdfMaxPhysicalScrollTop({ totalHeight, viewportHeight }),
    ),
  );
  scrollPageOffset = clampPdfScrollPageOffset({
    scrollPageOffset: logicalScrollTop - physicalScrollTop,
    totalHeight,
    viewportHeight,
  });

  return { physicalScrollTop, scrollPageOffset };
}

function createPageNumberRange(firstPage: number, lastPage: number) {
  if (lastPage < firstPage) return [];

  return Array.from(
    { length: lastPage - firstPage + 1 },
    (_, index) => firstPage + index,
  );
}

function getRenderedPageSize(
  pageSize: PdfPageSize,
  scale: number,
  rotation: number,
) {
  const isRotated = rotation % 180 !== 0;
  return {
    width: Math.round((isRotated ? pageSize.height : pageSize.width) * scale),
    height: Math.round((isRotated ? pageSize.width : pageSize.height) * scale),
  };
}

function finiteNumber(value: number) {
  return Number.isFinite(value) ? value : 0;
}

function roundPdfScrollPixel(value: number) {
  if (typeof window === "undefined") return Math.round(value);
  const ratio = window.devicePixelRatio || 1;
  return Math.round(value * ratio) / ratio;
}

function safePadding(value: number) {
  return Number.isFinite(value) && value > 0 ? value : 0;
}

function safeSize(value: number) {
  return Number.isFinite(value) && value > 0 ? value : 0;
}

function clamp(value: number, min: number, max: number) {
  return Math.min(max, Math.max(min, value));
}

function getPdfPageOffsetTop(layout: PdfPageLayoutModel, pageNumber: number) {
  return (
    layout.padding +
    (pageNumber - 1) * (layout.estimatedHeight + layout.gap) +
    getHeightDeltaBeforePage(layout, pageNumber)
  );
}

function getHeightDeltaBeforePage(
  layout: PdfPageLayoutModel,
  pageNumber: number,
) {
  const measuredPageIndex = getLastMeasuredPageIndexBefore(layout, pageNumber);
  return measuredPageIndex < 0
    ? 0
    : layout.prefixHeightDeltas[measuredPageIndex];
}

function getLastMeasuredPageIndexBefore(
  layout: PdfPageLayoutModel,
  pageNumber: number,
) {
  let low = 0;
  let high = layout.measuredPages.length - 1;
  let match = -1;

  while (low <= high) {
    const mid = Math.floor((low + high) / 2);
    if (layout.measuredPages[mid].pageNumber < pageNumber) {
      match = mid;
      low = mid + 1;
    } else {
      high = mid - 1;
    }
  }

  return match;
}

import * as React from "react";
import { useMountEffect } from "@/hooks/use-mount-effect";

import {
  getPdfPreloadPageNumbers,
  getPdfRenderPageNumbers,
  getPdfVisiblePageNumbers,
  PDF_RENDER_WINDOW_OVERSCAN_PX,
  type PdfPageLayoutModel,
} from "./pdf-viewer-layout";
import type { ViewerDocumentTransition } from "./viewer-types";
import { useKeyedMountEffect } from "@/hooks/use-keyed-mount-effect";
import { useKeyedLayoutEffect } from "@/hooks/use-keyed-layout-effect";
import { joinEffectKey } from "@/lib/effect-key";

export const PDF_PAGE_WINDOW_RETENTION_MS = 250;

const PDF_SHELL_MOTION_RENDER_WINDOW_VIEWPORT_MULTIPLIER = 2;
const PDF_SHELL_MOTION_RENDER_WINDOW_PAGE_OVERSCAN = 3;

type PdfPageWindow = {
  scrollPageOffset: number;
  visiblePageNumbers: readonly number[];
  renderPageNumbers: readonly number[];
  warmPageNumbers: readonly number[];
  preloadPageNumbers: readonly number[];
};

export type PdfPageVirtualizationScrollMetrics = {
  scrollPageOffset: number;
  scrollTop: number;
  viewportHeight: number;
};

export function usePdfPageVirtualization({
  getScrollMetrics,
  isLayoutTransitioning = false,
  layout,
  resetKey,
  shouldHoldPageWindow = false,
  transition,
  viewportElement,
}: {
  getScrollMetrics?: () => PdfPageVirtualizationScrollMetrics;
  isLayoutTransitioning?: boolean;
  layout: PdfPageLayoutModel;
  resetKey?: unknown;
  shouldHoldPageWindow?: boolean;
  transition?: ViewerDocumentTransition;
  viewportElement: HTMLDivElement | null;
}) {
  const measureFrameRef = React.useRef(0);
  const retentionTimeoutRef = React.useRef<ReturnType<
    typeof setTimeout
  > | null>(null);
  const releasedRetentionLayoutRef = React.useRef<PdfPageLayoutModel | null>(
    null,
  );
  const hasMeasuredScrollRef = React.useRef(false);
  const lastMeasuredLayoutRef = React.useRef(layout);
  const lastMeasuredResetKeyRef = React.useRef<unknown>(resetKey);
  const lastMeasuredScrollTopRef = React.useRef(0);
  const hasReleasedPageWindowRetention =
    transition?.source === "viewer-shell" &&
    transition.layoutPolicy === "target" &&
    Object.is(releasedRetentionLayoutRef.current, layout);
  const shouldRetainPreviousPageWindow =
    (shouldHoldPageWindow ||
      shouldRetainPdfPageWindow({
        isLayoutTransitioning,
        transition,
      })) &&
    (!hasReleasedPageWindowRetention || shouldHoldPageWindow);
  const renderWindowTransition =
    transition?.source === "viewer-shell" &&
    (!hasReleasedPageWindowRetention || shouldHoldPageWindow)
      ? transition
      : undefined;
  const shouldFreezePreviousPageWindow =
    shouldHoldPageWindow || renderWindowTransition?.source === "viewer-shell";
  const getCurrentScrollMetrics =
    React.useCallback((): PdfPageVirtualizationScrollMetrics => {
      return Object.is(lastMeasuredResetKeyRef.current, resetKey) &&
        getScrollMetrics
        ? getScrollMetrics()
        : {
            scrollPageOffset: 0,
            scrollTop: Object.is(lastMeasuredResetKeyRef.current, resetKey)
              ? (viewportElement?.scrollTop ?? 0)
              : 0,
            viewportHeight: viewportElement?.clientHeight ?? 0,
          };
    }, [getScrollMetrics, resetKey, viewportElement]);
  const getPageWindow = React.useCallback(
    (
      metrics: PdfPageVirtualizationScrollMetrics,
      fitPerfectly = false,
      overscanPx = getPdfRenderWindowOverscanPx({
        layout,
        transition: renderWindowTransition,
        viewportHeight: metrics.viewportHeight,
      }),
    ): PdfPageWindow => {
      const renderPageNumbers = getPdfRenderPageNumbers({
        fitPerfectly,
        layout,
        overscanPx,
        scrollTop: metrics.scrollTop,
        viewportHeight: metrics.viewportHeight,
      });

      return {
        scrollPageOffset: metrics.scrollPageOffset,
        visiblePageNumbers: getPdfVisiblePageNumbers({
          layout,
          scrollTop: metrics.scrollTop,
          viewportHeight: metrics.viewportHeight,
        }),
        renderPageNumbers,
        warmPageNumbers: renderPageNumbers,
        preloadPageNumbers: getPdfPreloadPageNumbers({
          layout,
          renderPageNumbers,
        }),
      };
    },
    [layout, renderWindowTransition],
  );
  const getCurrentVisiblePageNumbers = React.useCallback((): PdfPageWindow => {
    return getPageWindow(getCurrentScrollMetrics());
  }, [getCurrentScrollMetrics, getPageWindow]);
  const getResetPageWindow = React.useCallback(() => {
    const viewportHeight = viewportElement?.clientHeight ?? 0;
    const renderPageNumbers = getPdfRenderPageNumbers({
      layout,
      scrollTop: 0,
      viewportHeight,
    });

    return {
      scrollPageOffset: 0,
      visiblePageNumbers: getPdfVisiblePageNumbers({
        layout,
        scrollTop: 0,
        viewportHeight,
      }),
      renderPageNumbers,
      warmPageNumbers: renderPageNumbers,
      preloadPageNumbers: getPdfPreloadPageNumbers({
        layout,
        renderPageNumbers,
      }),
    };
  }, [layout, viewportElement]);
  const [state, setState] = React.useState<{
    isTransitionPageWindow: boolean;
    layout: PdfPageLayoutModel;
    resetKey: unknown;
    pageWindow: PdfPageWindow;
  }>(() => ({
    isTransitionPageWindow: false,
    layout,
    resetKey,
    pageWindow: getCurrentVisiblePageNumbers(),
  }));
  const pageWindow =
    Object.is(state.layout, layout) && Object.is(state.resetKey, resetKey)
      ? state.isTransitionPageWindow && !shouldRetainPreviousPageWindow
        ? getCurrentVisiblePageNumbers()
        : state.pageWindow
      : Object.is(state.resetKey, resetKey)
        ? createTransitionPageWindow({
            currentPageWindow: getCurrentVisiblePageNumbers(),
            layout,
            previousPageWindow: state.pageWindow,
            shouldFreezePreviousPageWindow,
            shouldRetainPreviousPageWindow,
          })
        : getResetPageWindow();
  const cancelPageWindowRetentionRelease = React.useCallback(() => {
    if (retentionTimeoutRef.current === null) return;
    clearTimeout(retentionTimeoutRef.current);
    retentionTimeoutRef.current = null;
  }, []);
  const schedulePageWindowRetentionRelease = React.useCallback(() => {
    cancelPageWindowRetentionRelease();
    retentionTimeoutRef.current = setTimeout(() => {
      retentionTimeoutRef.current = null;
      const metrics = getCurrentScrollMetrics();
      const currentPageWindow = getPageWindow(
        metrics,
        false,
        PDF_RENDER_WINDOW_OVERSCAN_PX,
      );
      releasedRetentionLayoutRef.current = layout;
      lastMeasuredLayoutRef.current = layout;
      lastMeasuredResetKeyRef.current = resetKey;
      lastMeasuredScrollTopRef.current = metrics.scrollTop;
      hasMeasuredScrollRef.current = true;
      setState((previousState) => {
        if (!Object.is(previousState.resetKey, resetKey)) {
          return previousState;
        }

        return Object.is(previousState.layout, layout) &&
          !previousState.isTransitionPageWindow &&
          arePageWindowsEqual(previousState.pageWindow, currentPageWindow)
          ? previousState
          : {
              isTransitionPageWindow: false,
              layout,
              resetKey,
              pageWindow: currentPageWindow,
            };
      });
    }, PDF_PAGE_WINDOW_RETENTION_MS);
  }, [
    cancelPageWindowRetentionRelease,
    getCurrentScrollMetrics,
    getPageWindow,
    layout,
    resetKey,
  ]);

  const measureVisiblePagesNow = React.useCallback(() => {
    measureFrameRef.current = 0;
    const metrics = getCurrentScrollMetrics();
    const renderOverscanPx = getPdfRenderWindowOverscanPx({
      layout,
      transition: renderWindowTransition,
      viewportHeight: metrics.viewportHeight,
    });
    const fitPerfectly = shouldFitPdfPerfectly({
      canFitPerfectly:
        hasMeasuredScrollRef.current &&
        Object.is(lastMeasuredLayoutRef.current, layout) &&
        Object.is(lastMeasuredResetKeyRef.current, resetKey),
      previousScrollTop: lastMeasuredScrollTopRef.current,
      renderOverscanPx,
      scrollTop: metrics.scrollTop,
      viewportHeight: metrics.viewportHeight,
    });
    const currentPageWindow = getPageWindow(metrics, fitPerfectly);
    const hasScrollMovedSinceLastMeasurement =
      Math.abs(metrics.scrollTop - lastMeasuredScrollTopRef.current) > 1;
    const shouldBreakRetentionForScroll =
      hasScrollMovedSinceLastMeasurement &&
      shouldHoldPageWindow &&
      !isLayoutTransitioning &&
      renderWindowTransition?.source !== "viewer-shell";
    const shouldRetainMeasuredPageWindow =
      shouldRetainPreviousPageWindow && !shouldBreakRetentionForScroll;
    const shouldFreezeMeasuredPageWindow =
      shouldFreezePreviousPageWindow && !shouldBreakRetentionForScroll;
    lastMeasuredLayoutRef.current = layout;
    lastMeasuredResetKeyRef.current = resetKey;
    lastMeasuredScrollTopRef.current = metrics.scrollTop;
    hasMeasuredScrollRef.current = true;
    setState((previousState) => {
      const nextPageWindow = createTransitionPageWindow({
        currentPageWindow,
        layout,
        previousPageWindow: previousState.pageWindow,
        shouldFreezePreviousPageWindow: shouldFreezeMeasuredPageWindow,
        shouldRetainPreviousPageWindow: shouldRetainMeasuredPageWindow,
      });
      const isTransitionPageWindow = shouldRetainMeasuredPageWindow;

      return Object.is(previousState.layout, layout) &&
        Object.is(previousState.resetKey, resetKey) &&
        previousState.isTransitionPageWindow === isTransitionPageWindow &&
        arePageWindowsEqual(previousState.pageWindow, nextPageWindow)
        ? previousState
        : {
            isTransitionPageWindow,
            layout,
            resetKey,
            pageWindow: nextPageWindow,
          };
    });
    if (shouldHoldPageWindow) {
      cancelPageWindowRetentionRelease();
    } else if (
      shouldReleasePdfPageWindowRetention(transition) &&
      !hasReleasedPageWindowRetention
    ) {
      schedulePageWindowRetentionRelease();
    } else if (!shouldRetainPreviousPageWindow) {
      cancelPageWindowRetentionRelease();
    }
    if (fitPerfectly && measureFrameRef.current === 0) {
      measureFrameRef.current = requestAnimationFrame(() =>
        measureVisiblePagesNowRef.current(),
      );
    }
  }, [
    getCurrentScrollMetrics,
    getPageWindow,
    layout,
    resetKey,
    cancelPageWindowRetentionRelease,
    schedulePageWindowRetentionRelease,
    hasReleasedPageWindowRetention,
    isLayoutTransitioning,
    renderWindowTransition,
    shouldHoldPageWindow,
    shouldFreezePreviousPageWindow,
    shouldRetainPreviousPageWindow,
    transition,
  ]);
  const measureVisiblePagesNowRef = React.useRef(measureVisiblePagesNow);
  useKeyedLayoutEffect(joinEffectKey([measureVisiblePagesNow]), () => {
    measureVisiblePagesNowRef.current = measureVisiblePagesNow;
  });

  const measureVisiblePages = React.useCallback(() => {
    if (measureFrameRef.current) return;
    measureFrameRef.current = requestAnimationFrame(() =>
      measureVisiblePagesNowRef.current(),
    );
  }, []);

  useKeyedMountEffect(
    joinEffectKey([
      cancelPageWindowRetentionRelease,
      schedulePageWindowRetentionRelease,
      shouldHoldPageWindow,
      shouldRetainPreviousPageWindow,
      transition?.layoutPolicy,
      transition?.source,
    ]),
    () => {
      if (shouldHoldPageWindow) {
        cancelPageWindowRetentionRelease();
      } else if (
        shouldReleasePdfPageWindowRetention(transition) &&
        !hasReleasedPageWindowRetention
      ) {
        schedulePageWindowRetentionRelease();
      } else if (!shouldRetainPreviousPageWindow) {
        cancelPageWindowRetentionRelease();
      }
    },
  );

  useKeyedMountEffect(joinEffectKey([measureVisiblePagesNow]), () => {
    if (measureFrameRef.current) {
      cancelAnimationFrame(measureFrameRef.current);
      measureFrameRef.current = 0;
    }
    measureVisiblePagesNow();
  });

  useMountEffect(() => () => {
    if (measureFrameRef.current) {
      cancelAnimationFrame(measureFrameRef.current);
    }
    cancelPageWindowRetentionRelease();
  });

  return {
    scrollPageOffset: pageWindow.scrollPageOffset,
    visiblePageNumbers: pageWindow.visiblePageNumbers,
    renderPageNumbers: pageWindow.renderPageNumbers,
    warmPageNumbers: pageWindow.warmPageNumbers,
    preloadPageNumbers: pageWindow.preloadPageNumbers,
    measureVisiblePages,
  };
}

function createTransitionPageWindow({
  currentPageWindow,
  layout,
  previousPageWindow,
  shouldFreezePreviousPageWindow,
  shouldRetainPreviousPageWindow,
}: {
  currentPageWindow: PdfPageWindow;
  layout: PdfPageLayoutModel;
  previousPageWindow: PdfPageWindow;
  shouldFreezePreviousPageWindow: boolean;
  shouldRetainPreviousPageWindow: boolean;
}): PdfPageWindow {
  if (!shouldRetainPreviousPageWindow) return currentPageWindow;

  if (shouldFreezePreviousPageWindow) {
    return {
      scrollPageOffset: currentPageWindow.scrollPageOffset,
      visiblePageNumbers: previousPageWindow.visiblePageNumbers,
      renderPageNumbers: previousPageWindow.renderPageNumbers,
      warmPageNumbers: previousPageWindow.warmPageNumbers,
      preloadPageNumbers: previousPageWindow.preloadPageNumbers,
    };
  }

  return {
    scrollPageOffset: currentPageWindow.scrollPageOffset,
    visiblePageNumbers: mergePageNumbers(
      layout,
      previousPageWindow.visiblePageNumbers,
      currentPageWindow.visiblePageNumbers,
    ),
    renderPageNumbers: mergePageNumbers(
      layout,
      previousPageWindow.renderPageNumbers,
      currentPageWindow.renderPageNumbers,
    ),
    warmPageNumbers: mergePageNumbers(
      layout,
      previousPageWindow.warmPageNumbers,
      currentPageWindow.warmPageNumbers,
    ),
    preloadPageNumbers: mergePageNumbers(
      layout,
      previousPageWindow.preloadPageNumbers,
      currentPageWindow.preloadPageNumbers,
    ),
  };
}

function mergePageNumbers(
  layout: PdfPageLayoutModel,
  previousPageNumbers: readonly number[],
  currentPageNumbers: readonly number[],
) {
  return Array.from(new Set([...previousPageNumbers, ...currentPageNumbers]))
    .filter((pageNumber) => pageNumber >= 1 && pageNumber <= layout.pageCount)
    .sort((a, b) => a - b);
}

function arePageWindowsEqual(
  previousPageWindow: PdfPageWindow,
  nextPageWindow: PdfPageWindow,
) {
  return (
    previousPageWindow.scrollPageOffset === nextPageWindow.scrollPageOffset &&
    arePageNumbersEqual(
      previousPageWindow.visiblePageNumbers,
      nextPageWindow.visiblePageNumbers,
    ) &&
    arePageNumbersEqual(
      previousPageWindow.renderPageNumbers,
      nextPageWindow.renderPageNumbers,
    ) &&
    arePageNumbersEqual(
      previousPageWindow.warmPageNumbers,
      nextPageWindow.warmPageNumbers,
    ) &&
    arePageNumbersEqual(
      previousPageWindow.preloadPageNumbers,
      nextPageWindow.preloadPageNumbers,
    )
  );
}

function arePageNumbersEqual(
  previousPageNumbers: readonly number[],
  nextPageNumbers: readonly number[],
) {
  if (previousPageNumbers.length !== nextPageNumbers.length) return false;
  return previousPageNumbers.every(
    (pageNumber, index) => pageNumber === nextPageNumbers[index],
  );
}

function shouldFitPdfPerfectly({
  canFitPerfectly,
  previousScrollTop,
  renderOverscanPx,
  scrollTop,
  viewportHeight,
}: {
  canFitPerfectly: boolean;
  previousScrollTop: number;
  renderOverscanPx: number;
  scrollTop: number;
  viewportHeight: number;
}) {
  return (
    canFitPerfectly &&
    viewportHeight > 0 &&
    Math.abs(scrollTop - previousScrollTop) >
      viewportHeight + renderOverscanPx * 2
  );
}

function getPdfRenderWindowOverscanPx({
  layout,
  transition,
  viewportHeight,
}: {
  layout: PdfPageLayoutModel;
  transition?: ViewerDocumentTransition;
  viewportHeight: number;
}) {
  if (transition?.source !== "viewer-shell") {
    return PDF_RENDER_WINDOW_OVERSCAN_PX;
  }

  return Math.max(
    PDF_RENDER_WINDOW_OVERSCAN_PX,
    getSafePositiveNumber(viewportHeight) *
      PDF_SHELL_MOTION_RENDER_WINDOW_VIEWPORT_MULTIPLIER,
    getSafePositiveNumber(layout.estimatedHeight) *
      PDF_SHELL_MOTION_RENDER_WINDOW_PAGE_OVERSCAN,
  );
}

function shouldRetainPdfPageWindow({
  isLayoutTransitioning,
  transition,
}: {
  isLayoutTransitioning: boolean;
  transition?: ViewerDocumentTransition;
}) {
  return (
    isLayoutTransitioning ||
    (transition?.source === "viewer-shell" &&
      transition.layoutPolicy === "target")
  );
}

function shouldReleasePdfPageWindowRetention(
  transition?: ViewerDocumentTransition,
) {
  return (
    transition?.source === "viewer-shell" &&
    transition.layoutPolicy === "target"
  );
}

function getSafePositiveNumber(value: number) {
  return Number.isFinite(value) ? Math.max(0, value) : 0;
}

import * as React from "react";

import { useKeyedMountEffect } from "@/hooks/use-keyed-mount-effect";

import type { PdfPageSize } from "./pdf-viewer-types";
import { joinEffectKey } from "@/lib/effect-key";

export function usePdfPageSizes(resetKey: unknown) {
  const [state, setState] = React.useState<{
    resetKey: unknown;
    pageSizeByNumber: ReadonlyMap<number, PdfPageSize>;
  }>(() => ({ resetKey, pageSizeByNumber: new Map() }));

  const emptyPageSizeByNumber = React.useMemo<ReadonlyMap<number, PdfPageSize>>(
    () => new Map(),
    [],
  );
  const pageSizeByNumber = Object.is(state.resetKey, resetKey)
    ? state.pageSizeByNumber
    : emptyPageSizeByNumber;

  useKeyedMountEffect(joinEffectKey(["pdf-page-sizes", resetKey]), () => {
    setState((previousState) =>
      Object.is(previousState.resetKey, resetKey)
        ? previousState
        : { resetKey, pageSizeByNumber: new Map() },
    );
  });

  const setPageSizes = React.useCallback(
    (pageSizes: Iterable<readonly [number, PdfPageSize]>) => {
      setState((previousState) => {
        const previousPageSizeByNumber = Object.is(
          previousState.resetKey,
          resetKey,
        )
          ? previousState.pageSizeByNumber
          : emptyPageSizeByNumber;

        let nextPageSizeByNumber: Map<number, PdfPageSize> | null = null;
        for (const [pageNumber, size] of pageSizes) {
          const current = (
            nextPageSizeByNumber ?? previousPageSizeByNumber
          ).get(pageNumber);
          if (current?.width === size.width && current.height === size.height) {
            continue;
          }

          nextPageSizeByNumber ??= new Map(previousPageSizeByNumber);
          nextPageSizeByNumber.set(pageNumber, {
            width: size.width,
            height: size.height,
          });
        }

        if (!nextPageSizeByNumber) {
          return previousState;
        }
        return { resetKey, pageSizeByNumber: nextPageSizeByNumber };
      });
    },
    [emptyPageSizeByNumber, resetKey],
  );

  const setPageSize = React.useCallback(
    (pageNumber: number, size: PdfPageSize) => {
      setPageSizes([[pageNumber, size]]);
    },
    [setPageSizes],
  );

  return { pageSizeByNumber, setPageSize, setPageSizes };
}

import * as React from "react";

import { readPdfPageResource } from "@/lib/pdf-document-resource";
import type { PdfDocumentProxy } from "@/lib/pdf-document-types";

import { getPdfCanvasPixelSize } from "./pdf-viewer-canvas";
import {
  readPdfRenderedPageCache,
  readPdfRenderedPageCachePreview,
  writePdfRenderedPageCache,
  type PdfRenderedPageCache,
  type PdfRenderedPageSignature,
} from "./pdf-viewer-render-cache";
import { toPdfRenderFailedError } from "./pdf-viewer-render-error";
import type {
  PageOverlayProps,
  PdfPageRenderStatus,
  PdfPageRenderTiming,
  PdfPageSize,
} from "./pdf-viewer-types";
import { useKeyedMountEffect } from "@/hooks/use-keyed-mount-effect";
import { joinEffectKey } from "@/lib/effect-key";

type PdfRenderedPage = PdfRenderedPageSignature;
type PdfDocumentPage = ReturnType<typeof readPdfPageResource>;
type PdfViewportSize = {
  width: number;
  height: number;
};

type PdfPageProps = {
  document: PdfDocumentProxy;
  documentKey: string;
  pageNumber: number;
  scale: number;
  renderScale?: number;
  isLayoutTransitioning?: boolean;
  rotation: number;
  devicePixelRatio: number;
  renderCache?: PdfRenderedPageCache;
  renderOverlay?: (props: PageOverlayProps) => React.ReactNode;
  onRenderTiming?: (timing: PdfPageRenderTiming) => void;
  onSize?: (pageNumber: number, size: PdfPageSize) => void;
};

type PdfPageCanvasProps = {
  documentKey: string;
  page: PdfDocumentPage;
  pageNumber: number;
  renderScale: number;
  rotation: number;
  devicePixelRatio: number;
  renderCache?: PdfRenderedPageCache;
  onRenderTiming?: (timing: PdfPageRenderTiming) => void;
};

export const PdfPage = React.memo(function PdfPage({
  document,
  documentKey,
  pageNumber,
  scale,
  renderScale,
  isLayoutTransitioning,
  rotation,
  devicePixelRatio,
  renderCache,
  renderOverlay,
  onRenderTiming,
  onSize,
}: PdfPageProps) {
  const page = readPdfPageResource(document, pageNumber);
  const intrinsicViewport = React.useMemo(
    () => page.getViewport({ scale: 1, rotation: page.rotate ?? 0 }),
    [page],
  );

  useKeyedMountEffect(
    joinEffectKey([
      intrinsicViewport.height,
      intrinsicViewport.width,
      onSize,
      pageNumber,
    ]),
    () => {
      onSize?.(pageNumber, {
        width: intrinsicViewport.width,
        height: intrinsicViewport.height,
      });
    },
  );

  const displaySize = React.useMemo(
    () =>
      getPdfDisplayViewportSize({
        intrinsicViewport,
        rotation,
        scale,
      }),
    [intrinsicViewport, rotation, scale],
  );
  const resolvedRenderScale = renderScale ?? scale;

  return (
    <div
      className="ring-border relative shadow-sm ring-1"
      data-layout-transitioning={isLayoutTransitioning ? "" : undefined}
      style={{ width: displaySize.width, height: displaySize.height }}
      data-slot="pdf-page"
      data-page={pageNumber}
    >
      <PdfPageCanvas
        documentKey={documentKey}
        page={page}
        pageNumber={pageNumber}
        renderScale={resolvedRenderScale}
        rotation={rotation}
        devicePixelRatio={devicePixelRatio}
        renderCache={renderCache}
        onRenderTiming={onRenderTiming}
      />
      {renderOverlay ? (
        <div className="pointer-events-none absolute inset-0">
          {renderOverlay({
            pageNumber,
            width: displaySize.width,
            height: displaySize.height,
            scale,
            rotation,
          })}
        </div>
      ) : null}
    </div>
  );
}, arePdfPagePropsEqual);

const PdfPageCanvas = React.memo(function PdfPageCanvas({
  documentKey,
  page,
  pageNumber,
  renderScale,
  rotation,
  devicePixelRatio,
  renderCache,
  onRenderTiming,
}: PdfPageCanvasProps) {
  const renderViewport = React.useMemo(
    () =>
      page.getViewport({
        scale: renderScale,
        rotation: ((page.rotate ?? 0) + rotation) % 360,
      }),
    [page, renderScale, rotation],
  );
  const [renderError, setRenderError] = React.useState<unknown>(null);
  if (renderError) throw renderError;

  const renderedPageRef = React.useRef<PdfRenderedPage | null>(null);

  const canvasRef = React.useCallback(
    (canvas: HTMLCanvasElement | null) => {
      if (!canvas) return;
      const renderSignature = {
        documentKey,
        pageNumber,
        scale: renderScale,
        rotation,
        devicePixelRatio,
        viewportWidth: renderViewport.width,
        viewportHeight: renderViewport.height,
      } satisfies PdfRenderedPage;
      if (
        renderedPageRef.current &&
        doesRenderedPageSatisfyRequest(renderedPageRef.current, renderSignature)
      ) {
        return;
      }

      const startedAt = readNow();
      const reportRenderTiming = (
        status: PdfPageRenderStatus,
        source?: PdfPageRenderTiming["source"],
      ) => {
        onRenderTiming?.({
          pageNumber,
          scale: renderScale,
          rotation,
          devicePixelRatio,
          status,
          source,
          durationMs: Math.max(0, readNow() - startedAt),
        });
      };
      const context = canvas.getContext("2d");
      if (!context) {
        markCanvasRenderStatus(canvas, renderSignature, "failed");
        reportRenderTiming("failed");
        setRenderError(
          toPdfRenderFailedError(new Error("Canvas 2D context unavailable.")),
        );
        return;
      }

      const canvasWidth = getPdfCanvasPixelSize(
        renderSignature.viewportWidth,
        devicePixelRatio,
      );
      const canvasHeight = getPdfCanvasPixelSize(
        renderSignature.viewportHeight,
        devicePixelRatio,
      );
      const cachedPage = readPdfRenderedPageCache(renderCache, renderSignature);
      if (cachedPage) {
        replaceCanvasImage(
          canvas,
          context,
          cachedPage.canvas,
          canvasWidth,
          canvasHeight,
        );
        renderedPageRef.current = renderSignature;
        markCanvasRenderStatus(canvas, renderSignature, "rendered", "cache");
        reportRenderTiming("rendered", "cache");
        return;
      }

      const previewPage = readPdfRenderedPageCachePreview(
        renderCache,
        renderSignature,
      );
      const canKeepRenderedPageVisible =
        renderedPageRef.current !== null &&
        canRenderedPageStayVisibleWhilePending(
          renderedPageRef.current,
          renderSignature,
        );
      if (previewPage && !canKeepRenderedPageVisible) {
        replaceCanvasImage(
          canvas,
          context,
          previewPage.canvas,
          canvasWidth,
          canvasHeight,
        );
        markCanvasRenderStatus(
          canvas,
          renderSignature,
          "pending",
          "cache-preview",
        );
      } else if (!canKeepRenderedPageVisible) {
        resizeCanvas(canvas, canvasWidth, canvasHeight);
        markCanvasRenderStatus(canvas, renderSignature, "pending");
      } else {
        markCanvasRenderStatus(canvas, renderSignature, "pending");
      }

      const renderCanvas = canvas.ownerDocument.createElement("canvas");
      renderCanvas.width = canvasWidth;
      renderCanvas.height = canvasHeight;
      renderCanvas.style.width = `${renderViewport.width}px`;
      renderCanvas.style.height = `${renderViewport.height}px`;
      const renderContext = renderCanvas.getContext("2d");
      if (!renderContext) {
        markCanvasRenderStatus(canvas, renderSignature, "failed");
        reportRenderTiming("failed");
        setRenderError(
          toPdfRenderFailedError(new Error("Canvas 2D context unavailable.")),
        );
        return;
      }

      let renderTask: ReturnType<typeof page.render>;
      try {
        renderTask = page.render({
          canvas: renderCanvas,
          canvasContext: renderContext,
          viewport: renderViewport,
          transform:
            devicePixelRatio !== 1
              ? [devicePixelRatio, 0, 0, devicePixelRatio, 0, 0]
              : undefined,
        });
      } catch (error) {
        markCanvasRenderStatus(canvas, renderSignature, "failed");
        reportRenderTiming("failed");
        setRenderError(toPdfRenderFailedError(error));
        return;
      }
      let isActive = true;
      let didFinishPdfRender = false;
      renderTask.promise.then(
        () => {
          if (!isActive) return;
          didFinishPdfRender = true;
          replaceCanvasImage(
            canvas,
            context,
            renderCanvas,
            canvasWidth,
            canvasHeight,
          );
          renderedPageRef.current = renderSignature;
          writePdfRenderedPageCache({
            cache: renderCache,
            rendered: renderSignature,
            sourceCanvas: renderCanvas,
          });
          markCanvasRenderStatus(canvas, renderSignature, "rendered", "pdfjs");
          reportRenderTiming("rendered", "pdfjs");
        },
        (error) => {
          if (!isActive) return;
          didFinishPdfRender = true;
          markCanvasRenderStatus(canvas, renderSignature, "failed");
          reportRenderTiming("failed");
          setRenderError(toPdfRenderFailedError(error));
        },
      );
      return () => {
        isActive = false;
        if (!didFinishPdfRender) {
          renderTask.cancel();
        }
        if (!didFinishPdfRender) {
          markCanvasRenderStatus(canvas, renderSignature, "cancelled");
          reportRenderTiming("cancelled");
        }
      };
    },
    [
      devicePixelRatio,
      documentKey,
      onRenderTiming,
      page,
      pageNumber,
      renderCache,
      renderScale,
      renderViewport,
      rotation,
    ],
  );

  return (
    <canvas
      ref={canvasRef}
      style={{ width: "100%", height: "100%" }}
      className="block bg-white"
    />
  );
}, arePdfPageCanvasPropsEqual);

function arePdfPagePropsEqual(previous: PdfPageProps, next: PdfPageProps) {
  return (
    previous.document === next.document &&
    previous.documentKey === next.documentKey &&
    previous.pageNumber === next.pageNumber &&
    previous.scale === next.scale &&
    previous.renderScale === next.renderScale &&
    previous.isLayoutTransitioning === next.isLayoutTransitioning &&
    previous.rotation === next.rotation &&
    previous.devicePixelRatio === next.devicePixelRatio &&
    previous.renderCache === next.renderCache &&
    previous.renderOverlay === next.renderOverlay &&
    previous.onRenderTiming === next.onRenderTiming &&
    previous.onSize === next.onSize
  );
}

function arePdfPageCanvasPropsEqual(
  previous: PdfPageCanvasProps,
  next: PdfPageCanvasProps,
) {
  return (
    previous.documentKey === next.documentKey &&
    previous.page === next.page &&
    previous.pageNumber === next.pageNumber &&
    previous.renderScale === next.renderScale &&
    previous.rotation === next.rotation &&
    previous.devicePixelRatio === next.devicePixelRatio &&
    previous.renderCache === next.renderCache &&
    previous.onRenderTiming === next.onRenderTiming
  );
}

function getPdfDisplayViewportSize({
  intrinsicViewport,
  rotation,
  scale,
}: {
  intrinsicViewport: PdfViewportSize;
  rotation: number;
  scale: number;
}): PdfViewportSize {
  const isRotated = normalizePdfRotation(rotation) % 180 !== 0;
  return {
    width: Math.round(
      (isRotated ? intrinsicViewport.height : intrinsicViewport.width) * scale,
    ),
    height: Math.round(
      (isRotated ? intrinsicViewport.width : intrinsicViewport.height) * scale,
    ),
  };
}

function normalizePdfRotation(rotation: number) {
  return ((rotation % 360) + 360) % 360;
}

function resizeCanvas(
  canvas: HTMLCanvasElement,
  width: number,
  height: number,
) {
  if (canvas.width !== width) canvas.width = width;
  if (canvas.height !== height) canvas.height = height;
}

function drawCanvasImage(
  context: CanvasRenderingContext2D,
  image: HTMLCanvasElement,
  width: number,
  height: number,
) {
  if (typeof context.setTransform === "function") {
    context.setTransform(1, 0, 0, 1, 0, 0);
  }
  if (typeof context.drawImage === "function") {
    context.drawImage(image, 0, 0, width, height);
  }
}

function replaceCanvasImage(
  canvas: HTMLCanvasElement,
  context: CanvasRenderingContext2D,
  image: HTMLCanvasElement,
  width: number,
  height: number,
) {
  resizeCanvas(canvas, width, height);
  drawCanvasImage(context, image, width, height);
}

function markCanvasRenderStatus(
  canvas: HTMLCanvasElement,
  rendered: PdfRenderedPage,
  status: "pending" | PdfPageRenderStatus,
  source?: PdfPageRenderTiming["source"],
) {
  canvas.dataset.pdfPageNumber = String(rendered.pageNumber);
  canvas.dataset.pdfRenderStatus = status;
  if (source) {
    canvas.dataset.pdfRenderSource = source;
  } else {
    delete canvas.dataset.pdfRenderSource;
  }
}

function doesRenderedPageSatisfyRequest(
  rendered: PdfRenderedPage,
  requested: PdfRenderedPage,
) {
  return (
    rendered.documentKey === requested.documentKey &&
    rendered.pageNumber === requested.pageNumber &&
    rendered.rotation === requested.rotation &&
    rendered.scale >= requested.scale &&
    rendered.viewportWidth >= requested.viewportWidth &&
    rendered.viewportHeight >= requested.viewportHeight &&
    hasMatchingPageAspectRatio(rendered, requested) &&
    rendered.devicePixelRatio >= requested.devicePixelRatio
  );
}

function canRenderedPageStayVisibleWhilePending(
  rendered: PdfRenderedPage,
  requested: PdfRenderedPage,
) {
  return (
    rendered.documentKey === requested.documentKey &&
    rendered.pageNumber === requested.pageNumber &&
    rendered.rotation === requested.rotation &&
    hasMatchingPageAspectRatio(rendered, requested)
  );
}

function hasMatchingPageAspectRatio(
  rendered: PdfRenderedPage,
  requested: PdfRenderedPage,
) {
  const renderedRatio = rendered.viewportWidth / rendered.viewportHeight;
  const requestedRatio = requested.viewportWidth / requested.viewportHeight;
  return Math.abs(renderedRatio - requestedRatio) < 0.0001;
}

function readNow() {
  return typeof performance !== "undefined" ? performance.now() : Date.now();
}

export function getPdfCanvasPixelSize(
  cssSize: number,
  devicePixelRatio: number,
) {
  if (
    !Number.isFinite(cssSize) ||
    !Number.isFinite(devicePixelRatio) ||
    cssSize <= 0 ||
    devicePixelRatio <= 0
  ) {
    return 1;
  }
  return Math.max(1, Math.floor(cssSize * devicePixelRatio));
}

import { ViewerFormatError } from "@/lib/viewer-errors";

export function toPdfRenderFailedError(error: unknown) {
  return new ViewerFormatError({
    format: "pdf",
    kind: "render_failed",
    message: "Failed to render PDF page.",
    cause: error,
  });
}

